NAME = 'GerTafel: German Tafelbibel (1911)'
BOOK = 'Exodus'

CHAPTERS = {
    1: {
        1: 'Und dies sind die Namen der Söhne Israels, die mit Jakob nach Ägypten kamen. Ein Mann und sein Haus kamen sie.',
        2: 'Ruben, Simeon, Levi und Judah.',
        3: 'Isaschar, Sebulon und Benjamin.',
        4: 'Dan und Naphthali, Gad und Ascher.',
        5: 'Und es waren alle Seelen, die aus Jakobs Hüfte hervorgegangen, siebzig Seelen. Joseph aber war in Ägypten.',
        6: 'Und Joseph starb und alle seine Brüder und selbiges ganze Geschlecht.',
        7: 'Und die Söhne Israels waren fruchtbar und zeugten sich fort und mehrten sich und wurden sehr sehr zahlreich, und das Land ward angefüllt von ihnen.',
        8: 'Und es stand ein neuer König über Ägypten auf, der Joseph nicht kannte.',
        9: 'Und er sprach zu seinem Volke: Siehe, das Volk der Söhne Israels wird mehr und zahlreicher denn wir.',
        10: 'Wohlan, lasset uns weislich handeln gegen dasselbe, daß es nicht sich mehre und wenn uns Krieg begegne, sich auch zu unseren Hassern hinzutue, und wider uns streite und aus dem Lande hinaufziehe.',
        11: 'Und sie setzten Oberste der Fröner über dasselbe, um es durch Lasten zu bedrücken; und es baute dem Pharao die Vorratsstädte Pithon und Raamses.',
        12: 'Aber je mehr sie es bedrückten, desto mehr vermehrte es sich und brach es hervor, so daß ihnen die Söhne Israels zum Überdrusse wurden.',
        13: 'Und die Ägypter hielten die Söhne Israels zum Dienst an mit Strenge.',
        14: 'Und verbitterten ihnen ihr Leben mit hartem Dienst in Lehm und Ziegeln und in allerlei Dienst auf dem Feld, nebst all ihren Diensten, zu denen sie mit Strenge sie dienstbar machten.',
        15: 'Und der König Ägyptens sprach zu den Wehmüttern der Hebräerinnen, wovon der Name der einen war Schiphrah, und der Name der andern Puah.',
        16: 'Und er sprach: Wenn ihr die Hebräerinnen entbindet und sie auf den Geburtsstühlen sehet, wenn es ein Sohn ist, so tötet ihn, ist es aber eine Tochter, so mag sie leben.',
        17: 'Die Wehmütter aber fürchteten Gott und taten nicht wie der König von Ägypten zu ihnen geredet hatte und ließen die Knaben am Leben.',
        18: 'Und der König von Ägypten rief die Wehmütter und sprach zu ihnen: Warum habt ihr so getan und die Knaben am Leben gelassen?',
        19: 'Die Wehmütter aber sprachen zu Pharao: Weil die Hebräerinnen nicht sind wie die ägyptischen Weiber; denn sie sind lebhaft, ehe die Wehmutter zu ihnen kommt, da haben sie geboren.',
        20: 'Und Gott tat den Wehmüttern Gutes; und das Volk mehrte sich und ward sehr zahlreich.',
        21: 'Und es geschah, weil die Wehmütter Gott fürchteten, so machte er ihnen Häuser.',
        22: 'Und Pharao gebot all seinem Volk und sprach: Jeglichen Sohn, der geboren wird, werfet in den Strom, jede Tochter aber lasset leben.',
    },
    2: {
        1: 'Und ein Mann vom Hause Levi ging hin und nahm eine Tochter Levi.',
        2: 'Und das Weib empfing und gebar einen Sohn; und sie sah ihn, daß er gut war, und verbarg ihn drei Monate.',
        3: 'Und sie vermochte ihn nicht länger zu verbergen, und nahm ihm ein Kästlein von Binsen und verklebte es mit Erdharz und Pech, und legte das Kind hinein und legte es in das Schilf am Ufer des Stroms.',
        4: 'Und seine Schwester stellte sich von ferne, um zu erfahren, was mit ihm werden würde.',
        5: 'Und Pharaos Tochter kam herab an den Strom, um zu baden, und ihre Mädchen gingen am Rande des Stromes; und sie sah das Kästlein mitten im Schilf und sandte ihre Magd und ließ es holen.',
        6: 'Und sie öffnete es und sah das Kind, und siehe, der Junge weinte, und sie bemitleidete ihn und sprach: Es ist eines von den Kindern der Hebräer.',
        7: 'Und seine Schwester sprach zu der Tochter Pharaos: Soll ich gehen und dir ein säugendes Weib rufen von den Hebräerinnen, daß sie dir das Kind säuge?',
        8: 'Und die Tochter Pharaos sprach zu ihr: Geh hin! Und die Jungfrau ging und rief die Mutter des Kindes.',
        9: 'Und die Tochter Pharaos sprach zu ihr: Nimm dieses Kind und säuge mir es und ich will dir deinen Lohn geben. Und das Weib nahm das Kind und säugte es.',
        10: 'Und das Kind ward groß und sie brachte ihn zur Tochter des Pharao und er ward ihr zum Sohn, und sie nannte seinen Namen Mose; und sprach: Weil aus dem Wasser ich ihn habe gezogen.',
        11: 'Und es geschah in jenen Tagen, als Mose war groß geworden, daß er hinausging zu seinen Brüdern und ihre Lasten sah. Und er sah, wie ein ägyptischer Mann einen hebräischen Mann von seinen Brüdern schlug.',
        12: 'Und er wandte sich hin und her und sah, daß kein Mann da war, und schlug den Ägypter und verbarg ihn im Sande.',
        13: 'Und er ging am zweiten Tag aus und siehe, zwei hebräische Männer zankten sich. Und er sprach zu dem, der Unrecht hatte: Warum schlägst du deinen Genossen?',
        14: 'Und er sprach: Wer hat dich zum Manne, der Oberste und Richter über uns gesetzt? Sprichst du so, um mich auch zu erwürgen, wie du den Ägypter erwürgt hast? Und Mose fürchtete sich und sprach: So ist also die Sache bekannt geworden!',
        15: 'Und Pharao hörte diese Sache und er suchte den Mose zu erwürgen. Mose aber entfloh vor Pharao und wohnte im Lande Midian; und er wohnte bei einem Brunnen.',
        16: 'Und der Priester Midians hatte sieben Töchter. Und sie kamen und schöpften und füllten die Rinnen, um das Kleinvieh ihres Vaters zu tränken.',
        17: 'Und die Hirten kamen und trieben sie fort. Und Mose erhob sich und half ihnen und tränkte ihr Kleinvieh.',
        18: 'Und sie kamen zu ihrem Vater Reuel und er sprach: Warum kommet ihr heute so eilig nach Hause?',
        19: 'Und sie sagten: Ein ägyptischer Mann rettete uns aus der Hand der Hirten und hat uns auch geschöpft und das Kleinvieh getränkt.',
        20: 'Und er sprach zu seinen Töchtern: Und wo ist er? Warum habt ihr den Mann zurückgelassen? Ruft ihm, daß er Brot esse.',
        21: 'Und Mose war willens, bei dem Manne zu wohnen; und er gab dem Mose seine Tochter Zipporah.',
        22: 'Und sie gebar einen Sohn und er nannte seinen Namen Gerschom; denn er sprach: Ich war ein Fremdling in einem auswärtigen Lande.',
        23: 'Und es geschah nach vielen Tagen, daß der König von Ägypten starb. Und die Söhne Israels seufzten über ihre Knechtschaft und schrien und ihr Geschrei stieg auf zu Gott ob der Knechtschaft.',
        24: 'Und Gott hörte ihr Stöhnen und Gott gedachte seines Bundes mit Abraham, mit Isaak und mit Jakob.',
        25: 'Und Gott sah die Söhne Israels und Gott wußte es.',
    },
    3: {
        1: 'Und Mose weidete das Kleinvieh Jethros, seines Schwähers, des Priesters von Midian, und führte das Kleinvieh hinter die Wüste und kam zum Berge Gottes Horeb.',
        2: 'Und es erschien ihm der Engel Jehovahs in der Flamme des Feuers mitten aus dem Dornbusch; und er sah hin und siehe, der Dornbusch brannte mit Feuer; und der Dornbusch ward doch nicht verzehrt.',
        3: 'Und Mose sprach: Ich will doch ablenken und sehen dies große Gesicht, warum der Dornbusch nicht brennt.',
        4: 'Und Jehovah sah, daß er ablenkte zu sehen und Gott rief ihm mitten aus dem Dornbusche und sprach: Mose! Mose! Und er sprach: Hier bin ich!',
        5: 'Und Er sprach: Nahe dich nicht hierher! Zieh deine Schuhe von deinen Füßen; denn der Ort, auf dem du stehst, ist Boden der Heiligkeit!',
        6: 'Und sagte: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Und Mose verbarg sein Ange- sicht; denn er fürchtete sich, auf Gott zu blicken.',
        7: 'Und Jehovah sprach: Ich habe das Elend Meines Volkes in Ägypten gesehen und ihr Schreien gehört ob ihren Fronvögten; denn Ich kenne seine Schmerzen.',
        8: 'Und Ich bin herabgestiegen, es aus der Hand der Ägypter zu erretten, und es aus diesem Lande heraufzuführen in ein Land, gut und weit, in ein Land, das von Milch und Honig fließt, zum Orte der Kanaaniter und Chethiter und Amoriter und Pherisiter und Chiviter und Jebusiter.',
        9: 'Und nun siehe, das Geschrei, der Söhne Israels ist zu Mir gekommen und Ich habe auch den Druck gesehen, wie die Ägypter sie unterdrücken.',
        10: 'Und nun, gehe hin, und Ich sende dich zu Pharao; und bringe Mein Volk, die Söhne Israels aus Ägypten heraus.',
        11: 'Und Mose sprach zu Gott: Wer bin ich, daß ich zu Pharao ginge und die Söhne Israels aus Ägypten brächte?',
        12: 'Und Er sprach: Weil Ich mit dir sein werde; und dies soll das Zeichen sein, daß Ich dich gesandt habe: Wenn du das Volk aus Ägypten herausgebracht, werdet ihr an diesem Berge Gott dienen.',
        13: 'Und Mose sprach zu Gott: Siehe, wenn ich zu den Söhnen Israels komme und ihnen sage: Der Gott eurer Väter hat mich zu euch gesandt und sie zu mir sagen: Welches ist Sein Name, was soll ich zu ihnen sagen?',
        14: 'Und Gott sprach zu Mose: Ich bin, der Ich bin; und Er sprach: So sollst du zu den Söhnen Israels sprechen: Der Ich bin hat mich zu euch gesandt.',
        15: 'Und weiter sprach Gott zu Mose: So sollst du zu den Söhnen Israels sprechen: Jehovah, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs hat mich zu euch gesandt. Das ist Mein Name in Ewigkeit, und das ist Mein Gedächtnis zum Geschlecht des Geschlechts.',
        16: 'Geh und versammle die Ältesten Israels und sprich zu ihnen: Jehovah, der Gott eurer Väter ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, und hat gesagt: Ich habe euch heimgesucht und was euch in Ägyptenland getan worden ist.',
        17: 'Und Ich sage: Ich werde euch aus dem Elende Ägyptens in das Land der Kanaaniter und Chethiter und Amoriter und Pherisiter und Chiviter und Jebusiter in ein Land heraufbringen, das von Milch und Honig fließt.',
        18: 'Und hören sie auf deine Stimme, dann gehst du und die Ältesten Israels zum Könige von Ägypten, und ihr saget ihm: Jehovah, der Gott der Hebräer, ist uns begegnet, und nun laß uns doch drei Tagreisen in die Wüste ziehen, daß wir Jehovah, unserem Gotte, opfern.',
        19: 'Und Ich weiß, daß euch der König von Ägypten nicht wird ziehen lassen, auch nicht durch starke Hand.',
        20: 'Und Ich werde Meine Hand ausstrecken und Ägypten schlagen mit allen Meinen Wundern, die Ich in seiner Mitte tun werde; und danach wird er euch entlassen.',
        21: 'Und Ich werde diesem Volke Gnade in den Augen der Ägypter geben, und es wird geschehen, daß wenn ihr gehet, ihr nicht leer gehet.',
        22: 'Und ein jegliches Weib soll sich von ihrer Nachbarin und von ihrer Hausgenossin Gefäße von Silber und Gefäße von Gold und Gewänder erbeten, und ihr sollet sie auf eure Söhne und auf eure Töchter legen und den Ägyptern entreißen.',
    },
    4: {
        1: 'Und Mose antwortete und sprach: Aber siehe, sie werden mir nicht glauben und nicht auf meine Stimme hören; denn sie werden sagen: Jehovah ist dir nicht erschienen.',
        2: 'Und Jehovah sprach zu ihm: Was hast du in deiner Hand? Und er sprach: Einen Stab.',
        3: 'Und Er sprach: Wirf ihn zur Erde. Und er warf ihn zur Erde; und er ward zu einer Schlange und Mose floh vor ihr.',
        4: 'Und Jehovah sprach zu Mose: Strecke deine Hand aus und ergreife sie beim Schwanz. Und er streckte seine Hand aus und faßte sie fest; und sie ward zum Stab in seiner Hand:',
        5: 'Auf daß sie glauben, daß Jehovah, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, dir erschienen ist.',
        6: 'Und Jehovah sprach weiter zu ihm: Strecke doch deine Hand in deinen Busen. Und er streckte seine Hand in seinen Busen und zog sie heraus und siehe! seine Hand war aussätzig, wie Schnee.',
        7: 'Und Er sprach: Steck deine Hand zurück in deinen Busen. Und er steckte seine Hand zurück in seinen Busen und zog sie heraus aus seinem Busen, und siehe! sie ward wieder wie sein Fleisch.',
        8: 'Und es soll geschehen, wenn sie dir nicht glauben, noch auf die Stimme des ersten Zeichens hören, so werden sie der Stimme des nachfolgenden Zeichens glauben.',
        9: 'Und es soll geschehen, wenn sie auch diesen zwei Zeichen nicht glauben, noch auf deine Stimme hören, dann nimm von dem Wasser des Stromes und gieß es auf das Trockene, so wird das Wasser, das du aus dem Strom genommen, auf dem Trockenen zu Blut werden.',
        10: 'Und Mose sprach zu Jehovah: Ach, Herr, ich bin kein Mann von Worten, weder gestern, noch ehegestern, noch seit Du mit deinem Knechte redest; denn ich bin schwer von Mund und schwer von Zunge.',
        11: 'Und Jehovah sprach zu ihm: Wer macht des Menschen Mund? Oder wer macht stumm oder taub oder sehend oder blind? Bin nicht Ich es, Jehovah?',
        12: 'Und nun gehe und Ich will mit deinem Munde sein und dich unterweisen, was du reden sollst.',
        13: 'Und er sprach: Ach, Herr sende doch, durch wessen Hand du senden willst.',
        14: 'Und es entbrannte der Zorn Jehovahs wider Moses und Er sprach: Ist nicht Aharon, der Levite, dein Bruder? Ich weiß, daß er reden kann. Und siehe, er geht auch aus dir entgegen, und wird dich sehen und fröhlich sein in seinem Herzen.',
        15: 'Und du sollst zu ihm reden und die Worte in seinen Mund legen und Ich will mit deinem Munde und mit seinem Munde sein und euch unterweisen, was ihr tun sollt.',
        16: 'Und er soll für dich zum Volke reden, und es wird geschehen, daß er dein Mund ist und du ihm der Gott bist.',
        17: 'Und diesen Stab nimm in deine Hand, mit ihm sollst du die Zeichen tun.',
        18: 'Und Mose ging und kehrte zu Jethro, seinem Schwäher zurück und sprach zu ihm: Laß mich doch gehen, und zu meinen Brüdern, die in Ägypten sind, zurückkehren, auf daß ich sehe, ob sie noch leben. Und Jethro sprach zu Mose: Gehe hin im Frieden.',
        19: 'Und Jehovah sprach zu Mose in Midian: Gehe, kehre zurück nach Ägypten; denn gestorben sind alle die Männer, die dir nach deiner Seele trachteten.',
        20: 'Und Mose nahm sein Weib und seine Söhne und ließ sie auf dem Esel reiten, und kehrte nach Ägyptenland zurück, und Mose nahm den Stab Gottes in seine Hand.',
        21: 'Und Jehovah sprach zu Mose: Wenn du gehst, um nach Ägypten zurückzukehren, so siehe zu, daß du alle Wahrzeichen, die Ich in deine Hand gelegt habe, vor Pharao tust. Ich aber werde sein Herz bestärken, daß er das Volk nicht entläßt.',
        22: 'Und du sollst zu Pharao sprechen: Also spricht Jehovah: Mein Sohn, Mein Erstgeborener, ist Israel.',
        23: 'Und Ich sage dir: Entlasse Meinen Sohn, auf daß er Mir diene. Weigerst du dich aber, ihn zu entlassen, siehe, so erwürge Ich deinen Sohn, deinen Erstgeborenen.',
        24: 'Und es geschah auf dem Wege in dem Nachtlager, daß Jehovah auf ihn traf und trachtete ihn zu töten.',
        25: 'Und Zipporah nahm einen Stein und beschnitt die Vorhaut ihres Sohnes und ließ sie seine Füße berühren und sprach: Ein Bräutigam des Blutes bist du mir.',
        26: 'Und Er ließ von ihm ab; da sagte sie: Ein Bräutigam des Blutes um der Beschneidung willen.',
        27: 'Und Jehovah sprach zu Aharon: Geh Mose entgegen nach der Wüste. Und er ging und traf ihn auf dem Berge Gottes und küßte ihn.',
        28: 'Und Mose sagte dem Aharon an alle Worte Jehovahs, womit Er ihn gesendet und alle Zeichen, die Er ihm geboten.',
        29: 'Und Mose und Aharon gingen und sie versammelten alle Ältesten der Söhne Israels.',
        30: 'Und Aharon redete alle die Worte, die Jehovah zu Mose geredet hatte, und tat die Zeichen vor den Augen des Volkes.',
        31: 'Und das Volk glaubte; und sie hörten, daß Jehovah die Söhne Israels heimgesucht und ihr Elend gesehen; und sie verneigten und sie verbeugten sich.',
    },
    5: {
        1: 'Und danach kamen Mose und Aharon und sprachen zu Pharao: So spricht Jehovah, der Gott Israels: Entlasse Mein Volk, daß sie Mir ein Fest feiern in der Wüste.',
        2: 'Und Pharao sprach: Wer ist der Jehovah, auf Dessen Stimme ich hören soll, Israel zu entlassen? Ich kenne den Jehovah nicht und entlasse auch Israel nicht.',
        3: 'Und sie sprachen: Der Gott der Hebräer ist uns begegnet. Laß uns doch einen Weg von drei Tagreisen in die Wüste ziehen, daß wir Jehovah, unserem Gott, opfern, auf daß Er nicht mit Pest oder dem Schwerte auf uns stoße.',
        4: 'Und der König von Ägypten sprach zu ihnen: Warum wollt ihr, Mose und Aharon, das Volk von seinen Werken abwendig machen? Geht an eure Lasten!',
        5: 'Und Pharao sprach: Siehe, viel ist schon des Volkes im Lande und ihr wollt sie von ihren Lasten feiern lassen?',
        6: 'Und an jenem Tage gebot Pharao den Fronvögten im Volk und seinen Vorstehern, und sprach:',
        7: 'Gebet nicht ferner Stroh dem Volke zum Ziegelmachen, wie gestern und ehegestern. Lasset sie gehen und selber sich Stroh zusammenstoppeln.',
        8: 'Und das Maß der Ziegel, die sie gestern und ehegestern machten, leget ihnen auf, nehmet nichts weg davon. Lässig sind sie, deshalb schreien sie und sagen: Lasset uns gehen, daß wir unserem Gotte opfern.',
        9: 'Schwer sei der Dienst auf den Männern, und lasset sie ihn tun und nicht nach lügenhaften Worten schauen.',
        10: 'Und die Fronvögte des Volkes und seine Vorsteher gingen hinaus und sprachen zu dem Volk und sagten: So spricht Pharao: Ich gebe euch kein Stroh.',
        11: 'Gehet selber und nehmet euch Stroh, wo ihr es findet. Doch vom Dienst wird euch nichts abgezogen.',
        12: 'Und das Volk zerstreute sich im ganzen Land Ägypten, um Stoppeln für das Stroh zusammenzutragen.',
        13: 'Und die Fronvögte trieben sie an und sprachen: Vollendet euer Werk, das Tagewerk an seinem Tage, wie, da ihr Stroh hattet.',
        14: 'Und die Vorsteher der Söhne Israels, welche die Fronvögte Pharaos über sie gesetzt, wurden geschlagen, indem man sagte: Warum habt ihr nicht vollendet eure Satzung Ziegel zu machen wie gestern und ehegestern, weder gestern noch heute?',
        15: 'Und die Vorsteher der Söhne Israels kamen und schrien vor Pharao und sprachen: Warum tust du also deinen Knechten?',
        16: 'Stroh wird deinen Knechten keines gegeben, und sie sagen uns: Ihr habet Ziegel zu machen, und siehe, deine Knechte schlägt man, und dein Volk hat gesündigt.',
        17: 'Und er sprach: Lässig seid ihr, lässig, deshalb sprecht ihr: Lasset uns gehen und dem Jehovah opfern.',
        18: 'Und nun gehet und dienet; und Stroh wird euch keines gegeben; aber euer Maß Ziegel habt ihr zu geben.',
        19: 'Und die Vorsteher der Söhne Israels sahen, daß sie übel daran waren; denn man sagte: Ihr dürfet von euern Ziegeln nichts ablassen, vom Tagewerk an seinem Tage.',
        20: 'Und sie stießen auf Mose und Aharon, die sich ihnen gegenüberstellten, als sie von Pharao herauskamen;',
        21: 'Und sie sprachen zu ihnen: Jehovah sehe auf euch und richte. Ihr habt unseren Geruch stinkend gemacht in den Augen Pharaos und in den Augen seiner Knechte, um ihnen das Schwert in die Hand zu geben, uns zu erwürgen.',
        22: 'Und Mose kehrte zu Jehovah zurück und sprach: Herr, warum hast Du diesem Volk übel getan? Warum hast Du mich denn gesandt?',
        23: 'Und seitdem ich zu Pharao gekommen bin, um in Deinem Namen zu reden, hat er diesem Volke Böses getan, und Du hast Dein Volk nicht errettet.',
    },
    6: {
        1: 'Und Jehovah sprach zu Mose: Nun sollst du sehen, was Ich dem Pharao tun werde. Denn durch starke Hand soll er sie entlassen, und durch starke Hand sie aus seinem Lande forttreiben.',
        2: 'Und Gott redet zu Mose und sprach zu ihm: Ich bin Jehovah.',
        3: 'Und bin Abraham, Isaak und Jakob als Gott Schaddai erschienen, aber bei Meinem Namen Jehovah wurde Ich ihnen nicht bekannt.',
        4: 'Und habe auch Meinen Bund mit ihnen aufgerichtet, ihnen das Land Kanaan zu geben, das Land ihrer Wanderungen, in dem sie Fremdlinge waren.',
        5: 'Und Ich habe das Stöhnen der Söhne Israels gehört, welche die Ägypter knechten, und gedenke Meines Bundes.',
        6: 'Darum sprich zu den Söhnen Israels: Ich bin Jehovah, und Ich bringe euch von den Lasten der Ägypter heraus und errette euch aus ihrer Knechtschaft, mit ausgestrecktem Arm und mit großen Gerichten will Ich euch erlösen.',
        7: 'Und Ich nehme euch Mir zum Volk und werde euch Gott sein, und ihr sollt wissen, daß Ich Jehovah, euer Gott bin, Der euch von den Lasten Ägyptens herausgebracht,',
        8: 'Und bringe euch zu dem Land, das Ich dem Abraham, Isaak und Jakob zu geben Meine Hand aufhob, und euch nun zum erblichen Besitztum gebe; Ich bin Jehovah.',
        9: 'Und Mose redete so mit den Söhnen Israels; aber sie hörten vor Ungeduld des Geistes und harter Knechtschaft nicht auf Mose.',
        10: 'Und Jehovah redete mit Mose und sprach:',
        11: 'Gehe hinein, rede zu Pharao, dem Könige Ägyptens, und er soll die Söhne Israels aus seinem Land entlassen.',
        12: 'Und Mose redete vor Jehovah und sprach: Siehe, die Söhne Israels hörten nicht auf mich; und wie sollte Pharao auf mich hören? und ich bin unbeschnitten an Lippen.',
        13: 'Und Jehovah redete zu Mose und zu Aharon und gebot ihnen an die Söhne Israels und an Pharao, den König von Ägypten, die Söhne Israels aus Ägyptenland herauszubringen.',
        14: 'Das sind die Häupter des Hauses ihrer Väter: Die Söhne Rubens, des Erstgeborenen Israels: Chanoch und Pallu, Chezron und Karmi. Das sind die Familien Rubens.',
        15: 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jachin und Zochar und Schaul, der Sohn der Kanaaniterin. Dies die Familien Simeons.',
        16: 'Und das sind die Namen der Söhne Levis nach ihren Geschlechtern: Gerschon und Kohath und Merari, und die Jahre des Lebens Levis waren hundertsiebenunddreißig Jahre.',
        17: 'Die Söhne Gerschons sind Libni und Schimei nach ihren Familien.',
        18: 'Und die Söhne Kohaths: Amram und Jizhar und Chebron und Ussiel, und die Jahre des Lebens Kohaths sind hundertdreiunddreißig Jahre.',
        19: 'Und die Söhne Meraris sind Machli und Muschi. Dies die Familien Levis nach ihren Geschlechtern.',
        20: 'Und Amram nahm sich seine Muhme Jochebed zum Weibe, und sie gebar ihm Aharon und Mose; und die Jahre des Lebens Amrams waren hundertsiebenunddreißig Jahre.',
        21: 'Und die Söhne Jizhars waren Korach und Nepheg und Sichri.',
        22: 'Und die Söhne Ussiels: Mischael und Elzaphan und Sithri.',
        23: 'Und Aharon nahm Elischeba, Tochter Aminadabs, Schwester des Nachasson, sich zum Weibe und sie gebar ihm Nadab und Abihu, Eleasar und Ithamar.',
        24: 'Und die Söhne Korachs: Assir und Elkanah und Abiasaph. Das sind die Familien der Korachiten.',
        25: 'Und Eleasar, Sohn Aharons, nahm sich eine von Putiels Töchtern zum Weibe, und sie gebar ihm Pinechas. Dies sind die Häupter der Väter der Leviten nach ihren Familien.',
        26: 'Das ist Aharon und Mose, zu denen Jehovah sprach: Bringet Israels Söhne heraus aus dem Lande Ägypten nach ihren Heerscharen.',
        27: 'Sie sind es, die zu Pharao, dem Könige von Ägypten, redeten, daß sie möchten die Söhne Israels aus Ägypten herausbringen, das ist Moses und Aharon.',
        28: 'Und es geschah an dem Tage, da Jehovah zu Mose redete im Lande Ägypten,',
        29: 'Und Jehovah redete zu Mose und sprach: Ich bin Jehovah! Rede zu Pharao, Ägyptens König, alles, was Ich zu dir rede.',
        30: 'Und Mose sprach vor Jehovah: Siehe, ich bin unbeschnitten an Lippen, und wie wird Pharao auf mich hören?',
    },
    7: {
        1: 'Und Jehovah sprach zu Mose: Siehe, Ich habe dich zum Gott für Pharao gegeben, und Aharon, dein Bruder, soll dein Prophet sein.',
        2: 'Du sollst alles reden, was Ich dir gebiete und dein Bruder Aharon soll reden zu Pharao, auf daß er die Söhne Israels aus seinem Lande entlasse.',
        3: 'Und Ich will verhärten Pharaos Herz, und viel machen Meiner Zeichen und Meiner Wahrzeichen in Ägyptenland.',
        4: 'Und Pharao wird nicht auf euch hören; aber Ich werde Meine Hand auf die Ägypter legen und durch große Gerichte Meine Heerscharen, Mein Volk, die Söhne Israels aus Ägyptenland herausbringen.',
        5: 'Und wissen sollen die Ägypter, daß Ich Jehovah bin, wenn Ich Meine Hand ausstrecke über Ägypten und Israels Söhne aus ihrer Mitte herausbringe.',
        6: 'Und Mose und Aharon taten wie Jehovah ihnen geboten hatte, so taten sie.',
        7: 'Und Mose war achtzig Jahre alt und Aharon dreiundachtzig Jahre alt, als sie zu Pharao redeten.',
        8: 'Und Jehovah redete zu Mose und zu Aharon und sprach:',
        9: 'So Pharao zu euch redet und spricht: Gebet für euch ein Wahrzeichen, dann sprich zu Aharon: Nimm deinen Stab und wirf ihn hin vor Pharao. Er soll zur Wasserschlange werden.',
        10: 'Und Mose ging hinein und Aharon zu Pharao und sie taten so wie Jehovah geboten hatte, und Aharon warf seinen Stab vor Pharao und vor seine Knechte und er ward zur Wasserschlange.',
        11: 'Und Pharao rief auch die Weisen und Zauberer, und auch sie, die Wahrsager Ägyptens, taten also mit ihren Zauberformeln.',
        12: 'Und sie warfen jeder Mann seinen Stab hin, und sie wurden zu Wasserschlangen; aber Aharons Stab verschlang ihre Stäbe.',
        13: 'Und Pharaos Herz ward bestärkt; und er hörte nicht auf sie, wie Jehovah geredet hatte.',
        14: 'Und Jehovah sprach zu Mose: Schwer ist Pharaos Herz; er weigert sich, das Volk zu entlassen.',
        15: 'Gehe zu Pharao am Morgen! Siehe, er geht aus an das Wasser, und stelle dich ihm entgegen am Ufer des Stromes, und nimm den Stab, der in eine Schlange verwandelt worden, in deine Hand.',
        16: 'Und sprich zu ihm: Jehovah, der Gott der Hebräer, hat mich zu dir gesandt und spricht: Entlaß Mein Volk, daß sie Mir dienen in der Wüste! Und siehe, du hast bis jetzt nicht darauf gehört.',
        17: 'So spricht Jehovah: Daran sollst du wissen, daß Ich Jehovah bin: Siehe, ich schlage mit dem Stabe, der in meiner Hand ist, auf die Wasser, die im Strome sind, und sie werden in Blut verwandelt.',
        18: 'Und der Fisch im Strom soll sterben, und stinken soll der Strom, daß die Ägypter sich abmühen, Wasser aus dem Strome zu trinken.',
        19: 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Nimm deinen Stab und strecke deine Hand aus über die Wasser Ägyptens, über ihre Flüsse, über ihre Ströme und über ihre Seen und über jegliche Sammlung ihrer Wasser, und sie sollen zu Blut werden; und soll Blut sein im ganzen Land Ägypten und in Holz und in Stein.',
        20: 'Und Mose und Aharon taten so, wie Jehovah geboten hatte. Und er hob den Stab empor und schlug die Wasser in dem Strom vor den Augen Pharaos und vor den Augen seiner Knechte, und alle Wasser in dem Strom wurden in Blut verwandelt.',
        21: 'Und der Fisch im Strome starb und der Strom stank, und die Ägypter vermochten nicht das Wasser aus dem Strom zu trinken; und das Blut war in ganz Ägyptenland.',
        22: 'Und es taten so auch die Wahrsager Ägyptens mit ihren Zauberformeln und Pharaos Herz ward bestärkt und er hörte nicht auf sie, wie Jehovah geredet hatte.',
        23: 'Und Pharao wandte sich und kam in sein Haus, und nahm auch dies nicht zu Herzen.',
        24: 'Und alle Ägypter gruben in den Umgebungen des Stroms nach Wasser zum Trinken; denn sie vermochten nicht von dem Wasser des Stromes zu trinken.',
        25: 'Und es wurden erfüllt sieben Tage, seitdem Jehovah den Strom geschlagen hatte. Und Jehovah sprach zu Mose: Gehe hinein zu Pharao und sprich zu ihm: So spricht Jehovah: Entlaß Mein Volk, daß sie Mir dienen. Und wenn du dich weigerst, es zu entlassen, siehe, so schlage ich all deine Grenze mit Fröschen. Und der Strom soll von Fröschen wimmeln, und sie sollen heraufsteigen und kommen in dein Haus und in deine Schlafkammer und auf dein Bett, und in das Haus deiner Knechte und zu deinem Volk, und in deine Öfen und in deine Backtröge. Und an dich und dein Volk und an alle deine Knechte sollen die Frösche heraufkommen.',
    },
    8: {
        1: 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Strecke deine Hand aus mit deinem Stab über die Flüsse, über die Ströme und über die Seen, und bringe die Frösche herauf über Ägyptenland.',
        2: 'Und Aharon streckte seine Hand aus über die Wasser Ägyptens, und herauf kam der Frosch und bedeckte Ägyptenland.',
        3: 'Und die Wahrsager taten mit ihren Zauberformeln gleich also. Und sie brachten Frösche herauf über Ägyptenland.',
        4: 'Und Pharao rief Mose und Aharon und sprach: Flehet zu Jehovah, daß Er die Frösche von mir und Meinem Volk wegnehme; und ich will das Volk entlassen, daß sie dem Jehovah opfern.',
        5: 'Und Mose sprach zu Pharao: Habe du den Ruhm über mich, bis wann soll ich für dich und für deine Knechte und für dein Volk flehen, daß die Frösche von dir und deinen Häusern ausgerottet werden; nur im Strom werden sie verbleiben.',
        6: 'Und er sprach: Auf morgen! und er sprach: Nach deinem Wort! auf daß du wissest, daß keiner ist wie Jehovah, unser Gott.',
        7: 'Und die Frösche sollen weichen von dir und deinen Häusern und von deinen Knechten und von deinem Volk; nur in dem Strome sollen sie verbleiben.',
        8: 'Und Mose ging hinaus und Aharon fort von Pharao, und Mose schrie zu Jehovah der Frösche wegen, die Er über Pharao gebracht.',
        9: 'Und Jehovah tat nach Moses Wort, und die Frösche starben weg aus den Häusern, aus den Höfen und aus den Feldern.',
        10: 'Und sie häuften sie auf zu Haufen und Haufen, und das Land stank.',
        11: 'Und Pharao sah, daß er wieder atmen konnte und er verstockte sein Herz und hörte nicht auf sie, wie Jehovah geredet hatte.',
        12: 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Strecke deinen Stab aus und schlage den Staub der Erde, daß er zu Läusen werde in ganz Ägyptenland!',
        13: 'Und sie taten also, und Aharon streckte seine Hand aus mit seinem Stab und schlug den Staub der Erde, und die Läuse waren an Mensch und Vieh; aller Staub der Erde ward zu Läusen im ganzen Land Ägypten.',
        14: 'Und es taten die Wahrsager auch also mit ihren Zauberformeln, um Läuse hervorzubringen und sie vermochten es nicht, und die Läuse waren an Mensch und Vieh.',
        15: 'Und die Wahrsager sprachen zu Pharao: Dies ist der Finger Gottes! Und das Herz Pharaos bestärkte sich und er hörte nicht auf sie, wie Jehovah geredet hatte.',
        16: 'Und Jehovah sprach zu Mose: Stehe früh am Morgen auf und stelle dich vor Pharao. Siehe, er geht aus an das Wasser; und sprich zu ihm: So spricht Jehovah: Entlaß Mein Volk, daß sie Mir dienen!',
        17: 'Entlässest du nicht Mein Volk, siehe, da sende Ich Ungeziefer wider dich, wider deine Knechte und wider dein Volk und wider deine Häuser und die Häuser der Ägypter sollen voll vom Ungeziefer sein, und auch der Boden, auf dem sie sind.',
        18: 'Und Ich will unterscheiden an jenem Tag Goschens Land, auf dem Mein Volk steht; daß dort das Ungeziefer nicht soll sein, damit du wissest daß Ich Jehovah bin inmitten des Landes.',
        19: 'Und eine Erlösung will Ich zwischen Mein Volk und zwischen deinem Volk setzen; morgen geschehe dieses Zeichen.',
        20: 'Und Jehovah tat also. Und schwer kam das Ungeziefer in Pharaos Haus und in seiner Knechte Haus und in das ganze Ägyptenland; das Land verdarb vor Ungeziefer.',
        21: 'Und Pharao rief Mose und Aharon und sprach: Gehet, opfert eurem Gott in dem Lande.',
        22: 'Mose aber sprach: Es ist nicht richtig, so zu tun, denn sonst würden wir den Greuel der Ägypter Jehovah, unserem Gotte, opfern. Siehe, würden wir den Greuel der Ägypter vor ihren Augen opfern, würden sie uns nicht steinigen?',
        23: 'Drei Tagreisen wollen wir in die Wüste ziehen und Jehovah, unserem Gotte, opfern, wie Er uns sagte.',
        24: 'Und Pharao sprach: Ich will euch entlassen, daß ihr Jehovah, eurem Gotte, opfert in der Wüste. Nur sollt ihr nicht ferne gehen; flehet für mich!',
        25: 'Und Mose sprach: Siehe, ich gehe hinaus von dir und werde zu Jehovah flehen; und Er wird morgen wegnehmen das Ungeziefer von Pharao, von seinen Knechten und von seinem Volke. Nur möge Pharao nicht mehr uns hintergehen, das Volk nicht zu entlassen, daß es Jehovah opfere.',
        26: 'Und Mose ging hinaus von Pharao und flehte zu Jehovah.',
        27: 'Und Jehovah tat nach dem Worte Moses und nahm weg das Ungeziefer von Pharao, von seinen Knechten und von seinem Volk; nicht eines verblieb.',
        28: 'Aber Pharao verstockte sein Herz auch diesmal und entließ das Volk nicht.',
    },
    9: {
        1: 'Und Jehovah sprach zu Mose: Gehe hinein zu Pharao und rede zu ihm: So spricht Jehovah, der Gott der Hebräer: Entlaß Mein Volk, daß sie Mir dienen.',
        2: 'Denn, wenn du dich weigerst, sie zu entlassen und sie noch länger festhältst;',
        3: 'Siehe, so ist die Hand Jehovahs wider deine Viehherden, die auf dem Felde sind, wider die Pferde, wider die Esel, wider die Kamele, wider das Rindvieh und wider das Kleinvieh mit sehr schwerer Pestilenz.',
        4: 'Und Jehovah wird unterscheiden zwischen den Viehherden Israels und den Viehherden Ägyptens, so daß nicht ein Stück von dem, das die Söhne Israels haben, sterben wird.',
        5: 'Und Jehovah setzte eine bestimmte Zeit und sprach: Morgen wird Jehovah dies im Lande tun.',
        6: 'Und Jehovah tat dies am morgenden Tag, und alle Viehherden Ägyptens starben, und von den Viehherden Israels starb nicht eines.',
        7: 'Und Pharao sandte und siehe, von den Viehherden Israels war nicht eines gestorben. Aber Pharaos Herz verstockte sich und er entließ das Volk nicht.',
        8: 'Und Jehovah sprach zu Mose und zu Aharon: Nehmet euch die Fäuste voll Ruß des Ofens und Mose sprenge ihn gen Himmel vor den Augen Pharaos.',
        9: 'Und er soll zu feinem Staub werden über ganz Ägyptenland, und soll werden an Menschen und an Vieh zu einem Geschwür, das aufbricht mit Blattern, in ganz Ägyptenland.',
        10: 'Und sie nahmen den Ofenruß, standen vor Pharao und Mose sprengte ihn gen Himmel, und er ward zu einem Geschwür, das ausbrach in Blattern, an Mensch und an Vieh.',
        11: 'Und es vermochten die Wahrsager nicht zu stehen vor Mose wegen des Geschwürs; denn das Geschwür war an den Wahrsagern und an allen Ägyptern.',
        12: 'Und Jehovah bestärkte Pharaos Herz, so daß er nicht auf sie hörte, so wie Jehovah zu Mose geredet hatte.',
        13: 'Und Jehovah sprach zu Mose: Stehe auf früh am Morgen und stelle dich vor Pharao und sprich zu ihm: So spricht Jehovah, der Gott der Hebräer: Entlaß Mein Volk, daß sie Mir dienen.',
        14: 'Denn diesmal sende Ich alle Meine Plagen über dein Herz und über deine Knechte und über dein Volk, auf daß du wissest, daß keiner ist wie Ich, auf der ganzen Erde.',
        15: 'Und nun hätte Ich Meine Hand ausgestreckt und dich und dein Volk mit der Pestilenz geschlagen, daß von der Erde du weggeschafft werdest.',
        16: 'Aber darum ließ Ich dich noch stehen, darum, daß Ich dich sehen lasse Meine Kraft, und man von Meinem Namen auf der ganzen Erde erzähle.',
        17: 'Wirfst du dich gegen Mein Volk noch länger, auf daß du sie nicht entlässest:',
        18: 'Siehe, so lasse Ich um die morgende Zeit einen sehr schweren Hagel regnen, wie noch keiner in Ägypten gewesen ist, seit dem Tage, daß es gegründet ward, bis jetzt.',
        19: 'Und nun, sende und laß zusammenflüchten deine Viehherden und alles, was du auf dem Felde hast. Jedweder Mensch und das Vieh, das auf dem Feld sich findet und nicht ins Haus versammelt ist, so der Hagel auf sie herabkommt, wird sterben.',
        20: 'Wer von den Knechten Pharaos das Wort Jehovahs fürchtete, der ließ seine Knechte und seine Viehherden in die Häuser fliehen.',
        21: 'Wer sich aber Jehovahs Wort nicht zu Herzen legte, der ließ seine Knechte und seine Viehherden auf dem Felde.',
        22: 'Und Jehovah sprach zu Mose: Strecke deine Haus aus gen Himmel, daß es hagle auf ganz Ägyptenland, auf Mensch und Vieh und auf alles Kraut des Feldes im Lande Ägypten.',
        23: 'Und Mose streckte seinen Stab aus gen Himmel und Jehovah gab Stimmen und Hagel und ineinanderfahrendes Feuer zur Erde hin; und Jehovah ließ Hagel regnen auf das Land Ägypten.',
        24: 'Und es ward ein Hagel und ein ineinanderfahrendes Feuer inmitten des Hagels; sehr schwer, so daß desgleichen noch nie gewesen war in ganz Ägyptenland, seit es zu einer Völkerschaft wurde.',
        25: 'Und der Hagel schlug in ganz Ägyptenland alles, was auf dem Felde war, vom Menschen bis zum Vieh, und alles Kraut des Feldes schlug der Hagel, und jeglichen Baum des Feldes zerbrach er.',
        26: 'Nur im Lande Goschen, wo die Söhne Israels waren, war kein Hagel.',
        27: 'Und Pharao sandte und rief Mose und Aharon und sprach zu ihnen: Diesmal habe ich gesündigt, Jehovah ist der Gerechte, und ich und mein Volk sind ungerecht.',
        28: 'Flehet zu Jehovah, auf daß genug sei der Stimmen Gottes und des Hagels; so will ich euch entlassen, und ihr sollt nicht länger bleiben.',
        29: 'Und Mose sprach zu ihm: Wenn ich hinaus vor die Stadt komme, will ich meine Hände ausbreiten zu Jehovah, da sollen die Stimmen aufhören und kein Hagel mehr sein, auf daß du wissest, daß die Erde Jehovahs ist.',
        30: 'Du aber und deine Knechte - das weiß ich - ihr fürchtet euch noch nicht vor dem Angesichte Jehovah Gottes.',
        31: 'Und der Flachs und die Gerste wurden geschlagen; denn die Gerste hatte Ähren und der Flachs hatte Knoten.',
        32: 'Und der Weizen und der Spelt wurden nicht geschlagen, weil sie verdeckt waren.',
        33: 'Und Mose ging weg von Pharao, hinaus zur Stadt, und breitete seine Hände aus zu Jehovah, und die Stimmen hörten auf und der Hagel und der Regen ergossen sich nicht mehr zur Erde.',
        34: 'Und Pharao sah, daß der Regen aufhörte und der Hagel und die Stimmen, und er fuhr fort zu sündigen und verstockte sein Herz, er und seine Knechte.',
        35: 'Und Pharaos Herz ward bestärkt und er entließ die Söhne Israels nicht, wie Jehovah durch die Hand Moses geredet hatte.',
    },
    10: {
        1: 'Und Jehovah sprach zu Mose: Gehe hinein zu Pharao; denn Ich habe sein Herz und das Herz seiner Knechte verstockt, auf daß Ich diese Meine Zeichen in seine Mitte setze.',
        2: 'Und auf daß du erzählest vor den Ohren deines Sohnes und des Sohnes deines Sohnes, was Ich in Ägypten ausgerichtet, und Meine Zeichen, die Ich unter sie gesetzt, und ihr wisset, daß Ich Jehovah bin.',
        3: 'Und Mose und Aharon gingen hinein zu Pharao und sprachen zu ihm: So spricht Jehovah, der Gott der Hebräer: Wie lange weigerst du dich, vor Mir dich zu demütigen. Entlaß Mein Volk, daß sie Mir dienen.',
        4: 'Denn wenn du dich weigerst, Mein Volk zu entlassen, siehe, dann bringe Ich morgen Heuschrecken in deine Grenze,',
        5: 'So daß sie das Angesicht der Erde bedekken, daß man die Erde nicht zu sehen vermag, und sollen fressen das Übergebliebene des Entkommenen, das auch vom Hagel geblieben, und fressen jeglichen Baum, der für euch aus dem Felde sproßt.',
        6: 'Und sollen füllen deine Häuser und die Häuser aller deiner Knechte und die Häuser aller Ägypter, wie es nicht gesehen deine Väter, noch deiner Väter Väter, seit dem Tage, da sie auf dem Boden waren, bis auf diesen Tag. Und er wandte sich und ging hinaus von Pharao.',
        7: 'Und Pharaos Knechte sprachen zu ihm: Wie lange soll uns dies zum Fallstrick sein? Entlaß die Männer, daß sie Jehovah, ihrem Gotte dienen? Weißt du noch nicht, daß Ägypten vergeht?',
        8: 'Und man brachte Mose und Aharon zurück zu Pharao, und er sprach zu ihnen: Gehet, dienet Jehovah, eurem Gott. Wer und wer sind die, so da gehen?',
        9: 'Und Mose sprach: Mit unseren Jungen und unseren Alten wollen wir ziehen, mit unseren Söhnen und mit unseren Töchtern, mit unserem Kleinvieh und mit unseren Rindern wollen wir ziehen; denn wir haben ein Fest Jehovahs.',
        10: 'Und er sprach zu ihnen: So sei Jehovah mit euch, wie ich euch entlasse und eure Kindlein. Sehet, daß Böses ist vor euern Angesichtern!',
        11: 'Nicht also! So gehet doch, ihr junge Männer, und dienet dem Jehovah; denn das suchet ihr ja. Und man trieb sie fort von dem Angesichte Pharaos.',
        12: 'Und Jehovah sprach zu Mose: Strecke deine Hand aus über Ägyptenland wegen der Heuschrecken. Und herauf sollen sie kommen über das Land Ägypten und alles Kraut des Landes fressen, alles, was vom Hagel verblieb.',
        13: 'Und Mose streckte seinen Stab über Ägyptenland aus. Und Jehovah führte einen Ostwind über das Land jenen ganzen Tag und die ganze Nacht. Es ward Morgen und der Ostwind trug die Heuschrecken daher.',
        14: 'Und die Heuschrecken kamen herauf über das ganze Land Ägypten, und ließen sich sehr schwer in aller Grenze Ägyptens nieder. Vordem hatte es nie also Heuschrecken gege- ben und nachher wird es auch nie mehr also geben.',
        15: 'Und sie bedeckten das Angesicht des ganzen Landes und das Land ward verfinstert. Und sie fraßen alles Kraut der Erde und alle Frucht des Baumes, die der Hagel übrig gelassen; und blieb nichts Grünes am Baum, noch am Kraut des Feldes in ganz Ägyptenland übrig.',
        16: 'Und Pharao rief eilig Mose und Aharon und sprach: Ich habe gesündigt wider Jehovah, euern Gott, und wider euch.',
        17: 'Und nun vergib doch nur diesmal meine Sünde und flehet zu Jehovah, eurem Gott, daß Er von mir nur diesen Tod wegnehme.',
        18: 'Und er ging hinaus von Pharao und flehte zu Jehovah.',
        19: 'Und Jehovah ließ kehren einen sehr starken Wind vom Meere, und Er hob die Heuschrecke auf und warf sie ins Schilfmeer, in aller Grenze Ägyptens verblieb nicht eine Heuschrecke.',
        20: 'Und Jehovah bestärkte das Herz Pharaos, und er entließ die Söhne Israels nicht.',
        21: 'Und Jehovah sprach zu Mose: Strecke deine Hand aus gen Himmel, daß Finsternis sei über Ägyptenland und man in der Finsternis herumtastet.',
        22: 'Und Mose streckte seine Hand aus gen Himmel und es ward Finsternis, dichte Finsternis in ganz Ägyptenland für drei Tage.',
        23: 'Es sah der Mann den Bruder nicht; und drei Tage stand kein Mann von seiner Stelle auf; aber die Söhne Israels hatten Licht in ihren Wohnungen.',
        24: 'Und Pharao rief Mose und sprach: Gehet, dienet Jehovah. Nur euer Kleinvieh und eure Rinder lasset zurück; auch eure Kindlein mögen mit euch gehen.',
        25: 'Und Mose sprach: Auch Schlachtopfer und Brandopfer sollst du in unsre Hand geben, daß wir sie darbringen Jehovah, unserem Gotte.',
        26: 'Und auch unsere Viehherden sollen mit uns gehen; keine Klaue darf dahinten verbleiben; denn davon müssen wir nehmen, Jehovah, unserem Gott, zu dienen; und wir wissen nicht, womit wir Jehovah dienen sollen, bis wir dahin kommen.',
        27: 'Und Jehovah bestärkte Pharaos Herz und er wollte sie nicht entlassen.',
        28: 'Und Pharao sprach zu ihm: Gehe von mir! Hüte dich, mein Angesicht wieder zu sehen; denn am Tage, da du mein Angesicht siehst, sollst du sterben.',
        29: 'Und Mose sprach: Richtig hast du geredet. Ich werde dein Angesicht hinfort nicht mehr sehen.',
    },
    11: {
        1: 'Und Jehovah sprach zu Mose: Noch eine Plage werde Ich über Pharao und über Ägypten hereinbringen, danach wird er euch von dannen entlassen. Wenn er euch entläßt allzumal, dann wird er euch von dannen forttreiben.',
        2: 'Rede doch vor des Volkes Ohren: Jeder Mann soll von seinem Genossen, und jedes Weib von ihrer Genossin Gefäße von Silber und Gefäße von Gold sich erbeten.',
        3: 'Und Jehovah gab dem Volke Gnade in den Augen der Ägypter; auch war der Mann Mose sehr groß im Lande Ägypten in den Augen der Knechte Pharaos und in den Augen des Volkes.',
        4: 'Und Mose sprach: So spricht Jehovah: Um die Mitte der Nacht gehe Ich aus in die Mitte Ägyptens.',
        5: 'Und sterben soll alle Erstgeburt im Lande Ägypten von dem Erstgeborenen Pharaos, der auf seinem Throne sitzt, bis auf den Erstgeborenen der Dienstmagd, die hinter der Mühle ist, und alle Erstgeburt des Viehs.',
        6: 'Und ein groß Geschrei wird sein im ganzen Lande Ägypten, desgleichen nie gewesen ist und desgleichen nie mehr sein wird.',
        7: 'Und bei allen Söhnen Israels soll kein Hund die Zunge regen, vom Manne bis zum Vieh, auf daß ihr wisset, daß Jehovah unterscheidet zwischen Ägyptern und zwischen Israel.',
        8: 'Und all diese deine Knechte kommen herab zu mir und verbeugen sich vor mir und sprechen: Geh aus, du und all das Volk, das deinem Fuße folgt; und danach gehe ich aus. Und er ging in dem Entbrennen des Zornes hinaus von Pharao.',
        9: 'Und Jehovah sprach zu Mose: Pharao wird auf euch nicht hören, auf daß Meiner Wahrzeichen viel werde im Lande Ägypten.',
        10: 'Und Mose und Aharon taten alle diese Wahrzeichen vor Pharao; und Jehovah bestärkte Pharaos Herz, so daß er die Söhne Israel nicht aus seinem Land entließ.',
    },
    12: {
        1: 'Und Jehovah sprach zu Mose und zu Aharon im Lande Ägypten und sagte:',
        2: 'Dieser Monat sei euch das Haupt der Monate. Der erste sei er euch unter den Monaten des Jahres.',
        3: 'Redet zu der ganzen Gemeinde Israels und saget: Am zehnten dieses Monats da nehme von euch jeder Mann sich ein Lamm für das Haus der Väter, ein Lammauf das Haus.',
        4: 'Und wenn das Haus zu klein ist für ein Lamm, so nehme er es und sein Nachbar, der seinem Hause nahe ist, nach der Zahl der Seelen, je wie Einer von dem Lamm essen mag zählet ihn.',
        5: 'Ein Lamm ohne Fehl, männlich von einem Jahre soll es sein für euch. Von den Lämmern und von den Ziegen sollt ihr es nehmen.',
        6: 'Und bis zum vierzehnten Tage dieses Monats bewahrt es auf, behaltet es und die ganze Versammlung der Gemeinde Israels schlachte es gegen Abend.',
        7: 'Und von dem Blute sollen sie nehmen und an die zwei Türpfosten und an die Oberschwelle tun, an den Häusern, in denen sie essen;',
        8: 'Und sollen das Fleisch in dieser Nacht essen, am Feuer gebraten, und mit Ungesäuertem und mit bitteren Kräutern sollen sie es essen.',
        9: 'Nicht roh oder gekocht, im Wasser gekocht, sollt ihr davon essen, sondern am Feuer gebraten, seinen Kopf auf seinen Schenkeln und seinen Eingeweiden.',
        10: 'Und sollt nichts davon übrig lassen bis zum Morgen, was aber davon übrig bleibt bis zum Morgen, sollt ihr im Feuer verbrennen.',
        11: 'Und so sollt ihr es essen: Eure Lenden gegürtet, eure Schuhe an euren Füßen und eure Stöcke in eurer Hand, und sollt es mit Hast essen; es soll ein Passah dem Jehovah sein.',
        12: 'Und in dieser Nacht durchzieh Ich das Land Ägypten und schlage alle Erstgeburt im Lande Ägypten vom Menschen und bis zum Vieh, und über alle Götter Ägyptens halte Ich Gericht, Ich Jehovah.',
        13: 'Und das Blut sei euch zum Zeichen an den Häusern, worin ihr seid, und sehe Ich das Blut, gehe Ich an euch vorüber und keine Plage vom Verderben soll an euch sein, wenn Ich das Land Ägypten schlage.',
        14: 'Und dieser Tag sei zum Gedächtnis für euch; und als ein Fest Jehovahs sollet ihr ihn feiern in euren Geschlechtern, als ewige Satzung sollet ihr ihn feiern.',
        15: 'Sieben Tage sollt ihr Ungesäuertes essen; schon am ersten Tage sollt ihr den Sauerteig aus euren Häusern wegschaffen; denn jeder, der Gesäuertes ißt, dessen Seele soll aus Israel ausgerottet werden; vom ersten bis zum siebenten Tag.',
        16: 'Und am ersten Tage soll heilige Zusammenberufung und am siebenten Tage heilige Zusammenberufung bei euch sein. Keinerlei Arbeit werde an denselben getan. Nur was jede Seele ißt, darf bei euch zugerichtet werden.',
        17: 'Und haltet das Ungesäuerte; denn an diesem selben Tage habe Ich eure Heerscharen aus dem Land Ägypten ausgeführt, und haltet diesen Tag in euren Geschlechtern als ewige Satzung.',
        18: 'In dem ersten, am vierzehnten Tage des Monats am Abend sollt ihr Ungesäuertes essen bis zum einundzwanzigsten Tage des Monats am Abend.',
        19: 'Sieben Tage soll kein Sauerteig in euren Häusern gefunden werden; denn jeder, der Gesäuertes ißt, dessen Seele soll aus der Gemeinde Israels ausgerottet werden, bei dem Fremdling, und bei dem Eingeborenen des Landes.',
        20: 'Nichts Gesäuertes sollt ihr essen, in allen euren Wohnungen sollt ihr Ungesäuertes essen.',
        21: 'Und Mose berief alle Ältesten Israels und sprach zu ihnen: Ziehet hervor und nehmet euch Kleinvieh nach euren Familien und schlachtet das Passah.',
        22: 'Und nehmet ein Bündel Ysop und tauchet es in das Blut, das im Becken ist und berührt die Oberschwelle und die beiden Türpfosten mit dem Blut, das in dem Becken ist; und kein Mann von euch gehe aus dem Eingang seines Hauses bis zum Morgen.',
        23: 'Und Jehovah wird durchziehen, die Ägypter zu schlagen, und wenn Er das Blut an der Oberschwelle und an den zwei Türpfosten sieht, so geht Jehovah vorbei an dem Eingang und gibt nicht zu, daß der Verderber in eure Häuser komme, um zu schlagen.',
        24: 'Und ihr sollt halten dieses Wort als Satzung für dich und für deine Söhne ewiglich.',
        25: 'Und soll geschehen, wenn ihr in das Land kommet, das Jehovah euch geben wird, wie Er geredet hat, da sollt ihr diesen Dienst halten.',
        26: 'Und es soll geschehen, wenn eure Söhne zu euch sagen: Was ist euch dieser Dienst?',
        27: 'Und ihr sollt sagen: Es ist das Passahopfer für Jehovah, Der an den Häusern der Söhne Israels in Ägypten vorbeiging, da Er Ägypten schlug, und unsere Häuser errettete. Und das Volk verneigte sich und sie beteten an.',
        28: 'Und die Söhne Israels gingen hin und taten, wie Jehovah Mose und Aharon geboten, so taten sie.',
        29: 'Und es geschah um Mitternacht, daß Jehovah schlug alle Erstgeburt im Lande Ägypten, vom Erstgeborenen Pharaos, der auf seinem Throne sitzen sollte, bis zum Erstgeborenen des Gefangenen, der im Hause der Grube war, und alle Erstgeburt des Viehs.',
        30: 'Und Pharao stand auf in der Nacht, er und alle seine Knechte, und alle Ägypter, und es war ein großes Geschrei in Ägypten; denn es war kein Haus, wo nicht ein Toter war.',
        31: 'Und er rief Mose und Aharon in der Nacht und sprach: Machet euch auf, gehet hinaus aus meines Volkes Mitte, sowohl ihr, als auch die Söhne Israels und gehet und dienet Jehovah, wie ihr geredet habt.',
        32: 'Auch euer Kleinvieh und eure Rinder nehmet mit, wie ihr geredet habt, und geht und segnet auch mich.',
        33: 'Und Ägypten drang auf das Volk, sie eilig aus dem Lande zu senden; denn, sagten sie, wir alle sterben.',
        34: 'Und das Volk trug seinen Teig, ehe er gesäuert war, ihre Backtröge, in ihre Gewänder zugebunden, auf ihren Schultern.',
        35: 'Und die Söhne Israels hatten getan, nach dem Worte Moses, und die Ägypter um Gefä-ße von Silber und Gefäße von Gold und Gewänder gefragt.',
        36: 'Und Jehovah hatte dem Volke Gnade in den Augen der Ägypter gegeben und sie gewährten sie ihnen. Und sie entrissen es den Ägyptern.',
        37: 'Und die Söhne Israels brachen von Ramses auf gen Sukkoth, bei sechshunderttausend zu Fuß, die Männer ohne die Kindlein.',
        38: 'Und auch viel Troß zog mit ihnen hinauf und Kleinvieh und Rinder, eine sehr große Viehherde.',
        39: 'Und sie buken den Teig, den sie aus Ägypten herausgebracht, zu ungesäuerten Kuchen; denn es war nicht gesäuert, weil sie aus Ägypten fortgetrieben wurden und nicht vermochten zu zaudern und auch keine Zehrung für sich zugerichtet hatten.',
        40: 'Und das Wohnen der Söhne Israel, da sie in Ägypten gewohnt hatten, war dreißig Jahre und vierhundert Jahre.',
        41: 'Und es geschah am Ende der vierhundertdreißig Jahre, daß auf eben diesen selben Tag alle Heerscharen Jehovahs von Ägyptenland ausgingen.',
        42: 'Eine Nacht der Wachen war es dem Jehovah, da Er sie herausbrachte aus dem Lande Ägypten; diese Nacht sei dem Jehovah zur Wache für alle Söhne Israels nach ihren Geschlechtern.',
        43: 'Und Jehovah sprach zu Mose und Aharon: Dies ist die Satzung für das Passah: Kein Sohn eines Ausländischen soll davon essen!',
        44: 'Aber jeden Knecht, den Mann, den du für Geld gekauft, sollst du beschneiden. Dann esse er davon.',
        45: 'Ein Beisaß und Mietling soll nicht davon essen.',
        46: 'In einem Hause soll es gegessen werden. Du sollst nichts von dem Fleisch aus dem Hause hinausbringen. Und ihr sollt kein Bein an ihm brechen.',
        47: 'Die ganze Gemeinde Israels soll es tun.',
        48: 'Und wenn sich ein Fremdling bei dir aufhält und dem Jehovah das Passah halten will, dem soll alles Männliche beschnitten werden; dann nahe er sich, es zu halten, und soll sein wie der Eingeborene des Landes; aber ein Unbeschnittener soll nicht davon essen.',
        49: 'Ein Gesetz soll sein für den Eingeborenen und den Fremdling, der in eurer Mitte sich aufhält.',
        50: 'Und alle Söhne Israels taten, wie Jehovah dem Mose und Aharon geboten hatte, also taten sie.',
        51: 'Und an eben demselben Tage geschah es, daß Jehovah die Söhne Israels nach ihren Heerscharen aus Ägyptenland herausbrachte.',
    },
    13: {
        1: 'Und Jehovah redete zu Mose und sprach:',
        2: 'Heilige Mir alle Erstgeburt; alles, was die Mutter bricht bei den Söhnen Israels, bei Mensch und bei Vieh, Mein ist es.',
        3: 'Und Mose sprach zu dem Volk: Gedenket dieses Tages, da ihr aus Ägypten, aus dem Hause der Knechte ausgegangen seid; denn mit starker Hand hat euch Jehovah von da herausgebracht; und nichts Gesäuertes soll gegessen werden.',
        4: 'Heute gehet ihr aus im Monat Abib.',
        5: 'Und soll geschehen, wenn dich Jehovah in das Land der Kanaaniter und der Chethiter und der Amoriter und der Chiviter und der Jebusiter, das Er deinen Vätern geschworen, dir zu geben, hineinbringen wird, in ein Land, da Milch und Honig fließt, so sollst du diesen Dienst in diesem Monat dienen.',
        6: 'Sieben Tage sollst du Ungesäuertes essen, und am siebenten Tage ist ein Fest dem Jeho- vah.',
        7: 'Ungesäuertes esse man die sieben Tage. Und nichts Gesäuertes soll man bei dir sehen, und kein Sauerteig soll in deiner ganzen Grenze bei dir zu sehen sein.',
        8: 'Und sage an deinem Sohn an diesem Tage und sprich: Darum ist es, daß Jehovah dies mir getan, da ich aus Ägypten ausging.',
        9: 'Und es sei dir zum Zeichen auf deiner Hand und zum Andenken zwischen deinen Augen, auf daß Jehovahs Gesetz in deinem Munde sei; denn mit starker Hand hat Jehovah dich aus Ägypten herausgebracht.',
        10: 'Und du sollst halten diese Satzung zur bestimmten Zeit von Jahr zu Jahr.',
        11: 'Und soll geschehen, wenn dich Jehovah ins Land der Kanaaniter hereingebracht, wie Er dir und deinen Vätern geschworen und dir es gegeben hat:',
        12: 'Und alles, was die Mutter bricht, soll an Jehovah übergehen und alle Erstgeburt vom Wurf des Viehs, sei Jehovahs.',
        13: 'Und alle Erstgeburt vom Esel sollst du mit einem Lamme einlösen, und lösest du es nicht ein, so brich ihr das Genick; aber alle Erstgeburt vom Menschen unter deinen Söhnen sollst du einlösen.',
        14: 'Und es wird geschehen, daß dich dein Sohn morgen fragt und sagt: Was soll das? und du sagst ihm: Mit starker Hand hat uns Jehovah aus Ägypten, der Knechte Haus, herausgebracht.',
        15: 'Und es geschah, da Pharao sich verhärtete, uns zu entlassen, da erwürgte Jehovah alle Erstgeburt im Land Ägypten, von der Erstgeburt des Menschen bis zur Erstgeburt des Viehs; darum opfere ich Jehovah alles Männliche, das die Mutter bricht, und löse alle Erstgeburt meiner Söhne ein.',
        16: 'Und es sei zum Zeichen auf deiner Hand und zum Stirnband zwischen deinen Augen, daß mit starker Hand Jehovah uns aus Ägypten herausgebracht.',
        17: 'Und es geschah, als Pharao das Volk entließ, daß Gott sie nicht auf dem Weg zu der Philister Land, weil er nahe war, führte; denn Gott sprach: Das Volk möchte sich es gereuen lassen, wenn es Streit sieht, und wieder nach Ägypten zurückkehren.',
        18: 'Und Gott ließ das Volk herumziehen, auf dem Weg der Wüste nach dem Schilfmeer, und kampfgerüstet zogen die Söhne Israels herauf aus dem Lande Ägypten.',
        19: 'Und Mose hatte die Gebeine Josephs mit sich genommen; denn der hatte die Söhne Israels einen Eid schwören lassen, und gesprochen: Gewißlich wird euch Gott heimsuchen, und ihr sollt meine Gebeine von da mit euch hinaufbringen.',
        20: 'Und sie brachen von Sukkoth auf und lagerten in Etham, am Ende der Wüste.',
        21: 'Und Jehovah ging vor ihnen her, bei Tag in einer Wolkensäule, um sie den Weg zu führen, und bei Nacht in einer Feuersäule, um ihnen zu leuchten, auf daß sie bei Tag und bei Nacht gehen könnten.',
        22: 'Nicht wich die Wolkensäule bei Tag, noch die Feuersäule bei Nacht, vor dem Volke.',
    },
    14: {
        1: 'Und Jehovah redete zu Mose und sprach:',
        2: 'Rede zu den Söhnen Israels, daß sie sollen zurückkehren und sich vor Pi-Hachiroth zwischen Migdol und zwischen dem Meere lagern; vor Baal-Zephon, dem gegenüber am Meere sollt ihr euch lagern.',
        3: 'Und Pharao wird über die Söhne Israels sagen: Sie sind verirrt im Lande, die Wüste hat sie eingeschlossen.',
        4: 'Und Ich bestärke Pharaos Herz, daß er ihnen nachsetze, und Ich will Mich verherr- lichen an Pharao und all seiner Streitmacht, auf daß die Ägypter wissen, daß Ich Jehovah bin. Und sie taten also.',
        5: 'Und es ward dem Könige von Ägypten angesagt, daß das Volk geflohen sei; und das Herz Pharaos und seiner Knechte kehrte sich wider das Volk und sie sprachen: Was haben wir getan, daß wir Israel entließen und sie uns nicht mehr dienen?',
        6: 'Und er spannte seinen Streitwagen an und nahm sein Volk mit sich;',
        7: 'Und nahm sechshundert auserwählte Streitwagen und alle Streitwagen Ägyptens und Wagenkämpfer auf jeden davon.',
        8: 'Und Jehovah hatte das Herz Pharaos, des Königs von Ägypten bestärkt, daß er den Söhnen Israels nachsetzte. Und die Söhne Israels waren mit erhöhter Hand ausgegangen.',
        9: 'Und die Ägypter setzten ihnen nach und erreichten sie, da sie am Meere lagerten; alle Rosse der Streitwagen Pharaos und seine Reiter und seine Streitmacht bei Pi-Hachiroth vor Baal-Zephon.',
        10: 'Und Pharao nahte sich; und die Söhne Israels hoben ihre Augen auf und siehe, der Ägypter zog aus hinter ihnen her; und sie fürchteten sich sehr, und die Söhne Israels schrien zu Jehovah.',
        11: 'Und zu Mose sprachen sie: Waren keine Gräber in Ägypten, daß du uns nehmen muß-test, um in der Wüste zu sterben? Warum hast du uns das getan, daß du uns aus Ägyptenland herausbrachtest?',
        12: 'Ist nicht dies das Wort, das wir in Ägypten zu dir redeten und sagten: Höre auf von uns, daß wir den Ägyptern dienen; denn es ist besser für uns, den Ägyptern zu dienen, als in der Wüste zu sterben.',
        13: 'Und Mose sprach zu dem Volk: Fürchtet euch nicht, stellet euch auf und sehet das Heil Jehovahs, das Er heute an euch tut; denn die Ägypter, die ihr heute saht, die sehet ihr fortan nimmer in Ewigkeit.',
        14: 'Jehovah streitet für euch; und ihr sollt nur stille schweigen.',
        15: 'Und Jehovah sprach zu Mose: Was schreist du zu Mir? Rede zu den Söhnen Israels, daß sie aufbrechen.',
        16: 'Und du erhebe deinen Stab und strecke deine Hand aus über das Meer, und spalte es entzwei, auf daß die Söhne Israels mitten im Meer im Trockenen gehen.',
        17: 'Und Ich, siehe Ich bestärke der Ägypter Herz, daß sie hinter ihnen herziehen, und Ich will an Pharao, an all seiner Streitmacht, an seinen Streitwagen und seinen Reitern Mich verherrlichen.',
        18: 'Und die Ägypter sollen wissen, daß Ich Jehovah bin, wenn Ich an Pharao, an seinen Streitwagen und an seinen Reitern Mich verherrliche.',
        19: 'Und es brach auf der Engel Gottes, der vor dem Lager Israels einherzog, und ging hinter sie, und die Wolkensäule vor ihnen brach auf und stand hinter ihnen.',
        20: 'Und kam zwischen Ägyptens Lager und zwischen das Lager Israels; und es war da die Wolke und Finsternis und sie erleuchtete die Nacht; und das eine nahte dem andern nicht die ganze Nacht.',
        21: 'Und Mose streckte seine Hand aus über das Meer, und durch einen starken Ostwind ließ Jehovah das Meer hingehen die ganze Nacht hindurch und legte das Meer trocken, und die Wasser spalteten sich.',
        22: 'Und die Söhne Israels gingen im Trockenen mitten durch das Meer, und das Wasser ward ihnen eine Mauer zu ihrer Rechten und zu ihrer Linken.',
        23: 'Und die Ägypter setzten ihnen nach; und alle Rosse Pharaos, seine Streitwagen und seine Reiter kamen ihnen nach mitten in das Meer.',
        24: 'Und es geschah, um die Morgenwache, daß Jehovah in der Feuer- und Wolkensäule auf das Lager der Ägypter schaute und das Lager der Ägypter verwirrte.',
        25: 'Und die Räder von den Streitwagen wegnahm und sie mit Beschwerde fahren ließ. Und die Ägypter sagten: Lasset uns fliehen vor Israel; denn Jehovah streitet für sie wider die Ägypter.',
        26: 'Und Jehovah sprach zu Moses: Strecke deine Hand aus über das Meer, auf daß die Wasser über den Ägypter, über seinen Streitwagen und über seine Reiter zurückkehren.',
        27: 'Und Mose streckte seine Hand aus über das Meer; und das Meer kehrte bei der Wendung des Morgens zur Stärke seiner Strömung zurück; und die Ägypter flohen ihm entgegen, und Jehovah schüttelte die Ägypter ab mitten in das Meer. Neunzig Mann.',
        28: 'Und die Wasser kehrten zurück und bedeckten die Streitwagen und die Reiter, samt der ganzen Streitmacht Pharaos, die hinter ihnen her in das Meer kam, so daß nicht einer von ihnen verblieb.',
        29: 'Und die Söhne Israel gingen im Trockenen mitten im Meer, und die Wasser waren ihnen zur Mauer zu ihrer Rechten und zu ihrer Linken.',
        30: 'Und Jehovah rettete an diesem Tage Israel aus der Hand der Ägypter; und Israel sah die Ägypter tot am Ufer des Meeres.',
        31: 'Und Israel sah die große Hand, die Jehovah wider die Ägypter erzeigt hatte, und das Volk fürchtete Jehovah, und sie glaubten an Jehovah und an Mose, seinen Knecht.',
    },
    15: {
        1: 'Da sang Mose und die Söhne Israels dieses Lied dem Jehovah und sprachen und sagten: Ich will singen dem Jehovah; denn hoch erhaben ist Er! Roß und Reiter stürzte Er ins Meer.',
        2: 'Meine Stärke und mein Gesang ist Jah. Und Er ward mir zum Heil. Er ist mein Gott, und einen Wohnort will ich Ihm bereiten. Er ist der Gott meines Vater, und Ihn will ich erhöhen.',
        3: 'Jehovah ist ein Mann des Streites. Jehovah ist Sein Name.',
        4: 'Die Streitwagen Pharaos und seine Streitmacht warf Er ins Meer, und die Auswahl seiner Wagenkämpfer ist ins Schilfmeer versunken.',
        5: 'Abgründe bedeckten sie, sie gingen hinab in die Schlünde wie ein Stein.',
        6: 'Deine Rechte, Jehovah, ist verklärt in Kraft, Deine Rechte, Jehovah, zerschmettert den Feind.',
        7: 'Und in der Fülle Deiner Hoheit reißest Du nieder, die wider Dich aufstehen; Du sendest aus Dein Entbrennen; es frißt sie auf wie Stoppel.',
        8: 'Und bei dem Hauchen Deiner Nase türmten sich die Wasser auf; gleich einem Haufen stellten sich auf die Strömungen. Die Abgründe starrten im Herzen des Meeres.',
        9: 'Es spricht der Feind: Ich setze nach; ich erreiche sie; ich teile die Beute, meine Seele soll sich an ihnen füllen. Ich entblöße mein Schwert, meine Hand treibt sie aus.',
        10: 'Du bliesest mit Deinem Winde, das Meer bedeckte sie. Wie Blei versanken sie in die gewaltigen Wasser.',
        11: 'Wer ist wie Du unter den Göttern, Jehovah? Wer ist wie Du, prachtvoll in Heiligkeit, furchtbar im Lobe, Wunder tuend!',
        12: 'Du strecktest aus Deine Rechte, da verschlang sie die Erde.',
        13: 'Du führtest in Deiner Barmherzigkeit das Volk, das Du erlöstest, durch Deine Stärke hast Du es geleitet zum Wohnort Deiner Heiligkeit.',
        14: 'Die Völker hörten es und zitterten; Wehen ergriffen die Einwohner Philistäas.',
        15: 'Da wurden bestürzt Edoms Stammhäupter; Moabs Gewaltige ergriff ein Zittern, es zerflossen alle Einwohner Kanaans.',
        16: 'Schrecken und Schauer fiel auf sie, ob der Größe Deines Armes wurden sie stille wie der Stein, bis Dein Volk, Jehovah, vorüberzieht, bis vorüberzieht das Volk, das Du erworben.',
        17: 'Du bringst sie hinein und pflanzest sie auf den Berg Deines Erbes, zur Stätte, die Du, Jehovah, zu Deiner Wohnung machtest, zum Heiligtum, o Herr, das Deine Hände Dir zugerichtet.',
        18: 'Jehovah sei König ewig und immerfort.',
        19: 'Denn Pharaos Roß mit seinem Streitwagen und mit seinen Reitern kam hinein ins Meer; und Jehovah ließ des Meeres Wasser über sie zurückkommen; und die Söhne Israels gingen im Trockenen mitten im Meer.',
        20: 'Und Mirjam, die Prophetin, Aharons Schwester, nahm die Pauke in ihre Hand, und alle Weiber gingen aus mit Pauken und im Reigentanz ihr nach.',
        21: 'Und Mirjam antwortete ihnen: Singt dem Jehovah; denn hoch erhaben ist Er. Roß und Reiter stürzt Er ins Meer.',
        22: 'Und Mose ließ Israel vom Schilfmeer aufbrechen, und sie gingen aus nach der Wüste Schur, und gingen drei Tage in der Wüste und fanden kein Wasser.',
        23: 'Und sie kamen nach Marah und vermochten nicht das Wasser zu trinken vor Bitterkeit; denn es war bitter; deshalb nannte man seinen Namen Marah.',
        24: 'Und das Volk murrte über Mose und sagte: Was sollen wir trinken?',
        25: 'Und er rief zu Jehovah und Jehovah zeigte ihm Holz; und er warf es in das Wasser, und das Wasser ward süß. Daselbst setzte Er ihnen Satzung und Recht, und versuchte sie allda.',
        26: 'Und Er sprach: Wenn du auf die Stimme Jehovahs, deines Gottes, hörst und tust, was recht in Seinen Augen ist, und Seine Gebote zu Ohren nimmst und alle Seine Satzungen hältst, so werde Ich keine der Krankheiten, die Ich auf die Ägypter gelegt, auf dich legen; denn Ich, Jehovah, bin dein Heiler.',
        27: 'Und sie kamen nach Elim und daselbst waren zwölf Wasserquellen und siebzig Palmen; und sie lagerten da an den Wassern.',
    },
    16: {
        1: 'Und von Elim brachen sie auf, und die ganze Gemeinde der Söhne Israels kam nach der Wüste Sin, die zwischen Elim und Sinai ist, am fünfzehnten Tage des zweiten Monats seit ihrem Auszug aus dem Lande Ägypten.',
        2: 'Und es murrte die ganze Gemeinde der Söhne Israel wider Mose und Aharon in der Wüste;',
        3: 'Und die Söhne Israels sagten zu ihnen: Wären wir doch durch die Hand Jehovahs im Lande Ägypten gestorben, wo wir beim Fleischtopfe saßen, wo wir Brot aßen bis wir satt waren; denn ihr habt uns in diese Wüste herausgeführt, um diese ganze Versammlung Hungers sterben zu lassen.',
        4: 'Und Jehovah sprach zu Mose: Siehe, Ich lasse euch Brot vom Himmel regnen und das Volk gehe aus und lese auf den täglichen Bedarf an seinem Tage, auf daß Ich dasselbe versuche, ob es in Meinem Gesetz wandle oder nicht.',
        5: 'Und am sechsten Tage soll geschehen, wenn sie bereiten, was sie eingebracht haben, daß es das Doppelte ist von dem, was sie Tag für Tag auflesen.',
        6: 'Und Mose und Aharon sprachen zu allen Söhnen Israels: Wenn es Abend wird, sollt ihr wissen, daß es Jehovah ist, Der euch aus Ägyptenland ausgeführt hat.',
        7: 'Und am Morgen sollt ihr sehen Jehovahs Herrlichkeit, daran, daß Er euer Murren gegen Jehovah gehört hat; denn wir, was sind wir, daß ihr wider uns murret?',
        8: 'Und Mose sprach: Daran, daß Jehovah euch am Abend Fleisch zu essen gibt und Brot am Morgen zur Sättigung; daran, daß Er, Jehovah, auf euer Murren gehört, mit dem ihr wider Ihn murrtet; denn was sind wir? Nicht wider uns war euer Murren, sondern wider Jehovah!',
        9: 'Und Mose sprach zu Aharon: Sprich zu der ganzen Gemeinde der Söhne Israels: Nahet euch herzu vor Jehovah; denn Er hat euer Murren gehört.',
        10: 'Und es geschah als Aharon zur Gemeinde der Söhne Israels redete, daß sie sich gegen die Wüste wandten, und siehe, die Herrlichkeit Jehovahs erschien in einer Wolke.',
        11: 'Und Jehovah redete zu Mose und sprach:',
        12: 'Ich habe das Murren der Söhne Israels gehört. Rede zu ihnen und sprich: Gegen Abend sollt ihr Fleisch essen und am Morgen euch sättigen mit Brot, und sollt wissen, daß Ich, Jehovah, euer Gott bin.',
        13: 'Und es geschah am Abend, daß die Wachtel heraufkam und das Lager bedeckte, und am Morgen war eine Lagerung von Tau rings um das Lager.',
        14: 'Und als die Taulagerung aufstieg, siehe, da war auf der Oberfläche der Wüste etwas Feines, Rundes, so fein wie der Reif auf der Erde.',
        15: 'Und die Söhne Israels sahen es und sie sagten der Mann zu seinem Bruder: Was ist das? denn sie wußten nicht, was es war. Und Mose sprach zu ihnen: Es ist das Brot, das Jehovah euch zu essen gegeben hat.',
        16: 'Das ist das Wort, das Jehovah geboten hat: Leset davon auf, der Mann nach seinem Mundbedarf; ein Gomer auf den Kopf, nach der Zahl eurer Seelen, der Mann für die, so in seinem Zelte sind, sollt ihr nehmen.',
        17: 'Und die Söhne Israels taten so, und lasen auf viel und wenig;',
        18: 'Und maßen mit dem Gomer, und so hatte denn, der viel sammelte, keinen Überfluß, und der wenig sammelte, mangelte nicht. Jeder Mann hatte nach seinem Mundbedarf gesammelt.',
        19: 'Und Mose sprach zu ihnen: Kein Mann lasse davon übrig bis zum Morgen.',
        20: 'Sie hörten aber nicht auf Mose und einige Männer ließen übrig davon auf den Morgen. Und es wuchsen Würmer darin und es stank. Und Mose war entrüstet über sie.',
        21: 'Und sie lasen es auf von Morgen zu Morgen, der Mann nach seinem Mundbedarf; und wenn die Sonne heiß wurde, da zerschmolz es.',
        22: 'Und am sechsten Tage geschah es, daß sie das Doppelte des Brotes, je zwei Gomer für einen auflasen. Und alle Fürsten der Gemeinde sagten es Mose an.',
        23: 'Und er sprach zu ihnen: Das ist es, was Jehovah geredet hat: Morgen ist Sabbath, der heilige Sabbath Jehovahs! Was ihr backen wollet, das backet, und was ihr kochen wollet, das kochet, und alles, was überflüssig ist, das legt für euch nieder, um es für morgen aufzubewahren.',
        24: 'Und sie legten es nieder bis zum Morgen, wie Mose geboten hatte, und es stank nicht; auch war keine Made darin.',
        25: 'Und Mose sprach: Esset es heute, denn es ist heute Sabbath dem Jehovah; heute werdet ihr es nicht finden auf dem Felde.',
        26: 'Sechs Tage sollt ihr es auflesen, aber am siebenten Tage, am Sabbath, wird es nicht dort sein.',
        27: 'Und am siebenten Tage geschah es, daß einige vom Volk ausgingen es aufzulesen, und sie fanden nichts.',
        28: 'Und Jehovah sprach zu Mose: Wie lange wollet ihr euch weigern, Meine Gebote und Meine Gesetze zu halten?',
        29: 'Sehet, Jehovah hat euch den Sabbath gegeben; deshalb gibt Er euch am sechsten Tag Brot für zwei Tage. Bleibet, jeder Mann für sich; kein Mann gehe aus von seinem Ort am siebenten Tage.',
        30: 'Und es feierte das Volk am siebenten Tag.',
        31: 'Und das Haus Israel nannte dessen Namen Man. Und es war wie weißer Koriandersamen und sein Geschmack war wie Kuchen mit Honig.',
        32: 'Und Mose sprach: Dies ist das Wort, das Jehovah geboten hat: Füllet ein Gomer davon, daß es werde aufbewahrt für eure Geschlechter, auf daß sie das Brot sehen, das Ich euch ließ essen in der Wüste, als Ich euch aus Ägyptenland herausbrachte.',
        33: 'Und Mose sprach zu Aharon: Nimm eine Urne und tue ein Gomer voll Man hinein und stelle es nieder vor Jehovah zur Aufbewahrung für eure Geschlechter.',
        34: 'Wie Jehovah dem Mose geboten hatte, so stellte es Aharon nieder vor das Zeugnis zur Aufbewahrung.',
        35: 'Und die Söhne Israels aßen das Man vierzig Jahre, bis sie in bewohntes Land kamen. Das Man aßen sie, bis sie an die Grenze des Landes Kanaan kamen.',
        36: 'Und das Gomer ist ein Zehntel des Ephah.',
    },
    17: {
        1: 'Und die ganze Gemeinde der Söhne Israels brach auf von der Wüste Sin auf ihre Wanderzüge nach dem Munde Jehovahs und sie lagerten in Rephidim, und das Volk hatte kein Wasser zu trinken.',
        2: 'Und das Volk haderte mit Mose und sie sprachen: Gib uns Wasser, daß wir trinken! Und Mose sprach zu ihnen: Was hadert ihr mit mir? Was versuchet ihr Jehovah?',
        3: 'Und das Volk dürstete daselbst nach Wasser; und das Volk murrte wider Mose und sprach: Warum hast du uns aus Ägypten heraufgebracht, daß du mich und meine Söhne und meine Viehherden vor Durst sterben lässest.',
        4: 'Und Mose schrie zu Jehovah und sprach: Was soll ich mit diesem Volke tun: Noch ein wenig und sie steinigen mich.',
        5: 'Und Jehovah sprach zu Mose: Zieh hin vor dem Volke und nimm mit dir von den Ältesten Israels; und deinen Stab, mit dem du den Strom geschlagen, nimm in deine Hand und geh hin.',
        6: 'Siehe, Ich stehe dort vor dir auf dem Felsen in Horeb. Und du sollst den Felsen schlagen und Wasser kommt aus ihm heraus, auf daß das Volk trinke; und Mose tat also vor den Augen der Ältesten Israels.',
        7: 'Und er nannte den Namen des Ortes Massah und Meribah, darum, daß die Söhne Israels haderten und Jehovah verfluchten, indem sie sagten: Ist Jehovah in unserer Mitte oder nicht?',
        8: 'Und es kam Amalek und stritt mit Israel in Rephidim.',
        9: 'Und Mose sprach zu Jehoschua: Wähl uns Männer aus und gehe aus und streite wider Amalek. Ich werde mich morgen auf des Hügels Gipfel stellen und der Stab Gottes in meiner Hand.',
        10: 'Und Jehoschua tat, wie ihm Mose gesagt hatte, daß er wider Amalek streiten sollte. Und Mose, Aharon und Chur stiegen auf den Gipfel des Hügels.',
        11: 'Und es geschah, so wie Mose seine Hand emporhob, da hatte Israel die Übermacht und wie er seine Hand niedersinken ließ, hatte Amalek die Übermacht.',
        12: 'Und Moses Hände wurden schwer; und sie nahmen einen Stein und legten denselben unter ihn und er setzte sich darauf, und Aharon und Chur stützten seine Hände, der eine hier, der andere dort, und so geschah es, daß seine Hände festblieben, bis die Sonne unterging.',
        13: 'Und Jehoschua schwächte den Amalek und sein Volk mit der Schärfe des Schwertes.',
        14: 'Und Jehovah sprach zu Mose: Schreib dies zum Andenken in das Buch und bring es vor die Ohren Jehoschuas, daß Ich das Andenken an Amalek gänzlich auswischen will unter dem Himmel.',
        15: 'Und Mose baute einen Altar und nannte seinen Namen Jehovah Nissi.',
        16: 'Und sprach: Weil die Hand ist wider den Thron Jahs, hat Jehovah Krieg wider Amalek von Geschlecht zu Geschlecht.',
    },
    18: {
        1: 'Und Jethro, der Priester von Midjan, Moses Schwäher, hörte alles, was Gott an Mose und seinem Volke Israel getan, daß Jehovah Israel von Ägypten herausgebracht hatte;',
        2: 'Und Jethro, Moses Schwäher, nahm Zipporah, Moses Weib, nach ihrer Entlassung;',
        3: 'Und ihre zwei Söhne, von denen der Name des einen Gerschon war; denn er sprach: Ich war ein Fremdling in auswärtigem Lande.',
        4: 'Und der Name des anderen war Eleser; denn der Gott meines Vaters war mein Beistand und errette mich von dem Schwerte Pharaos.',
        5: 'Und es kam Jethro, Moses Schwäher, und seine Söhne und sein Weib zu Mose in die Wüste, wo er lagerte am Berge Gottes,',
        6: 'Und er sprach zu Mose: Ich, dein Schwäher Jethro, komme zu dir und dein Weib und ihre zwei Söhne mit ihr.',
        7: 'Und Mose ging hinaus seinem Schwäher entgegen und verbeugte sich vor ihm und küßte ihn; und sie fragten einander um den Frieden und kamen in das Zelt.',
        8: 'Und Mose erzählte seinem Schwäher alles, was Jehovah an Pharao und an den Ägyptern um Israels willen getan, all das Mühsal, das sie auf dem Wege getroffen und wie Jehovah sie errettet hätte.',
        9: 'Und Jethro freute sich über alles Gute, das Jehovah an Israel getan, daß Er es aus der Hand der Ägypter errettet hatte.',
        10: 'Und Jethro sprach: Gesegnet sei Jehovah, Der euch errettet aus der Hand der Ägypter und aus der Hand Pharaos, Der das Volk aus der Hand der Ägypter errettet hat.',
        11: 'Nun weiß ich, daß Jehovah größer ist denn alle Götter; denn es war in der Sache, in der sie sich vermaßen über sie.',
        12: 'Und Jethro, Moses Schwäher, nahm für Gott Brandopfer und Schlachtopfer, und Aharon kam und alle Ältesten Israels, das Brot zu essen mit Moses Schwäher vor Gott.',
        13: 'Und am morgenden Tage geschah, daß Mose saß das Volk zu richten; und das Volk stand bei Mose vom Morgen bis zum Abend.',
        14: 'Und Moses Schwäher sah alles, was er dem Volke tat, und sagte: Was ist dies, das du dem Volke tust? Warum sitzest du allein und alles Volk stellt sich bei dir vom Morgen bis zum Abend?',
        15: 'Und Mose sprach zu seinem Schwäher: Das Volk kommt zu mir, Gott zu befragen.',
        16: 'So sie eine Sache haben, kommen sie zu mir, und ich richte zwischen dem Mann und seinem Genossen und lasse sie die Satzungen Gottes und seine Gesetze wissen.',
        17: 'Und Moses Schwäher sagte zu ihm: Das Wort ist nicht gut, das du tust.',
        18: 'Du ermattest und auch dieses Volk, das bei dir ist. Denn die Sache ist zu schwer für dich, du vermagst es allein nicht zu tun.',
        19: 'So höre denn auf meine Stimme. Ich will dir raten und Gott sei mit dir! Sei du für das Volk vor Gott und bringe du die Sachen vor Gott.',
        20: 'Und warne sie ob der Satzungen und Gesetze, und laß sie den Weg wissen, den sie gehen und das Werk, das sie tun sollen.',
        21: 'Und du erschaue dir aus allem Volk tüchtige Männer, gottesfürchtige, Männer der Wahrheit, die Gewinn hassen, und setze sie über dasselbe als Oberste über tausend, als Oberste über hundert, als Oberste über fünfzig und als Oberste über zehn.',
        22: 'Und sie sollen das Volk richten zu jeder Zeit. Und soll sein, jede große Sache sollen sie zu dir bringen und jede kleine Sache selber richten; so wirst du es leichter haben und sie tragen mit dir.',
        23: 'Tust du dies Ding und gebietet dir es Gott, so vermagst du zu bestehen, und auch dies Volk mag in Frieden an seinen Ort kommen.',
        24: 'Und Mose hörte auf die Stimme seines Schwähers und tat alles, was er gesagt hatte.',
        25: 'Und Mose wählte tüchtige Männer aus ganz Israel und setzte sie zur Häuptern über das Volk, zu Obersten über tausend, zu Obersten über hundert, zu Obersten über fünfzig und zu Obersten über zehn.',
        26: 'Und sie richteten das Volk zu jeder Zeit, brachten die härtere Sache zu Mose, und alle kleinere Sache richteten sie selbst.',
        27: 'Und Mose entließ seinen Schwäher und er ging für sich in sein Land.',
    },
    19: {
        1: 'Im dritten Monat des Auszugs der Söhne Israels aus dem Lande Ägypten an demselben Tage kamen sie in die Wüste Sinai.',
        2: 'Und von Rephidim brachen sie auf und kamen in die Wüste Sinai, und lagerten in der Wüste, und Israel lagerte sich dem Berge gegenüber.',
        3: 'Und Mose stieg hinauf zu Gott, und Jehovah rief ihm vom Berge und sprach: So sollst du sprechen zum Hause Jakob, und ansagen den Söhnen Israels.',
        4: 'Ihr habt gesehen, was Ich den Ägyptern getan, und wie Ich euch auf Adlersflügeln getragen und zu Mir gebracht habe.',
        5: 'Und nun, wenn ihr gewißlich auf Meine Stimme höret und Meinen Bund haltet, so sollt ihr Mir zum Eigentum sein vor allen Völkern; denn Mein ist die ganze Erde.',
        6: 'Und ihr sollt Mir ein Königreich von Priestern sein und eine heilige Völkerschaft. Dies sind die Worte, die du zu den Söhnen Israels reden sollst.',
        7: 'Und Mose kam und rief die Ältesten des Volkes und legte ihnen alle diese Worte vor, die ihm Jehovah geboten hatte.',
        8: 'Und das ganze Volk antwortete allzumal und sie sprachen: Alles, was Jehovah geredet hat, wollen wir tun. Und Mose brachte die Worte des Volkes zurück zu Jehovah.',
        9: 'Und Jehovah sprach zu Mose: Siehe, Ich komme zu dir in einer dichten Wolke, auf daß das Volk höre, wenn Ich mit dir rede, und auch an dich glaube ewiglich. Und Mose sagte an die Worte des Volkes dem Jehovah.',
        10: 'Und Jehovah sprach zu Mose: Gehe zu dem Volk und heilige sie heute und morgen, und laß sie ihre Gewänder waschen.',
        11: 'Und sie sollen bereit sein auf den dritten Tag; denn am dritten Tage wird Jehovah vor den Augen des ganzen Volkes herabkommen auf den Berg Sinai.',
        12: 'Und setze dem Volk eine Grenze ringsum und sprich: Hütet euch, daß ihr nicht auf den Berg hinaufsteiget, noch sein Ende berühret. Jeder, der den Berg berührt, soll des Todes sterben.',
        13: 'Keine Hand soll ihn berühren; sondern gesteinigt oder mit Geschoß erschossen soll er werden. Sei es Vieh oder Mensch, er soll nicht am Leben bleiben. Beim Blasen des Jobelhorns sollen sie den Berg heraufkommen.',
        14: 'Und Mose kam vom Berg herab zum Volk und heiligte das Volk, und sie wuschen ihre Gewänder.',
        15: 'Und er sprach zu dem Volke: Seid bereit in drei Tagen und nahet keinem Weibe.',
        16: 'Und es geschah am dritten Tage, als es Morgen ward, daß da waren Stimmen und Blitze und eine schwere Wolke auf dem Berge und eine sehr starke Stimme der Posaune, so daß das ganze Volk, das im Lager war, erzitterte.',
        17: 'Und Mose brachte das Volk aus dem Lager Gott entgegen und sie stellten sich unten am Berge auf.',
        18: 'Und der ganze Berg Sinai rauchte, darum daß Jehovah im Feuer auf ihn herabkam, und sein Rauch stieg auf, wie der Rauch eines Ofens, und der ganze Berg erzitterte sehr.',
        19: 'Und die Stimme der Posaune erging und ward sehr stark. Mose redete und Gott antwortete ihm mit einer Stimme.',
        20: 'Und Jehovah stieg herab auf den Berg Sinai, auf den Gipfel des Berges, und Jehovah rief Mose auf den Gipfel des Berges und Mose stieg hinauf.',
        21: 'Und Jehovah sprach zu Mose: Geh hinab und bezeuge dem Volk, daß sie nicht durchbrechen zu Jehovah, um zu sehen und viele von ihnen fallen.',
        22: 'Und auch die Priester, die zu Jehovah herzutreten, sollen sich heiligen, auf daß Jehovah nicht gegen sie hervorbreche.',
        23: 'Und Mose sprach zu Jehovah: Das Volk vermag nicht zu dem Berg Sinai heraufzukommen; denn Du hast uns bezeugt und gesprochen: Setze Grenzen an den Berg und heilige ihn.',
        24: 'Und Jehovah sprach zu ihm: Geh, steig hinab und komm du und Aharon mit dir herauf; und die Priester und das Volk sollen nicht durchbrechen, um zu Jehovah heraufzusteigen, auf daß Er nicht hervorbreche gegen sie.',
        25: 'Und Mose ging hinab zum Volk und sprach zu ihnen.',
    },
    20: {
        1: 'Und Gott redete all diese Worte und sprach:',
        2: 'Ich bin Jehovah, dein Gott, Der dich aus Ägyptenland, aus dem Hause der Knechte herausgebracht hat.',
        3: 'Du sollst keine anderen Götter haben vor Meinem Angesicht.',
        4: 'Du sollst dir kein Schnitzbild, noch irgendein Abbild dessen machen, was im Himmel oben, noch dessen, was auf Erden unten, noch dessen, was in den Wassern unter der Erde ist.',
        5: 'Du sollst sie nicht anbeten, noch ihnen dienen; denn Ich bin Jehovah, dein Gott, ein eifriger Gott, Der da heimsucht die Missetat der Väter an den Söhnen bis ins dritte und vierte Glied, bei denen, die Mich hassen;',
        6: 'Und tue Barmherzigkeit an Tausenden, die Mich lieben und Meine Gebote halten.',
        7: 'Du sollst den Namen Jehovahs, deines Gottes, nicht ins Eitle führen; denn Jehovah wird den nicht ungestraft lassen, der Seinen Namen ins Eitle führt.',
        8: 'Gedenke des Sabbathtages, daß du ihn heiligest.',
        9: 'Sechs Tage sollst du arbeiten und all dein Werk tun.',
        10: 'Aber der siebente Tag ist ein Sabbath Jehovah, deinem Gott. Da sollst du kein Werk tun, weder du, noch dein Sohn, noch deine Tochter, dein Knecht, noch deine Magd, noch dein Vieh, noch dein Fremdling, der in deinen Toren ist.',
        11: 'Denn in sechs Tagen hat Jehovah den Himmel und die Erde gemacht, das Meer und alles, was darinnen ist, und geruht am siebenten Tage; darum segnete Jehovah den Sabbathtag und heiligte ihn.',
        12: 'Ehre deinen Vater und deine Mutter, damit deine Tage verlängert werden auf dem Boden, den Jehovah, dein Gott, dir geben wird.',
        13: 'Du sollst nicht töten.',
        14: 'Du sollst nicht ehebrechen.',
        15: 'Du sollst nicht stehlen.',
        16: 'Du sollst kein falsch Zeugnis reden, wider deinen Nächsten.',
        17: 'Du sollst dich nicht gelüsten lassen des Hauses deines Nächsten; du sollst dich nicht gelüsten lassen des Weibes deines Nächsten, noch seines Knechtes, noch seiner Magd, noch seines Ochsen, noch seines Esels, noch irgend etwas, das dein Nächster hat.',
        18: 'Und alles Volk sah die Stimmen und die Flammen, und den Schall der Posaunen und das Rauchen des Berges. Und das Volk sah es, und sie erbebten und stunden von ferne.',
        19: 'Und sprachen zu Mose: Rede du mit uns und wir wollen hören. Gott aber möge nicht mit uns reden; auf daß wir nicht sterben.',
        20: 'Und Mose sprach zum Volke: Fürchtet euch nicht; denn Gott ist darum gekommen, daß Er euch versuche, und darum daß Seine Furcht vor eurem Angesicht sei, auf daß ihr nicht sündigt.',
        21: 'Und das Volk stand von ferne, Mose aber trat herzu zu dem Wolkendunkel, da Gott war.',
        22: 'Und Jehovah sprach zu Mose: So sprich zu den Söhnen Israels: Ihr habt gesehen, daß Ich aus dem Himmel mit euch geredet habe.',
        23: 'Ihr sollt neben Mir nicht silberne Götter machen und Götter von Gold sollt ihr euch nicht machen.',
        24: 'Einen Altar aus Grund sollst du Mir machen, und darauf deine Brandopfer und deine Friedensopfer, dein Kleinvieh und deine Rinder opfern. An jeglichem Orte, wo Ich ein Gedächtnis Meines Namens stiften werde, will Ich zu dir kommen und dich segnen.',
        25: 'Und wenn du Mir einen Altar von Steinen machst, so baue ihn nicht mit behauenen; denn so du deine Eisen darüber schwingst, entweihst du ihn.',
        26: 'Und du sollst nicht auf Stufen zu Meinem Altar hinaufsteigen, auf daß deine Blöße nicht aufgedeckt werde an ihm.',
    },
    21: {
        1: 'Und dies sind die Gerichte, die du vor sie legen sollst:',
        2: 'So du einen hebräischen Knecht kaufst, soll er sechs Jahre dienen und im siebenten soll er frei ausgehen umsonst.',
        3: 'Ist er allein gekommen, so soll er auch allein ausgehen. Ist er der Gemahl eines Weibes, so soll sein Weib mit ihm ausgehen.',
        4: 'Hat ihm sein Herr ein Weib gegeben, und sie ihm Söhne oder Töchter geboren, so sei das Weib und ihre Kinder ihrem Herrn, und er geht allein aus.',
        5: 'Und wenn der Knecht spricht: Ich liebe meinen Herrn, mein Weib und meine Söhne, ich will nicht frei ausgehen;',
        6: 'So lasse ihn sein Herr herzutreten vor Gott, und lasse ihn an die Tür oder den Türpfosten treten, und sein Herr durchbohre ihm mit einem Pfriemen das Ohr, daß er ihm diene für immer.',
        7: 'Und verkauft ein Mann seine Tochter als Magd, so soll sie nicht ausgehen, wie die Knechte ausgehen.',
        8: 'Ist sie übel in den Augen ihres Herrn, daß er sie sich nicht antraut, so lasse er sie einlösen; an auswärtiges Volk sie zu verkaufen, soll er keine Macht haben, daß er treulos gegen sie handle.',
        9: 'So er sie aber seinem Sohne antraut, so soll er nach dem Gericht der Töchter an ihr tun.',
        10: 'Nimmt er ihm eine andere dazu, so soll er von ihrer Kost, ihrer Decke und ihrer ehelichen Pflicht nichts verringern.',
        11: 'Und tut er ihr diese drei nicht, so soll sie frei ohne Silber ausgehen.',
        12: 'Wer einen Mann schlägt, daß er stirbt, der soll des Todes sterben.',
        13: 'Hat er ihm aber nicht nachgestellt und ließ ihn Gott seiner Hand begegnen, so will ich dir einen Ort bestimmen, dahin er fliehen mag.',
        14: 'Vermißt sich aber ein Mann an seinem Genossen, um ihn mit List zu erwürgen, sollst du ihn von Meinem Altare wegnehmen, daß er sterbe.',
        15: 'Und wer seinen Vater und seine Mutter schlägt, der soll des Todes sterben.',
        16: 'Und wer einen Mann stiehlt und ihn verkauft, und er wird in seiner Hand gefunden, der soll des Todes sterben.',
        17: 'Und wer seinem Vater und seiner Mutter flucht, der soll des Todes sterben.',
        18: 'Und wenn Männer miteinander hadern und ein Mann den Genossen schlägt mit einem Stein oder mit der Faust und stirbt nicht, fällt aber auf das Lager;',
        19: 'So soll, wenn er aufsteht und mit einer Stütze auf der Straße geht, der ihn schlug, ungestraft bleiben, nur für seine Versäumnis soll er ihm geben und ihn heilen lassen.',
        20: 'Und schlägt ein Mann seinen Knecht, oder seine Magd mit dem Stocke, so daß er unter seiner Hand stirbt, so soll es gerächt werden.',
        21: 'Bleibt er aber noch einen oder zwei Tage, so soll es nicht gerächt werden; denn es ist sein Geld.',
        22: 'Und wenn Männer sich zanken und stoßen ein schwangeres Weib, daß die Frucht von ihr ausgeht, aber sonst kein Unfall geschieht, so soll er um Geld gestraft werden, so viel der Gemahl des Weibes ihm auferlegt, und soll es vor Schiedsrichter geben.',
        23: 'Ist aber ein Unfall geschehen, sollst du geben Seele um Seele.',
        24: 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß;',
        25: 'Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme.',
        26: 'Und schlägt ein Mann seinen Knecht ins Auge oder seine Magd ins Auge und verdirbt es, soll er ihn frei entlassen um des Auges willen.',
        27: 'Und wenn einer seinem Knecht einen Zahn oder seiner Magd einen Zahn ausschlägt, so soll er ihn frei entlassen um des Zahnes willen.',
        28: 'Und wenn ein Ochse einen Mann oder ein Weib stößt, so daß er stirbt, so soll der Ochse gesteinigt, sein Fleisch aber nicht gegessen werden, und der Herr des Ochsen soll ungestraft bleiben.',
        29: 'War aber der Ochse stößig seit gestern und ehegestern, und es war seinem Herrn bezeugt worden, und er hat ihn nicht verwahrt, und tötet er einen Mann oder ein Weib, so soll der Ochse gesteinigt werden und auch sein Herr sterben.',
        30: 'Wird ihm eine Sühne auferlegt, so gebe er als Lösegeld für seine Seele, alles, was ihm auferlegt worden ist.',
        31: 'Oder stößt er einen Sohn oder stößt er eine Tochter, so tue man ihm nach dem selbigen Gericht.',
        32: 'Stößt der Ochse einen Knecht oder eine Magd, so gebe er dreißig Silbersekel seinem Herrn und der Ochse werde gesteinigt.',
        33: 'Und so ein Mann eine Grube öffnet, oder so ein Mann eine Grube gräbt, und sie nicht bedeckt, und es fällt ein Ochse oder ein Esel hinein,',
        34: 'So soll der Herr der Grube Ersatz geben und seinem Herrn das Silber zurückgeben, das Tote aber gehört ihm.',
        35: 'Und so eines Mannes Ochse, den Ochsen seines Genossen stößt, daß er stirbt, so sollen sie den lebendigen Ochsen verkaufen und das Silber teilen und auch den toten sollen sie teilen.',
        36: 'Oder, wenn bekannt war, daß der Ochse stößig war seit gestern und ehegestern, und sein Herr ihn nicht verwahrt hatte, so soll er Ochsen für Ochsen erstatten, der tote aber soll ihm gehören. Wenn ein Mann einen Ochsen oder eines vom Kleinvieh gestohlen und es geschlachtet oder verkauft hat, so soll er fünf Rinder für den Ochsen, und vier vom Kleinvieh für eines vom Kleinvieh erstatten.',
    },
    22: {
        1: 'Wenn ein Dieb über dem Einbruch erfunden und geschlagen wird, daß er stirbt, so ist es keine Blutschuld.',
        2: 'Ist aber die Sonne über ihm aufgegangen, so ist es ihm Blutschuld. Er soll erstatten. Hat er nichts, so soll er für seinen Diebstahl verkauft werden.',
        3: 'Wird das Gestohlene in seiner Hand gefunden, sei es Ochse oder Esel oder Lamm, lebendig, so soll er das Doppelte erstatten.',
        4: 'So ein Mann ein Feld oder einen Weinberg abweidet und sein Vieh hineinläßt, daß es das Feld eines anderen abweide, so soll er es mit dem Besten seines Feldes und dem Besten seines Weinbergs erstatten.',
        5: 'So ein Feuer ausgeht und Dornen ergreift, so daß ein Garbenhaufe oder die stehende Saat oder das Feld verzehrt wird, so hat, der den Brand angesteckt, es zu erstatten.',
        6: 'Wenn ein Mann seinem Genossen Silber oder Gerät zur Verwahrung gibt, und es wird gestohlen aus dem Hause des Mannes, so soll der Dieb, wenn man ihn findet, das Doppelte erstatten.',
        7: 'Wenn der Dieb nicht gefunden wird, so lasse man den Hausmeister vor Gott nahen, ob er nicht seine Hand nach seines Genossen Habe ausgestreckt.',
        8: 'Über jeder Sache der Übertretung, sei es ein Ochse, ein Esel, ein Schaf, ein Kleid, alles Verlorene, wovon man sagt, daß es dies sei, so soll beider Sache vor Gott gebracht werden. Wen Gott für ungerecht erklärt, der soll dem Genossen das Doppelte erstatten.',
        9: 'Wenn ein Mann seinem Genossen einen Esel oder einen Ochsen, oder ein Schaf oder irgendein Stück Vieh in Verwahrung gibt, und es stirbt oder wird beschädigt oder gefangen weggetrieben, ohne daß es jemand sieht;',
        10: 'So soll ein Schwur vor Jehovah, zwischen beiden sein, ob er nicht seine Hand nach seines Genossen Habe ausgestreckt und sein Herr nehme es an, und er hat es nicht zu erstatten.',
        11: 'Ist es ihm aber gestohlen worden, so soll er es seinem Herrn erstatten.',
        12: 'Ist es zerfleischt worden, so bringe er es zum Zeugnis. Das Zerfleischte hat er nicht zu erstatten.',
        13: 'Und wenn ein Mann von seinem Genossen etwas entlehnt hat, und es wird beschädigt oder stirbt, ohne daß sein Herr dabei ist, so soll er es erstatten.',
        14: 'Wenn sein Herr dabei ist, so soll er es nicht erstatten. Ist es gemietet, so geht es in die Miete.',
        15: 'Und wenn ein Mann eine Jungfrau beredet, die noch nicht verlobt ist, und liegt bei ihr, so soll er sie sich durch Morgengabe zum Weib erwerben.',
        16: 'Weigert sich aber ihr Vater, sie ihm zu geben, so soll er Silber darwägen, je nach der Morgengabe der Jungfrauen.',
        17: 'Eine Zauberin sollst du nicht am Leben lassen.',
        18: 'Jeder, der bei dem Vieh liegt, der soll des Todes sterben.',
        19: 'Wer den Göttern opfert außer dem Jehovah allein, der sei verbannt.',
        20: 'Und den Fremdling sollst du nicht drängen, noch unterdrücken; denn ihr waret Fremdlinge im Land Ägypten.',
        21: 'Keine Witwe oder Waise sollt ihr niederdrücken.',
        22: 'Wenn du sie niederdrückst, und er schreit zu Mir, so werde Ich sein Schreien hören.',
        23: 'Und Mein Zorn wird entbrennen und Ich werde euch mit dem Schwerte erwürgen, und eure Weiber sollen Witwen und eure Söhne Waisen werden.',
        24: 'Wenn du Meinem Volk, das elend ist bei dir, Silber leihst, so sollst du ihm nicht wie Wucherer sein, ihr sollt ihm keinen Zins auferlegen.',
        25: 'Wenn du von deinem Genossen das Gewand zum Pfande nimmst, sollst du es ihm, wenn die Sonne untergeht, zurückgeben.',
        26: 'Denn seine einzige Decke ist es für seine Haut ist sein Gewand, darin er sich legt. Und wird sein, wenn er zu Mir schreit, so werde Ich ihn hören; denn Ich bin gnädig.',
        27: 'Gott sollst du nicht fluchen, noch einen Fürsten in deinem Volk verfluchen.',
        28: 'Mit den Erstlingen deines Getreides und deines Weines sollst du nicht zögern. Den Erstgeborenen deiner Söhne sollst du Mir geben.',
        29: 'Also sollst du tun mit deinem Ochsen und deinem Kleinvieh. Sieben Tage soll es bei seiner Mutter sein, am achten Tage sollst du es Mir geben.',
        30: 'Und Männer der Heiligkeit sollt ihr Mir sein; und Fleisch dessen, das auf dem Feld zerfleischt worden, sollt ihr nicht essen, den Hunden werfet es hin.',
    },
    23: {
        1: 'Trage kein eitles Gerücht aus. Biete deine Hand nicht dem Ungerechten, um Zeuge für eine Gewalttat zu werden.',
        2: 'Folge nicht den Vielen zum Bösen; und zeuge nicht bei einem Rechtshandel, um ihn abzulenken, so daß du zu der Menge ablenkst.',
        3: 'Und den Armen sollst du in seinem Rechtshandel nicht begünstigen.',
        4: 'So du auf den Ochsen deines Feindes oder seinen Esel, der in der Irre geht, stoßest, sollst du ihn ihm zurückbringen.',
        5: 'Wenn du den Esel dessen, der dich haßt, unter seiner Last niederliegen siehst, und wolltest unterlassen, ihn zu entledigen, so sollst du gleichwohl ihn mit jenem entledigen.',
        6: 'Du sollst das Recht deines Dürftigen nicht ablenken in seinem Rechtshandel.',
        7: 'Halte dich fern vom Worte der Lüge und erwürge nicht den Unschuldigen und Gerechten; denn Ich werde den Ungerechten nicht rechtfertigen.',
        8: 'Und ein Geschenk sollst du nicht nehmen; denn Geschenk verblendet die Sehenden und verdreht die Worte der Gerechten.',
        9: 'Und den Fremdling unterdrücke nicht; denn ihr wisset um des Fremdlings Seele, denn ihr waret Fremdlinge im Lande Ägypten.',
        10: 'Und sechs Jahre sollst du in dein Land säen und dessen Ertrag sammeln.',
        11: 'Im siebenten aber sollst du ablassen und es preisgeben, daß die Dürftigen deines Volkes davon essen, und was sie übriglassen, das Wild des Feldes fresse. So sollst du mit deinem Weinberg und deinem Ölgarten tun.',
        12: 'Sechs Tage sollst du dein Werk tun, am siebenten Tag aber feiern, auf daß dein Ochse und dein Esel ruhen, und der Sohn deiner Magd und der Fremdling sich erholen.',
        13: 'Und alles, was Ich zu euch gesprochen, sollt ihr halten; und des Namens anderer Götter sollt ihr nicht gedenken, er soll nicht aus eurem Munde gehört werden.',
        14: 'Dreimal sollst du Mir Fest feiern im Jahr.',
        15: 'Das Fest des Ungesäuerten sollst du halten, sieben Tage Ungesäuertes essen, wie Ich dir geboten, zur bestimmten Zeit des Monats Abib; denn in demselben bist du aus Ägypten ausgegangen. Ihr sollt aber nicht leer Mein Angesicht sehen.',
        16: 'Und das Fest der Ernte, der Erstlinge deiner Werke, die du sätest in das Feld; und das Fest der Einsammlung am Ausgang des Jahres, wenn du deine Werke vom Feld sammelst.',
        17: 'Dreimal im Jahr erscheine alles Männliche bei dir vor dem Angesicht des Herrn Jehovah!',
        18: 'Nicht sollst du auf Gesäuertem opfern das Blut Meines Opfers, noch soll bleiben das Fett Meines Festes über Nacht bis zum Morgen.',
        19: 'Das Erste der Erstlinge deines Bodens sollst du ins Haus Jehovahs, deines Gottes, bringen, das Böcklein nicht in der Milch seiner Mutter kochen.',
        20: 'Siehe, Ich sende einen Engel vor dir her, dich zu behüten auf dem Weg, und dich zu bringen an den Ort, den Ich bereitet habe.',
        21: 'Hüte dich vor Seinem Angesicht und höre auf Seine Stimme; erbittere Ihn nicht, denn eure Übertretung erträgt Er nicht; denn Mein Name ist in Seiner Mitte.',
        22: 'Wenn du aber auf Seine Stimme hören und alles tun wirst, was Ich zu dir reden werde, so will Ich ein Feind sein deinen Feinden und ein Bedränger deiner Bedränger.',
        23: 'Wenn vor dir hergehen wird Mein Engel und dich bringen zu den Amoritern und Chethitern und Pherisitern und Kanaanitern und den Chivitern und den Jebusitern, die Ich wegschaffen werde.',
        24: 'Du sollst ihre Götter nicht anbeten, noch ihnen dienen, und sollst nicht tun nach ihrem Tun, sondern niederreißen und zerbrechen ihre Bildsäulen.',
        25: 'Aber Jehovah, eurem Gotte sollt ihr dienen, so wird Er segnen dein Brot und dein Wasser, und Krankheit von eurer Mitte werde Ich wegnehmen.',
        26: 'Keine wird fehlgebären, keine unfruchtbar sein in deinem Lande. Ich werde deiner Tage Zahl voll machen.',
        27: 'Meinen Schrecken will Ich vor dir senden und verwirren alles Volk, zu dem du kommst, und geben, daß alle Feinde dir den Nacken kehren.',
        28: 'Und Hornisse will Ich vor dir senden und die Chiviter, die Kanaaniter und die Chethiter vor dir vertreiben.',
        29: 'Nicht in einem Jahr will Ich sie vor dir vertreiben, auf daß das Land nicht wüste werde, und sich das Wild des Feldes wider dich vermehre.',
        30: 'Nach und nach vertreibe Ich sie vor dir, bis daß du fruchtbar wirst und das Land erbest.',
        31: 'Und deine Grenze werde Ich setzen vom Schilfmeer bis zum Meer der Philister, und von der Wüste bis zum Flusse; denn Ich will die Einwohner des Landes geben in eure Hand, und sie vertreiben vor dir.',
        32: 'Keinen Bund sollst du mit ihnen und ihren Göttern schließen.',
        33: 'Sie sollen nicht in deinem Lande wohnen, daß sie dich nicht sündigen machen wider Mich; denn so du ihren Göttern dienest, wird es dir zum Fallstrick werden.',
    },
    24: {
        1: 'Und zu Mose sprach Er: Steige herauf zu Jehovah, du und Aharon, Nadab und Abihu, und siebzig von den Ältesten Israels, und betet an von ferne.',
        2: 'Und Mose trete allein herzu zu Jehovah, sie aber sollen nicht herzutreten, und das Volk komme nicht mit ihm herauf.',
        3: 'Und Mose kam und erzählte dem Volke alle die Worte Jehovahs und alle die Gerichte, und das ganze Volk antwortete mit einer Stimme und sie sprachen: Alle Worte, die Jehovah geredet, werden wir tun.',
        4: 'Und Mose schrieb alle die Worte Jehovahs, und machte sich früh auf am Morgen und baute einen Altar unten am Berge und zwölf Denksäulen für die zwölf Stämme Israels;',
        5: 'Und sandte Jünglinge der Söhne Israels hin, und sie ließen Brandopfer aufgehen und opferten Opfer des Friedens von Farren dem Jehovah.',
        6: 'Und Mose nahm die Hälfte des Blutes und tat es in die Becken, die Hälfte des Blutes aber sprengte er über den Altar.',
        7: 'Und er nahm das Buch des Bundes und las es vor den Ohren des Volkes, und sie sprachen: Alles, was Jehovah geredet hat, werden wir tun und Ihm gehorchen.',
        8: 'Und Mose nahm das Blut und sprengte es über das Volk und sprach: Siehe, dies ist das Blut des Bundes, den Jehovah über alle diese Worte mit euch geschlossen hat.',
        9: 'Und Mose stieg, und Aharon, Nadab und Abihu und siebzig von den Ältesten Israels hinauf;',
        10: 'Und sie sahen den Gott Israels, und unter Seinen Füßen war wie ein Werk von Saphirstein und wie Stoff des Himmels an Reinheit.',
        11: 'Und an die Ausgesonderten der Söhne Israels legte Er nicht Seine Hand. Und sie erschauten Gott und aßen und tranken.',
        12: 'Und Jehovah sprach zu Mose: Steige herauf zu Mir auf den Berg und sei da, und Ich werde dir die steinernen Tafeln und das Gesetz und das Gebot geben, das Ich zu ihrer Unterweisung geschrieben habe.',
        13: 'Und Mose machte sich auf und Jehoschua sein Diener; und Mose stieg auf den Berg Gottes.',
        14: 'Und zu den Ältesten sprach er: Sitzet für uns hier, bis wir zu euch zurückkommen, und siehe, Aharon und Chur sind bei euch. Wer immer eine Streitsache hat, der trete herbei zu ihnen.',
        15: 'Und Mose stieg auf den Berg, und die Wolke bedeckte den Berg.',
        16: 'Und die Herrlichkeit Jehovahs wohnte auf dem Berge Sinai, und die Wolke bedeckte ihn sechs Tage; und Er rief zu Mose am siebenten mitten aus der Wolke.',
        17: 'Und das Ansehen der Herrlichkeit Jehovahs war wie ein fressendes Feuer auf dem Gipfel des Berges vor den Augen der Söhne Israels.',
        18: 'Und Mose ging mitten in die Wolke und stieg den Berg hinauf; und Mose war vierzig Tage und vierzig Nächte auf dem Berg.',
    },
    25: {
        1: 'Und Jehovah redete zu Mose und sprach:',
        2: 'Rede zu den Söhnen Israels, daß sie für Mich eine Hebe nehmen; von jedem Manne, den sein Herz freiwillig treibt, sollt ihr nehmen die Hebe.',
        3: 'Und das ist die Hebe, die ihr von ihnen nehmen sollet: Gold und Silber und Erz.',
        4: 'Und Purpurblau und Purpurrot, Scharlach doppelt gefärbt und Byssus und Ziegenhaar.',
        5: 'Und rote Widderfelle und Dachsfelle und Schittimholz.',
        6: 'Öl für den Leuchter, Gewürze zum Salböl und zum Räucherwerk der Spezereien.',
        7: 'Onychsteine, und Steine zu Füllungen für das Ephod und für das Brustschildlein.',
        8: 'Und sie sollen Mir ein Heiligtum machen, auf daß Ich in ihrer Mitte wohne.',
        9: 'Nach allem wozu Ich dir das Vorbild der Wohnung und das Vorbild aller seiner Geräte sehen lasse, so sollt ihr es machen.',
        10: 'Und sie sollen eine Lade von Schittimholz machen, zwei Ellen und eine halbe seine Länge, und eine Elle und eine halbe ihre Breite, und eine Elle und eine halbe ihre Höhe.',
        11: 'Und überziehe sie mit reinem Gold, von innen und von außen sollst du sie überziehen, und mache rings herum einen goldenen Kranz daran.',
        12: 'Und gieße für sie vier goldene Ringe und setze sie an ihre vier Ecken, und zwei Ringe auf der einen Seitenwand und zwei auf der zweiten Seitenwand.',
        13: 'Und mache Stangen aus Schittimholz und überziehe sie mit Gold.',
        14: 'Und bringe die Stangen in die Ringe an den Seitenwänden der Lade, die Lade damit zu tragen.',
        15: 'In den Ringen der Lade sollen die Stangen sein, sie sollen nicht daraus weggenommen werden.',
        16: 'Und gib in die Lade das Zeugnis, das Ich dir geben werde.',
        17: 'Und du sollst einen Gnadenstuhl von reinem Golde machen, zwei Ellen und eine halbe soll seine Länge, und eine Elle und eine halbe seine Breite sein.',
        18: 'Und sollst zwei Cherube machen, von getriebenem Golde, aus den beiden Enden des Gnadenstuhls sollst du sie machen.',
        19: 'Und mache den einen Cherub von dem einen Ende, und den anderen Cherub von dem anderen Ende; machet die Cherube an den beiden Enden aus dem Gnadenstuhl.',
        20: 'Und die Cherube sollen die Flügel darüberhin ausbreiten, mit ihren Flügeln den Gnadenstuhl überdeckend, und ihre Gesichter einander zugewandt; gegen den Gnadenstuhl seien die Gesichter der Cherube.',
        21: 'Und du sollst den Gnadenstuhl oben auf die Lade tun, und in die Lade das Zeugnis geben, das Ich dir geben will.',
        22: 'Und dort komme Ich mit dir zusammen und rede mit dir von dem Gnadenstuhl zwischen den beiden Cheruben hervor, die auf der Lade des Zeugnisses sind, mit dir zu reden alles, was Ich dir an die Söhne Israels gebieten werde.',
        23: 'Und einen Tisch sollst du machen von Schittimholz, zwei Ellen seine Länge, und eine Elle seine Breite, und eine Elle und eine halbe seine Höhe.',
        24: 'Und sollst ihn mit reinem Gold überziehen, und ihm ringsum einen Kranz von Gold machen.',
        25: 'Und eine Randleiste eine Handbreit sollst du machen rings herum, und einen Kranz von Gold ringsum für die Randleiste.',
        26: 'Und sollst ihm vier goldene Ringe machen, und die Ringe auf die vier Ecken setzen, die an seinen vier Füßen sind.',
        27: 'Nächst der Randleiste sollen die Ringe sein, als Behälter für die Stangen, um den Tisch zu tragen.',
        28: 'Und die Stangen mache aus Schittimholz und überziehe sie mit Gold, daß mit ihnen der Tisch getragen werde.',
        29: 'Auch mache seine Schüsseln und seine Platten und seine Becher und seine Trankopferschalen, womit er gedeckt wird; aus reinem Gold sollst du sie machen.',
        30: 'Und gib auf den Tisch die Schaubrote vor Mein Angesicht beständig.',
        31: 'Und mache einen Leuchter von reinem Gold; in getriebener Arbeit werde der Leuchter gemacht. Sein Schaft und seine Röhre, seine Kelche, seine Knäufe und seine Blumen sollen aus ihm sein.',
        32: 'Und sechs Röhren sollen aus seinen Seiten ausgehen; drei Röhren des Leuchters aus der einen Seite, und drei Röhren des Leuchters aus der zweiten Seite.',
        33: 'Drei mandelblütförmige Kelche seien an einer Röhre mit Knauf und Blume, und drei mandelblütförmige Kelche an der anderen Röhre mit Knauf und Blume, so bei den sechs Röhren, die von dem Leuchter ausgehen.',
        34: 'Und am Leuchter sollen vier mandelblütförmige Kelche mit ihren Knäufen und Blumen sein.',
        35: 'Und ein Knauf sei unter zwei Röhren aus demselben, und ein Knauf unter zwei Röhren aus demselben, und ein Knauf unter zwei Röhren unter demselben; an den sechs Röhren, die von dem Leuchter ausgehen.',
        36: 'Ihre Käufe und Röhren seien aus ihm selbst; alles an ihm sei aus einer getriebenen Arbeit von reinem Gold.',
        37: 'Und mache seiner Lampen sieben, daß man seine Lampen aufstecke und leuchten lasse gegen sein Angesicht.',
        38: 'Und seine Lichtputzen und Löschnäpfe seien von reinem Gold.',
        39: 'Aus einem Talent reinen Goldes mache man ihn, samt allen diesen Gefäßen.',
        40: 'Und siehe zu, und mache es nach dem Vorbild derselben, das dir auf dem Berge gezeigt worden ist.',
    },
    26: {
        1: 'Und die Wohnung sollst du machen aus zehn Teppichen von gezwirntem Byssus und blauem und rotem Purpur und Scharlach; mit Cheruben, dem Werke des Kunstwirkers, sollst du sie machen.',
        2: 'Die Länge eines Teppichs sei achtundzwanzig Ellen und die Breite vier Ellen für einen Teppich; ein Maß für alle Teppiche.',
        3: 'Fünf Teppiche füge man zusammen, einen an den anderen, und wieder fünf Teppiche füge man zusammen, einen an den andern.',
        4: 'Und mache Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende bei der Zusammenfügung, und so sollst du es machen am Saume des äußersten Teppichs bei der zweiten Zusammenfügung.',
        5: 'Fünfzig Schleifen sollst du an dem einen Teppich machen, und fünfzig Schleifen sollst du machen am Ende des Teppichs an der zweiten Zusammenfügung, so daß die Schleifen einander gegenüberstehen.',
        6: 'Und mache fünfzig Haken von Gold, und füge die Teppiche zusammen durch die Haken aneinander, so daß es eine Wohnung werde.',
        7: 'Und mache Teppiche von Ziegenhaar zu einem Zelte über die Wohnung, elf Teppiche sollst du sie machen.',
        8: 'Die Länge eines Teppichs soll dreißig Ellen sein, und die Breite vier Ellen für einen Teppich; ein Maß für die elf Teppiche.',
        9: 'Und füge die fünf Teppiche besonders zusammen und die sechs Teppiche besonders, und mache den sechsten Teppich doppelt an der Vorderseite des Zeltes.',
        10: 'Und mache fünfzig Schleifen an den Saum des einen äußersten Teppichs an der Zusammenfügung und fünfzig Schleifen an den Saum des Teppichs an der zweiten Zusammenfügung.',
        11: 'Und mache fünfzig Haken von Erz, und bringe die Haken in die Schleifen, und füge das Zelt zusammen, daß es eines sei.',
        12: 'Und das Überhangende, was von den Teppichen des Zeltes überfließt, die Hälfte des Teppichs, die überfließt, soll hinten an der Wohnung überhängen.',
        13: 'Und die Elle von hier und die Elle von dort, die von der Länge der Teppiche des Zeltes überflüssig ist, soll auf beiden Seiten der Wohnung überhängen, um sie zu bedekken.',
        14: 'Und mache eine Decke für das Zelt von roten Widderfellen und eine Decke von Dachsfellen darüberhin.',
        15: 'Und mache die Bretter zur Wohnung von Schittimholz, aufrecht stehend.',
        16: 'Zehn Ellen sei die Länge des Brettes und eine Elle und eine halbe Elle die Breite eines Brettes.',
        17: 'Zwei Zapfen an dem einen Brett, fügend ineinander, sollst du machen an allen Brettern der Wohnung.',
        18: 'Und mache die Bretter für die Wohnung: zwanzig Bretter an der Ecke gegen Mittag, südwärts.',
        19: 'Und vierzig silberne Untersätze sollst du machen unter die zwanzig Bretter, zwei Untersätze unter je ein Brett für seine beiden Zapfen, und zwei Untersätze unter ein Brett für seine zwei Zapfen;',
        20: 'Und an der zweiten Seitenwand der Wohnung, in die Ecke gegen Mitternacht, zwanzig Bretter;',
        21: 'Und vierzig Untersätze von Silber; zwei Untersätze unter ein Brett, und zwei Untersätze unter jedes andere Brett;',
        22: 'Und an der hinteren Seite gegen das Meer mache sechs Bretter;',
        23: 'Und zwei Bretter sollst du machen für die Eckstücke der Wohnung an der Hinterseite.',
        24: 'Und sie sollen sein zwiefach von unten an und zugleich zwiefach auf seiner Spitze bis zum ersten Ring. So soll es mit diesen beiden sein, an den zwei Eckstücken sollen sie sein.',
        25: 'Und acht Bretter sollen es sein und ihre silbernen Untersätze, sechzehn Untersätze, zwei Untersätze unter einem Brett, und zwei Untersätze unter jedem anderen Brett.',
        26: 'Und mache Riegel von Schittimholz, fünf für die Bretter einer Seitenwand der Wohnung;',
        27: 'Und fünf Riegel für die Bretter der zweiten Seitenwand der Wohnung an der Hinterseite gegen das Meer;',
        28: 'Und der mittlere Riegel laufe mitten an den Brettern hin von Ende bis zu Ende.',
        29: 'Und die Bretter überziehe mit Gold, und ihre Ringe mache von Gold, als Behälter für die Riegel, und überziehe die Riegel mit Gold.',
        30: 'Und so richte die Wohnung auf nach ihrer Weise, die dir auf dem Berge gezeigt worden ist.',
        31: 'Und mache einen Vorhang von blauem und rotem Purpur und Scharlach, und gezwirntem Byssus, als Werk des Kunstwirkers soll man es machen mit Cheruben.',
        32: 'Und gib ihn an vier Säulen von Schittim, mit Gold überzogen, und ihre Nägel von Gold, auf vier silbernen Untersätzen,',
        33: 'Und den Vorhang gib unter die Haken, und bringe dahin innerhalb des Vorhangs die Lade des Zeugnisses; und der Vorhang scheide euch zwischen dem Heiligen und zwischen dem Allerheiligsten.',
        34: 'Und setze den Gnadenstuhl auf die Lade des Zeugnisses im Allerheiligsten.',
        35: 'Und den Tisch setze außerhalb des Vorhangs, und den Leuchter dem Tisch gerade gegenüber an die Seitenwand der Wohnung gegen Mittag, und den Tisch gib an die Seitenwand gegen Mitternacht.',
        36: 'Und mache eine Decke für den Eingang zum Zelte von blauem und rotem Purpur und Scharlach doppelt gefärbt und gezwirntem Byssus, das Werk eines Buntwirkers.',
        37: 'Und mache zu der Decke fünf Säulen von Schittim, und überziehe sie mit Gold, und ihre Nägel von Gold, und gieße für sie fünf eherne Untersätze.',
    },
    27: {
        1: 'Und den Altar mache aus Schittimholz, fünf Ellen die Länge und fünf Ellen die Breite, Geviert sei der Altar, und drei Ellen seine Höhe.',
        2: 'Und mache seine Hörner an seinen vier Ecken. Aus ihm heraus sollen seine Hörner sein, und überziehe ihn mit Erz.',
        3: 'Und mache seine Töpfe, die Asche wegzutun, und seine Schaufeln und seine Sprengbecken, und seine Fleischgabeln und seine Kohlpfannen. Alle seine Geräte sollst du von Erz machen.',
        4: 'Und mache für ihn ein Gitter, ein Netzwerk aus Erz, und an das Netz sollst du an seinen vier Enden vier eherne Ringe machen.',
        5: 'Und sollst es setzen unter die Einfassung des Altars von unten her, und das Netz sei bis an die Mitte des Altars.',
        6: 'Und mache Stangen für den Altar, Stangen von Schittimholz, und überziehe sie mit Erz.',
        7: 'Und seine Stangen bringe man in die Ringe, und sollen die Stangen an beiden Seitenwänden des Altars sein, wenn man ihn trägt.',
        8: 'Hohl, von Brettern sollst du ihn machen, wie man dir zeigte auf dem Berge, so sollen sie ihn machen.',
        9: 'Und den Vorhof der Wohnung mache an der Seite gegen Mittag südwärts; Behänge für den Vorhof von gezwirntem Byssus hundert Ellen die Länge an der einen Seite.',
        10: 'Und seiner Säulen zwanzig und seiner Untersätze zwanzig von Erz, die Nägel der Säulen und deren Umgürtungen von Silber.',
        11: 'Und so an der Seite gegen Mitternacht der Länge nach Behänge, hundert in die Länge, und seine zwanzig Säulen und deren zwanzig Untersätze von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber.',
        12: 'Und in die Breite des Vorhofs auf der Seite nach dem Meer Behänge, fünfzig Ellen, ihre Säulen zehn und deren zehn Untersätze.',
        13: 'Und in die Breite des Vorhofs auf der Vorderseite gegen Aufgang fünfzig Ellen.',
        14: 'Und fünfzehn Ellen Behänge auf dem Flügel, ihre Säulen drei und ihre Untersätze drei.',
        15: 'Und auf dem zweiten Flügel fünfzehn Behänge, ihre Säulen drei und ihre Untersätze drei.',
        16: 'Und zum Tor des Vorhofs eine Decke von zwanzig Ellen, von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus, das Werk des Buntwirkers, seine Säulen vier und ihre Untersätze vier.',
        17: 'Alle Säulen des Vorhofs ringsum mit silbernen Umgürtungen und ihren silbernen Nägeln und ihren ehernen Untersätzen.',
        18: 'Die Länge des Vorhofes hundert Ellen, und die Breite fünfzig gegen fünfzig, und die Höhe fünf Ellen von gezwirntem Byssus, und ihre Untersätze von Erz.',
        19: 'Alle Geräte der Wohnung für all ihren Dienst, und all ihre Pflöcke und alle Pflöcke des Vorhofs seien von Erz.',
        20: 'Und du gebiete den Söhnen Israels, daß sie dir reines, gestoßenes Olivenöl zum Licht bringen, auf daß man die Lampe beständig aufgehen lasse.',
        21: 'Im Versammlungszelte außerhalb des Vorhangs, der vor dem Zeugnisse ist, soll es Aharon und seine Söhne zurichten vom Abend bis zum Morgen, vor Jehovah. Eine ewige Satzung sei es für ihre Geschlechter aus den Söhnen Israels.',
    },
    28: {
        1: 'Und du, laß sich nahen zu dir Aharon, deinen Bruder, und seine Söhne mit ihm aus der Mitte der Söhne Israels, daß er Mir als Priester diene, Aharon, Nadab und Abihu, Eleazar und Ithamar, Aharons Söhne.',
        2: 'Und mache Kleider der Heiligkeit deinem Bruder Aharon zur Herrlichkeit und zum Schmuck.',
        3: 'Und du rede mit allen denen, die weisen Herzens sind, die Ich mit dem Geiste der Weisheit erfüllt, daß sie Aharons Kleider machen, ihn zu heiligen, auf daß er Mir Priester sei.',
        4: 'Und dies sind die Kleider, die sie machen sollen: das Brustschildlein und das Ephod und das Oberkleid und der Leibrock, zellenförmig gewirkt, die Tiara und der Gürtel. Und sie sollen Kleider der Heiligkeit machen für Aharon, deinen Bruder und für seine Söhne, daß er Mir Priester sei.',
        5: 'Und sie sollen dazu nehmen das Gold, und den blauen und roten Purpur, und doppelt gefärbten Scharlach und den Byssus.',
        6: 'Und das Ephod sollen sie machen aus Gold, blauem und rotem Purpur, doppelt gefärbtem Scharlach und gezwirnten Byssus, ein Werk des Kunstwirkers.',
        7: 'Zwei zusammengefügte Schulterstücke soll es haben an seinen zwei Enden, daß es zusammengefügt werde.',
        8: 'Und der Gurt seines Ephods, der darauf ist, soll von demselben Werke und aus demselben sein, von Gold, blauem und rotem Purpur, doppelt gefärbtem Scharlach und gezwirntem Byssus.',
        9: 'Und nimm zwei Onychsteine und grabe die Namen der Söhne Israels darein.',
        10: 'Sechs von ihren Namen auf den einen Stein und die sechs übrigen Namen auf den zweiten Stein, nach ihren Geburten.',
        11: 'Mit dem Werke des Werkmanns in Steinen mit Siegelstecherei sollst du auf die zwei Steine die Namen der Söhne Israels eingraben. Rings in Gold gefaßt sollst du sie machen.',
        12: 'Und setze die zwei Steine auf die Schultern des Ephod, als Gedenksteine für die Söhne Israels, und Aharon trage ihre Namen vor Jehovah auf seinen beiden Schultern zum Andenken.',
        13: 'Und mache die Einfassungen von Gold.',
        14: 'Und zwei Kettchen reinen Goldes sollst du an ihren Enden machen von Flechtwerk, und lege die geflochtenen Kettchen an die Einfassungen.',
        15: 'Und mache das Brustschildlein des Gerichts ein Werk des Kunstwirkers; wie das Werk des Ephod sollst du es machen; von Gold, von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus sollst du es machen.',
        16: 'Geviert sei es, gedoppelt, eine Spanne seine Länge und eine Spanne seine Breite.',
        17: 'Und du sollst es füllen mit einer Füllung von Steinen, vier Reihen von Steinen, eine Reihe von Rubin, Topas und Karfunkel: die erste Reihe.',
        18: 'Und die zweite Reihe: Chrysopras, Saphir und Diamant.',
        19: 'Und die dritte Reihe: Lasurstein, Achat und Amethyst.',
        20: 'Und die vierte Reihe: Tharschisch, Onych und Jaspis; in Gold eingefaßt, seien sie in ihren Füllungen.',
        21: 'Und die Steine seien nach den Namen der Söhne Israels, zwölf nach ihren Namen, wie Siegel eingegraben jeder Mann mit seinem Namen für die zwölf Stämme seien sie.',
        22: 'Und an die Enden des Brustschildleins mache Kettchen, Flechtwerk von reinem Gold.',
        23: 'Und an das Brustschildlein mache zwei goldene Ringe, und tue die zwei Ringe an die zwei Enden des Brustschildleins.',
        24: 'Und tue die zwei goldenen Geflechte an die zwei Ringe an den Enden des Brustschildleins.',
        25: 'Und die zwei Enden der beiden Geflechte setze an die zwei Einfassungen, und setze sie an die Schulterstücke des Ephod auf dessen Vorderseite.',
        26: 'Und mache zwei Ringe von Gold, und setze sie an die zwei Enden des Brustschildleins an dessen Saum, gegen das Ephod zu, einwärts.',
        27: 'Und mache zwei Ringe von Gold, und setze sie an die zwei Schulterstücke des Ephod von unten an seiner Vorderseite nächst der Zusammenfügung über dem Gurt des Ephod.',
        28: 'Und sie sollen das Brustschildlein mit seinen Ringen schnüren an die Ringe des Ephod mit einer purpurblauen Schnur, so daß es über dem Gurt des Ephod sei, und das Brustschildlein sich nicht von dem Ephod verrücke.',
        29: 'Und Aharon trage die Namen der Söhne Israels im Brustschildlein des Gerichts auf seinem Herzen, wenn er hineingeht ins Heiligtum, vor Jehovah zu beständigem Andenken.',
        30: 'Und in das Brustschildlein des Gerichts sollst du die Urim und die Thummim tun und sie seien auf dem Herzen Aharons, wenn er eingeht vor Jehovah, und Aharon trage beständig auf seinem Herzen das Gericht der Söhne Israels vor Jehovah.',
        31: 'Und du sollst das Oberkleid des Ephod gänzlich von blauem Purpur machen.',
        32: 'Und es sei seine Kopföffnung in seiner Mitte. Eine Borte soll sein an seiner Öffnung rings umher, das Werk des Webers; wie die Öffnung eines Panzers sei sie ihm, daß es nicht zerreiße.',
        33: 'Und an seine Säume mache Granatäpfel von blauem und rotem Purpur, und doppelt gefärbten Scharlach an seine Säume ringsherum, und goldene Glöckchen in ihrer Mitte ringsherum.',
        34: 'Ein goldenes Glöckchen und ein Granatapfel, ein goldenes Glöckchen und ein Granatapfel an den Säumen des Oberkleides ringsum.',
        35: 'Und Aharon soll es haben, wenn er Dienst tut, daß ihre Stimme gehört werde, wenn er ins Heiligtum eingeht vor Jehovah und wenn er herauskommt, auf daß er nicht sterbe.',
        36: 'Und ein Blatt mache von reinem Gold, und grabe darein mit Siegelstich: Heiligkeit dem Jehovah!',
        37: 'Und sollst es an eine Schnur von blauem Purpur setzen, und es soll sein an der Tiara; vorn an der Tiara soll es sein.',
        38: 'Und auf Aharons Stirn soll es sein, und Aharon trage die Missetat des Heiligen, das die Söhne Israels heiligen mit allen ihren heiligen Gaben, und es soll beständig auf seiner Stirn sein, zum Wohlgefallen für sie vor Jehovah.',
        39: 'Und du sollst den Leibrock zellenförmig wirken von Byssus, und die Tiara von Byssus machen, und den Gürtel machen mit dem Werk des Buntwirkers.',
        40: 'Und für die Söhne Aharons sollst du Leibröcke machen, und sollst ihnen Gürtel machen, und Kopfbünde sollst du ihnen machen zur Herrlichkeit und zum Schmuck.',
        41: 'Und sollst sie deinem Bruder Aharon und seinen Söhnen mit ihm anziehen, und sollst sie salben, und ihre Hand füllen, und sie heiligen, auf daß sie Mir Priesterdienst tun.',
        42: 'Und mache ihnen Beinkleider von Linnen, das Fleisch ihrer Blöße zu bedecken, sie sollen sein von den Lenden bis an die Schenkel.',
        43: 'Und Aharon und seine Söhne sollen sie anhaben, wenn sie in das Versammlungszelt eingehen, oder herzutreten zu dem Altare, um im Heiligtum Dienst zu tun, auf daß sie nicht eine Missetat tragen und sterben. Dies soll eine ewige Satzung für ihn und seinen Samen nach ihm sein.',
    },
    29: {
        1: 'Und das ist das Wort, das du ihnen tun sollst, um sie zu heiligen, auf daß sie Mir Priesterdienst tun. Nimm einen Farren, den Sohn der Herde, und zwei Widder ohne Fehl;',
        2: 'Und ungesäuertes Brot und ungesäuerte Kuchen, mit Öl vermischt, und ungesäuerte Fladen, mit Öl gesalbt, vom Semmelmehl des Weizens sollst du sie machen;',
        3: 'Und lege sie in einen Korb und bringe sie dar in dem Korbe, und den Farren und die zwei Widder.',
        4: 'Und Aharon und seine Söhne lasse nahen dem Eingang des Versammlungszeltes und wasche sie mit Wasser.',
        5: 'Und nimm die Kleider und ziehe dem Aharon den Leibrock und das Oberkleid des Ephod und das Ephod und das Brustschildlein an, und binde ihm den Gurt des Ephod um.',
        6: 'Und setze ihm die Tiara auf das Haupt, und tue das Diadem der Heiligkeit auf die Tiara.',
        7: 'Und nimm das Salböl und gieße es auf sein Haupt und salbe ihn.',
        8: 'Und laß nahen seine Söhne und ziehe ihnen die Leibröcke an.',
        9: 'Und gürte sie mit dem Gürtel, Aharon und seine Söhne, und binde ihnen die Kopfbünde um, auf daß sie das Priestertum haben zur ewigen Satzung; und sollst die Hand Aharons und die Hand seiner Söhne füllen.',
        10: 'Und bringe dar den Farren vor das Versammlungszelt, und Aharon und seine Söhne sollen ihre Hände dem Farren auf das Haupt legen.',
        11: 'Und sollst den Farren vor Jehovah schlachten am Eingang des Versammlungszeltes;',
        12: 'Und sollst vom Blut des Farren nehmen und mit deinem Finger auf die Hörner des Altars tun, und das ganze Blut an den Grund des Altars ausgießen.',
        13: 'Und sollst nehmen alles Fett, das die Eingeweide bedeckt und das Netz über der Leber und die zwei Nieren und das Fett, das über ihnen ist, und es anzünden auf dem Altar.',
        14: 'Und das Fleisch des Farren, und seine Haut und seinen Mist verbrenne mit Feuer außen vor dem Lager; denn ein Sündopfer ist es.',
        15: 'Und den einen Widder nimm, und Aharon und seine Söhne sollen ihre Hände auf das Haupt des Widders legen.',
        16: 'Und du sollst den Widder schlachten, und sein Blut nehmen und auf den Altar sprengen ringsherum.',
        17: 'Und den Widder zerstücke in seine Stücke, und wasche seine Eingeweide und seine Schenkel und lege sie auf seine Stücke und auf sein Haupt.',
        18: 'Und den ganzen Widder zünde an auf dem Altar; ein Brandopfer ist es dem Jehovah, ein Geruch der Ruhe, ein Feueropfer für Jehovah ist es.',
        19: 'Und nimm den zweiten Widder, und Aharon und seine Söhne sollen ihre Hände auf das Haupt des Widders legen.',
        20: 'Und schlachte den Widder und nimm von seinem Blut und tue es auf das rechte Ohrläppchen Aharons und auf das rechte Ohrläppchen seiner Söhne und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes, und sprenge das Blut auf dem Altar ringsherum.',
        21: 'Und nimm von dem Blut, das auf dem Altar ist, und von dem Salböl, und besprenge Aharon und seine Kleider und seine Söhne und die Kleider seiner Söhne mit ihm; und er soll heilig sein und seine Kleider, und seine Söhne und die Kleider seiner Söhne mit ihm.',
        22: 'Und nimm von dem Widder das Fett und den Fettschwanz und das Fett, das die Eingeweide bedeckt, und das Lebernetz und die zwei Nieren und das Fett auf ihnen und die rechte Keule; denn es ist ein Widder der Füllungen.',
        23: 'Und einen Laib Brot und einen Kuchen von Ölbrot und einen Fladen aus dem Korb des Ungesäuerten, der da ist vor Jehovah.',
        24: 'Und lege alles auf die Hände Aharons und auf die Hände seiner Söhne, und laß es weben als eine Webe vor Jehovah.',
        25: 'Und nimm sie aus ihrer Hand und zünde sie an auf dem Altar über dem Brandopfer, zu einem Geruch der Ruhe vor Jehovah. Ein Feueropfer ist es für Jehovah.',
        26: 'Und nimm die Brust von dem Widder der Füllungen für Aharon, und webe sie als eine Webe vor Jehovah und sie sei dir zum Anteil.',
        27: 'Und heilige die Brust der Webe und die Hebekeule, die gewebt und gehoben worden von dem Widder der Füllungen, von dem für Aharon und von dem für seine Söhne.',
        28: 'Und soll sein Aharons und seiner Söhne als ewige Satzung von den Söhnen Israels; denn es ist eine Hebe; und eine Hebe soll es sein von den Söhnen Israels von ihren Friedensopfern, als ihr Hebeopfer vor Jehovah.',
        29: 'Und die Kleider der Heiligkeit, die Aharon hat, seien seinen Söhnen nach ihm, um sie darin zu salben und darin ihre Hand zu füllen.',
        30: 'Sieben Tage soll sie anziehen, wer von seinen Söhnen statt seiner Priester wird, der eingeht in das Versammlungszelt, um in dem Heiligtum Dienst zu tun.',
        31: 'Und den Widder der Füllungen sollst du nehmen und sein Fleisch kochen an heiligem Orte.',
        32: 'Und Aharon und seine Söhne sollen das Fleisch des Widders und das Brot, das in dem Korbe ist, essen am Eingang des Versammlungszeltes.',
        33: 'Und sie sollen dieselben essen, durch die sie sind versöhnt worden, zu füllen ihre Hand, um sie zu heiligen, aber ein Fremder soll nicht davon essen, denn heilig sind sie.',
        34: 'Und wenn von dem Fleisch der Füllungen und von dem Brot bis zum Morgen übrigbleibt, sollst du das Übrige im Feuer verbrennen, es soll nicht gegessen werden, denn es ist Heiliges.',
        35: 'Und mit Aharon und seinen Söhnen sollst du so tun, nach allem was Ich dir geboten habe. Sieben Tage sollst du ihre Hand füllen.',
        36: 'Und einen Farren sollst du als Sündopfer jeden Tag zubereiten zur Versöhnung, und den Altar entsündigen, indem du dich über ihm versöhnst, und sollst ihn salben, um ihn zu heiligen.',
        37: 'Sieben Tage sollst du versöhnen über den Altar und ihn heiligen, und der Altar soll das Allerheiligste sein. Jeder, der den Altar berührt, soll geheiligt sein.',
        38: 'Und dies ist, was du auf dem Altar zubereiten sollst: zwei einjährige Lämmer an jedem Tage beständig.',
        39: 'Das eine Lamm sollst du am Morgen zubereiten und das zweite Lamm sollst du zubereiten gegen Abend.',
        40: 'Und ein Zehntel Semmelmehl, mit gestoßenem Öl vermischt, ein Viertel eines Hin, und als Trankopfer den vierten Teil eines Hin Wein für das eine Lamm.',
        41: 'Und das zweite Lamm sollst du zubereiten gegen Abend, wie das Speiseopfer am Morgen, und wie sein Trankopfer sollst du es machen, zum Geruch der Ruhe, ein Feueropfer für Jehovah.',
        42: 'Ein beständiges Brandopfer für eure Geschlechter am Eingang zum Versammlungszelt vor Jehovah, wo Ich mit euch zusammenkommen werde, um zu dir daselbst zu reden.',
        43: 'Und dort werde Ich zusammenkommen mit den Söhnen Israels, und geheiligt soll es werden durch Meine Herrlichkeit;',
        44: 'Und Ich werde heiligen das Versammlungszelt und den Altar; und Aharon und seine Söhne werde Ich heiligen, daß sie Mir Priesterdienste tun.',
        45: 'Und Ich werde wohnen inmitten der Söhne Israels, und werde ihnen Gott sein.',
        46: 'Und sie sollen wissen, daß Ich Jehovah ihr Gott bin, Der sie aus Ägyptenland herausgebracht hat, auf daß Ich in ihrer Mitte wohne, Ich Jehovah, ihr Gott.',
    },
    30: {
        1: 'Und du sollst einen Räuchaltar machen für das Räucherwerk. Aus Schittimholz sollst du ihn machen.',
        2: 'Eine Elle seine Länge und eine Elle seine Breite, geviert soll er sein, und zwei Ellen seine Höhe, aus ihm seien seine Hörner.',
        3: 'Und du sollst ihn mit reinem Gold überziehen, sein Dach und seine Wände ringsum und seine Hörner, und du sollst ihm einen goldenen Kranz machen ringsumher.',
        4: 'Und zwei goldene Ringe mache ihm daran, unterhalb seines Kranzes, an seinen zwei Seitenwänden, auf seinen beiden Seiten sollst du sie machen, und sie seien Behälter für die Stangen, ihn damit zu tragen.',
        5: 'Und die Stangen mache von Schittimholz und überziehe sie mit Gold.',
        6: 'Und stelle ihn vor den Vorhang, der bei der Lade des Zeugnisses ist, vor dem Gnadenstuhl, der über dem Zeugnisse, wo Ich mit dir zusammenkomme.',
        7: 'Und auf ihm lasse Aharon Morgen nach Morgen Räucherwerk der Spezereien anzünden. Wenn er die Lampen zurichtet, soll er damit räuchern.',
        8: 'Und wenn Aharon die Lampen aufsteckt gegen Abend, soll er damit räuchern, ein beständiges Räuchwerk vor Jehovah in euren Geschlechtern.',
        9: 'Kein fremdes Räuchwerk sollt ihr darauf aufgehen lassen, noch Brandopfer und Speiseopfer. Und kein Trankopfer sollt ihr daraufgießen.',
        10: 'Und Aharon versöhne einmal im Jahr auf den Hörnern desselben mit dem Blut des Sündopfers der Versöhnungen. Einmal im Jahr soll er darauf versöhnen für eure Geschlechter. Das Allerheiligste ist er für Jehovah.',
        11: 'Und Jehovah redete zu Mose und sprach:',
        12: 'Wenn du die Häupter erhebst der Söhne Israels nach ihrer Musterung, soll jeder Mann dem Jehovah eine Sühne für seine Seele geben, wenn man sie mustert; auf daß in der Musterung keine Plage wider sie komme.',
        13: 'Jeder, der zu den Gemusterten übergeht, soll einen halben Schekel geben, nach dem Schekel des Heiligtums, zwanzig Gerah auf den Schekel. Der halbe Schekel soll ein Hebeopfer für Jehovah sein.',
        14: 'Jeder, der zu den Gemusterten übergeht von dem Sohne von zwanzig Jahren und darüber, soll dem Jehovah ein Hebeopfer geben.',
        15: 'Der Reiche mehre nicht und der Arme mache es nicht weniger als die Hälfte eines Schekels, um eine Hebe zu geben für Jehovah, für eure Seelen zu sühnen.',
        16: 'Und nimm das Silber der Versöhnungen von den Söhnen Israels, und gib es zum Dienste des Versammlungszeltes, und es sei den Söhnen Israels zum Gedächtnis vor Jehovah, daß ihr für eure Seelen sühnetet.',
        17: 'Und Jehovah redete zu Mose und sprach:',
        18: 'Und du sollst ein Becken von Erz und sein Gestell von Erz machen zum Waschen, und es zwischen das Versammlungszelt und den Altar stellen und Wasser darein tun.',
        19: 'Und Aharon und seine Söhne sollen daraus ihre Hände und Füße waschen.',
        20: 'Wenn sie in das Versammlungszelt hineingehen, sollen sie sich mit Wasser waschen, auf daß sie nicht sterben; oder wenn sie zu dem Altare herzutreten, um den Dienst zu tun, dem Jehovah ein Feueropfer anzuzünden.',
        21: 'Und sie sollen ihre Hände und ihre Füße waschen, auf daß sie nicht sterben; und es soll dies ihnen eine ewige Satzung sein, ihm und seinem Samen für ihre Geschlechter.',
        22: 'Und Jehovah redete zu Mose und sprach:',
        23: 'Und du, nimm dir die hauptsächlichen Gewürze, der edelsten Myrrhe fünfhundert, und würzigen Zimt, die Hälfte davon, zweihundertfünfzig, und würzigen Kalmus zweihundertfünfzig,',
        24: 'Und Kassia fünfhundert, nach dem Schekel des Heiligtums, und Olivenöl ein Hin.',
        25: 'Und mache es zu Salböl der Heiligkeit, die Salbe der Salbe, ein Werk des Salbenmischers, das Salböl der Heiligkeit soll es sein.',
        26: 'Und salbe damit das Versammlungszelt und die Lade des Zeugnisses,',
        27: 'Und den Tisch und alle seine Geräte, und den Leuchter und seine Geräte, und den Rauchaltar;',
        28: 'Und den Brandopferaltar und alle seine Geräte, und das Becken und sein Gestell;',
        29: 'Und sollst sie heiligen, und sie sollen das Allerheiligste sein; ein jeder, der sie anrührt, soll geheiligt sein.',
        30: 'Und Aharon und seine Söhne sollst du salben und sie heiligen, auf daß sie Mir Priesterdienst tun.',
        31: 'Und zu den Söhnen Israels sollst du reden und sprechen: Das Salböl der Heiligkeit ist dies für Mich in euren Geschlechtern.',
        32: 'Auf das Fleisch eines Menschen soll es nicht gegossen werden; auch sollt ihr nach seinem Maß kein solches machen. Heilig ist es, heilig sei es euch.',
        33: 'Der Mann, der eines mischt gleich ihm, und davon einem Fremden gibt, der soll von seinem Volke ausgerottet werden.',
        34: 'Und Jehovah sprach zu Mose: Nimm dir Spezereien, Stakte, Räucherklaue und Galbanum, Spezereien, riechenden und lauteren Weihrauch. Teil zu Teil soll es sein.',
        35: 'Und mache daraus ein Räuchwerk, eine Mischung, ein Werk des Salbenmischers; gesalzen, rein, heilig.',
        36: 'Und zermalme davon, zerstoße und tue davon vor das Zeugnis in das Versammlungszelt, wo Ich mit dir zusammenkomme, das Allerheiligste sei es euch.',
        37: 'Und solch Räucherwerk, das du machst, nach demselben Maß sollt ihr es euch nicht machen, Heiliges sei es dir für Jehovah.',
        38: 'Der Mann, der ein solches macht, um den Geruch davon zu machen, der soll von seinem Volke ausgerottet werden.',
    },
    31: {
        1: 'Und Jehovah redete zu Mose und sprach:',
        2: 'Siehe, Ich habe mit Namen gerufen Bezaleel, den Sohn Uris, des Sohnes Churs, vom Stamme Judah;',
        3: 'Und habe ihn erfüllt mit dem Geiste Gottes, mit Weisheit und mit Einsicht und mit Erkenntnis und allerlei Werk;',
        4: 'Auszudenken Gedanken, sie zu machen in Gold und in Silber und in Erz;',
        5: 'Und im Steinschneiden zum Ausfüllen, und im Holzschneiden, um allerlei Werk zu machen.',
        6: 'Und siehe, Ich habe ihm gegeben Oholiab, den Sohn Achisamachs, vom Stamme Dan, und jedem, der weise ist von Herzen, in das Herz gegeben Weisheit, daß sie alles machen, was Ich dir geboten habe.',
        7: 'Das Versammlungszelt und die Lade für das Zeugnis und den Gnadenstuhl darauf, und alle Geräte des Zeltes,',
        8: 'Und den Tisch und seine Geräte, und den reinen Leuchter und alle seine Geräte, und den Rauchaltar;',
        9: 'Und den Brandopferaltar und alle seine Geräte, und das Becken und sein Gestell.',
        10: 'Und die Kleider des Dienstes, und die heiligen Kleider für Aharon, den Priester und die Kleider seiner Söhne, um Priesterdienst zu tun;',
        11: 'Und das Salböl und das Räuchwerk der Spezereien für das Heiligtum; nach allem, was Ich dir geboten habe, sollen sie es machen.',
        12: 'Und Jehovah redete zu Mose und sprach:',
        13: 'Und du, rede zu den Söhnen Israels und sprich: Haltet ja Meine Sabbathe; denn dies ist ein Zeichen zwischen Mir und zwischen euch in euren Geschlechtern, auf daß ihr wisset, daß Ich Jehovah es bin, Der euch heiligt.',
        14: 'Und haltet den Sabbath; denn heilig ist er euch. Wer ihn entweiht, soll des Todes sterben; denn jeder, der an ihm eine Arbeit tut, dessen Seele soll aus der Mitte seines Volkes ausgerottet werden.',
        15: 'Sechs Tage soll man Arbeit tun, am siebenten Tag aber ist der Sabbath des Sabbaths, dem Jehovah heilig. Wer eine Arbeit tut am Sabbathtage, soll des Todes sterben!',
        16: 'Und die Söhne Israels sollen den Sabbath halten, zu machen den Sabbath in ihren Geschlechtern zum Bunde der Ewigkeit.',
        17: 'Zwischen Mir und den Söhnen Israels sei er ein Zeichen ewiglich; denn in sechs Tagen machte Jehovah die Himmel und die Erde, am siebenten Tage aber hat Er gefeiert und Sich erholt.',
        18: 'Und Er gab dem Mose, als Er vollendet hatte mit ihm zu reden, auf dem Berge Sinai die zwei Tafeln des Zeugnisses, Tafeln von Stein, geschrieben mit dem Finger Gottes.',
    },
    32: {
        1: 'Und das Volk sah, daß Mose verzog, vom Berge herabzukommen; und das Volk kam zusammen zu Aharon und sprachen zu ihm: Mache dich auf! mach uns Götter, die vor uns gehen; denn dieser Mose, der Mann, der uns aus Ägyptenland heraufgebracht: wir wissen nicht, was mit ihm geschehen ist.',
        2: 'Und Aharon sprach zu ihnen: Reißet ab die goldenen Reife in den Ohren eurer Weiber, eurer Söhne und eurer Töchter und bringt sie mir.',
        3: 'Und das ganze Volk riß sich die goldenen Reife, die in ihren Ohren waren, ab, und brachten sie zu Aharon.',
        4: 'Und er nahm sie von ihrer Hand und bildete es mit dem Meißel und machte es zu einem gegossenen Kalb. Und sie sprachen: Dies sind deine Götter, Israel, die dich aus Ägyptenland heraufgebracht.',
        5: 'Und Aharon sah es, und baute einen Altar vor ihm, und Aharon rief aus und sprach: Morgen ist ein Fest für Jehovah!',
        6: 'Und früh am morgenden Tag standen sie auf und opferten Brandopfer auf und brachten Friedensopfer herbei, und das Volk setzte sich zu essen und zu trinken, und standen auf zum Spiel.',
        7: 'Und Jehovah redete zu Mose: Geh, steig hinab; denn verderblich handelt dein Volk, das du aus Ägyptenland heraufgebracht.',
        8: 'Eilends sind sie von dem Wege gewichen, den Ich ihnen geboten hatte. Sie haben sich ein gegossen Kalb gemacht und haben es angebetet und ihm geopfert, und gesagt: Dies sind deine Götter, Israel, die dich aus Ägyptenland heraufgebracht.',
        9: 'Und Jehovah sprach zu Mose: Ich habe dieses Volk gesehen, und siehe, es ist ein hartnäckiges Volk.',
        10: 'Und nun laß Mich bleiben, daß Mein Zorn gegen sie entbrenne, und Ich sie verzehre. Dich aber will Ich zu einer großen Völkerschaft machen.',
        11: 'Und Mose flehte vor dem Angesicht Jehovahs, seines Gottes, und sprach: Warum soll Dein Zorn entbrennen, Jehovah, wider Dein Volk, das Du mit großer Kraft und starker Hand aus Ägyptenland heraufgebracht?',
        12: 'Warum sollen die Ägypter sprechen und sagen: Zum Übel hat Er sie herausgebracht, um sie auf den Bergen zu erwürgen und vom Boden sie wegzutilgen? Kehre zurück vom Entbrennen Deines Zorns, und laß Dich des Bösen über Dein Volk gereuen!',
        13: 'Gedenke Abrahams, Isaaks und Israels, Deiner Knechte, denen Du geschworen bei Dir selbst, und zu denen Du geredet hast: Euren Samen will Ich mehren wie die Sterne des Himmels, und all dieses Land, davon Ich sagte, will Ich eurem Samen geben, und sie sollen es ewiglich erben.',
        14: 'Und Jehovah ließ Sich gereuen des Bösen, wovon Er geredet hatte, Seinem Volke anzutun.',
        15: 'Und Mose wandte sich und ging vom Berg hinab, und die zwei Tafeln des Zeugnisses waren in seiner Hand, Tafeln von beiden Seiten her beschrieben. Von dieser und von der anderen Seite waren sie geschrieben.',
        16: 'Und die Tafeln waren von Gott gemacht. Und das Geschriebene war von Gott geschrieben und auf die Tafeln eingegraben.',
        17: 'Und Jehoschuah hörte die Stimme des Volkes in seinem Jubeln und sprach zu Mose: Die Stimme des Kriegs ist im Lager.',
        18: 'Und er sprach: Das ist nicht Stimme des Geschreis des Obsiegens, noch die Stimme des Geschreis des Unterliegens; solches ist wie die Stimme des Elends, was ich höre.',
        19: 'Und es geschah, als er dem Lager nahte und das Kalb und die Reigentänze sah, da entbrannte Moses Zorn, und er warf die Tafeln aus seinen Händen und zerbrach sie unten am Berg.',
        20: 'Und er nahm das Kalb, das sie gemacht hatten und verbrannte es im Feuer, und zermahlte es, bis daß es fein war, und sprengte es auf das Wasser und ließ die Söhne Israels es trinken.',
        21: 'Und Mose sprach zu Aharon: Was hat dir dieses Volk getan, daß du eine so große Sünde über dasselbe gebracht hast?',
        22: 'Und Aharon sprach: Es entbrenne nicht der Zorn meines Herrn; du weißt, daß dieses Volk im Bösen ist.',
        23: 'Und sie sprachen zu mir: Mache uns Götter, daß sie vor uns hergehen; denn der Mose da, der Mann, der uns von Ägyptenland heraufgebracht: wir wissen nicht, was ihm geschehen ist.',
        24: 'Und ich sprach zu ihnen: Wer Gold hat, der reiße es sich ab. Und sie gaben es mir, und ich warf es ins Feuer, und dieses Kalb kam heraus.',
        25: 'Und Mose sah, daß das Volk losgelassen war, da es Aharon losgelassen, so daß sie zum Gespötte würden denen, die wider sie aufständen;',
        26: 'Und Mose stand am Tor des Lagers und sprach: Her zu mir, wer Jehovahs ist! Und es versammelten sich alle Söhne Levis zu ihm.',
        27: 'Und er sprach zu ihnen: So spricht Jehovah, der Gott Israels: Jeder von euch lege sein Schwert an seine Hüfte und gehe hin durch das Lager und kehre wieder von Tor zu Tor und erwürge jeder Mann seinen Bruder, und jeder Mann seinen Genossen, und jeder Mann seinen Nächsten.',
        28: 'Und die Söhne Levis taten nach dem Worte des Mose, und es fielen von dem Volk an selbigem Tag bei dreitausend Mann.',
        29: 'Und Mose sprach: Füllet heute eure Hand dem Jehovah, weil jeder wider seinen Sohn und wider seinen Bruder war, auf daß heute ein Segen über euch gegeben werde.',
        30: 'Und es geschah am morgenden Tag, daß Mose zu dem Volke sprach: Ihr habt eine große Sünde gesündigt, und nun will ich zu Jehovah hinaufgehen. Vielleicht daß ich eure Sünde versöhne.',
        31: 'Und Mose kehrte zu Jehovah zurück und sprach: Ach, dieses Volk hat eine große Sünde gesündigt, und sich Götter aus Gold gemacht.',
        32: 'Und nun, möchtest Du doch ihnen ihre Sünde vergeben, wo nicht, so wische mich doch aus Deinem Buche, das Du geschrieben hast.',
        33: 'Und Jehovah sprach zu Mose: Wer gegen Mich gesündigt hat, den werde Ich von Meinem Buche wischen.',
        34: 'Und nun geh, führe das Volk, wohin Ich dir gesagt habe, siehe, Mein Engel wird vor dir hergehen; aber am Tage Meiner Heimsuchung werde Ich ihre Sünde an ihnen heimsuchen.',
        35: 'Und Jehovah schlug das Volk darüber, daß sie das Kalb machten, das Aharon gemacht hatte.',
    },
    33: {
        1: 'Und Jehovah redete zu Mose: Geh, zieh hinauf von hinnen, du und das Volk, das du aus Ägyptenland heraufgebracht hast, in das Land, von dem Ich dem Abraham, dem Isaak und dem Jakob geschworen habe und gesagt: Deinem Samen will Ich es geben.',
        2: 'Und Ich will einen Engel vor dir hersenden, und vertreiben den Kanaaniter, den Amoriter und den Chethiter und den Pherisiter, den Chiviter und den Jebusiter;',
        3: 'In ein Land, da Milch und Honig fließt; denn Ich werde nicht in deiner Mitte hinaufziehen, weil du ein hartnäckiges Volk bist, Ich möchte dich sonst verzehren auf dem Wege.',
        4: 'Und das Volk hörte das böse Wort, und sie trauerten, und keiner legte seinen Schmuck an.',
        5: 'Und Jehovah sprach zu Mose: Sprich zu den Söhnen Israels: Ein hartnäckiges Volk seid ihr. In einem Augeblick, so Ich in deiner Mitte hinaufzöge, würde Ich dich verzehren. Und nun nimm deinen Schmuck von dir herunter, daß Ich wisse, was Ich mit dir tue.',
        6: 'Und die Söhne Israels rissen sich ihren Schmuck vor dem Berge Horeb ab.',
        7: 'Und Mose nahm das Zelt und schlug es außerhalb des Lagers für sich auf, fern von dem Lager, und nannte es Versammlungszelt; und es geschah, daß jeder, der Jehovah fragen wollte, zum Versammlungszelt außerhalb des Lagers hinausging.',
        8: 'Und es geschah, wenn Mose hinausging zum Zelt, stand alles Volk auf, und jeder Mann stellte sich an den Eingang seines Zeltes; und sie blickten Mose nach, bis er in das Zelt eingegangen war.',
        9: 'Und es geschah, wenn Mose in das Zelt einging, kam die Wolkensäule herab und stand am Eingang des Zeltes und redete mit Mose.',
        10: 'Und alles Volk sah die Wolkensäule am Eingang des Zeltes stehen, und das ganze Volk stand auf und verbeugte sich, jeder Mann am Eingang seines Zeltes.',
        11: 'Und Jehovah redete zu Mose von Angesicht zu Angesicht, wie ein Mann zu seinem Genossen redet; und er kehrte in das Lager zurück; und Jehoschuah, sein Diener, Nuns Sohn, der Jüngling, wich nicht aus des Zeltes Mitte.',
        12: 'Und Mose sprach zu Jehovah: Siehe, Du sprichst zu mir: Bringe dieses Volk hinauf, und hast mich nicht wissen lassen, wen Du mit mir senden willst, und hast doch gesagt: Ich kenne dich beim Namen, und du hast auch Gnade in Meinen Augen gefunden.',
        13: 'Und nun, wenn ich doch Gnade in Deinen Augen gefunden habe, so laß mich doch wissen Deinen Weg, auf daß ich Dich kenne, weil ich Gnade gefunden in Deinen Augen, und siehe, daß Dein Volk ist diese Völkerschaft.',
        14: 'Und Er sprach: Mein Angesicht soll gehen, und Ich werde dich zur Ruhe bringen.',
        15: 'Und er sprach zu Ihm: Wenn Dein Angesicht nicht geht, so bringe uns nicht von dannen hinauf.',
        16: 'Und woran soll dann erkannt werden, daß ich in Deinen Augen Gnade gefunden, ich und Dein Volk? Wenn nicht daran, daß Du mit uns gehst, und daß wir, ich und Dein Volk, ausgezeichnet werden vor allem Volke, das auf dem Boden ist?',
        17: 'Und Jehovah sprach zu Mose: Auch dieses Wort, das du geredet, will Ich tun; denn du hast Gnade in Meinen Augen gefunden, und Ich kenne dich beim Namen.',
        18: 'Und er sprach: Laß mich doch Deine Herrlichkeit sehen.',
        19: 'Und Er sprach: Ich will alle Meine Güte vor deinem Angesicht vorübergehen lassen, und den Namen Jehovahs anrufen vor dir. Und Ich bin gnädig, wem Ich gnädig bin, und erbarme Mich, wessen Ich Mich erbarme.',
        20: 'Und Er sprach: Mein Angesicht vermagst du nicht zu sehen; denn nicht sieht Mich ein Mensch und lebt.',
        21: 'Und Jehovah sprach: Siehe, es ist ein Ort bei Mir, und du sollst auf den Fels dich stellen.',
        22: 'Und es wird geschehen, wenn Meine Herrlichkeit vorüberzieht, so will Ich dich in die Kluft des Felsens stellen und Meine Hand über dich decken, bis Ich vorübergezogen bin.',
        23: 'Und Ich will Meine Hand wegnehmen, daß du Mich von hinten sehest, aber Mein Angesicht soll man nicht sehen.',
    },
    34: {
        1: 'Und Jehovah sprach zu Mose: Haue dir zwei steinerne Tafeln zu, wie die ersten, und Ich will auf die Tafeln die Worte schreiben, die auf den ersten Tafeln waren, die du zerbrochen hast.',
        2: 'Und sei bereit für den Morgen, und steig am Morgen auf den Berg Sinai und stelle dich Mir daselbst auf des Berges Spitze.',
        3: 'Und niemand steige mit dir hinauf, und soll sich auch niemand auf dem Berge sehen lassen. Auch Kleinvieh und Rind soll nicht vor diesem Berg weiden.',
        4: 'Und er hieb zwei steinerne Tafeln zu, gleich den ersten, und Mose machte sich früh am Morgen auf und stieg auf den Berg Sinai, wie Jehovah ihm geboten hatte, und nahm die zwei steinernen Tafeln in seine Hand.',
        5: 'Und Jehovah kam in der Wolke herab und stellte Sich zu ihm daselbst und rief Jehovahs Namen an.',
        6: 'Und Jehovah zog vorüber vor seinem Angesicht und rief: Jehovah, Jehovah, Gott, erbarmungsvoll und gnädig, langmütig und groß an Barmherzigkeit und Wahrheit.',
        7: 'Bewahrend Barmherzigkeit Tausenden, tragend Missetat und Übertretung und Sünde, aber nicht ungestraft lassend, heimsuchend die Missetat der Väter an den Söhnen und an der Söhne Söhnen bis ins dritte und vierte Glied.',
        8: 'Und Mose eilte und verneigte sich zur Erde und betete an.',
        9: 'Und sprach: Wenn ich doch Gnade fände in Deinen Augen, o Herr, daß der Herr doch in unserer Mitte zöge. Denn es ist ein hartnäckiges Volk; aber vergib unsrer Missetat und unsrer Sünde und mach uns zum Erbe.',
        10: 'Und Er sprach: Siehe, Ich schließe einen Bund; vor all deinem Volke will Ich Wunder tun, dergleichen nicht geschaffen sind auf der ganzen Erde und unter allen Völkerschaften; und sehen wird das ganze Volk, in dessen Mitte du bist, das Tun Jehovahs; denn furchtbar wird sein, was Ich mit dir tun werde.',
        11: 'Halte dir, was heut Ich dir gebiete. Siehe, Ich vertreibe vor dir den Amoriter und den Kanaaniter, und den Chethiter und den Pherisiter und den Chiviter und den Jebusiter.',
        12: 'Hüte dich, daß du nicht einen Bund mit dem Einwohner des Landes schließest, in das du kommst; auf daß er nicht zum Fallstrick in deiner Mitte werde.',
        13: 'Darum sollt ihr ihre Altäre einreißen und ihre Bildsäulen zerbrechen und ihre Ascheren ausrotten.',
        14: 'Denn du sollst keinen anderen Gott anbeten; denn Jehovah, Eiferer ist Sein Name, ein eifriger Gott ist Er.',
        15: 'Daß du keinen Bund schließest mit dem Einwohner des Landes, und sie nachbuhlen ihren Göttern und opfern ihren Göttern, und er dann dich rufe und du essest von ihrem Opfer,',
        16: 'Und nehmest von ihren Töchtern für deine Söhne, und dann ihre Töchter ihren Göttern nachbuhlen, und machen deine Söhne ihren Göttern nachbuhlen.',
        17: 'Mache dir keine gegossenen Götter.',
        18: 'Das Fest des Ungesäuerten sollst du halten, sieben Tage Ungesäuertes essen, wie Ich dir geboten habe, zur bestimmten Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten ausgegangen.',
        19: 'Alles, was die Mutter bricht, ist Mein, und von all deiner Viehherde sollst du das Männliche geben, alles Erstgeborene von Ochs und von Kleinvieh.',
        20: 'Und das Erstgeborene des Esels sollst du mit einem Lamme einlösen; und wenn du es nicht einlösest, so brich ihm das Genick. Jeden Erstgeborenen deiner Söhne sollst du lösen; und vor Meinem Angesicht soll man nicht leer erscheinen.',
        21: 'Sechs Tage sollst du arbeiten, aber am siebenten Tage feiern; mit dem Pflügen und dem Ernten sollst du feiern.',
        22: 'Und das Fest der Woche sollst du bei dir halten mit den Erstlingen der Weizenernte, und das Fest der Einsammlung im Verlaufe des Jahres.',
        23: 'Dreimal des Jahres erscheine all dein Männliches vor dem Angesicht des Herrn Jehovah, des Gottes Israels.',
        24: 'Denn Ich will die Völkerschaften vor deinem Angesicht austreiben und deine Grenze erweitern, und niemand soll dein Land begehren, wenn du hinaufgehst, dreimal im Jahre das Angesicht Jehovahs, deines Gottes, zu sehen.',
        25: 'Du sollst nicht über Gesäuertem das Blut Meines Opfers schlachten, noch soll über Nacht bis zum Morgen bleiben das Opfer des Passahfestes.',
        26: 'Das Erste der Erstlinge deines Bodens sollst du in das Haus Jehovahs deines Gottes bringen. Du sollst nicht kochen das Böcklein in der Milch seiner Mutter.',
        27: 'Und Jehovah sprach zu Mose: Schreibe dir diese Worte auf; denn nach dem Ausspruch dieser Worte schließe Ich einen Bund mit dir und mit Israel.',
        28: 'Und er war dort mit Jehovah vierzig Tage und vierzig Nächte, er aß kein Brot und trank kein Wasser; und Er schrieb die Worte des Bundes, die Zehn Worte, auf die Tafeln.',
        29: 'Und es geschah, als Mose vom Berge Sinai herabkam, und die zwei Tafeln des Zeugnisses in Moses Hand waren, bei seinem Herabkommen vom Berg, daß Mose nicht wußte, daß die Haut seines Angesichts davon strahlte, daß er mit Ihm geredet hatte.',
        30: 'Und Aharon und alle Söhne Israels sahen Mose, und siehe, die Haut seines Angesichts strahlte, und sie fürchteten sich, zu ihm herzutreten.',
        31: 'Und Mose rief ihnen zu, und Aharon und alle die Fürsten in der Gemeinde kehrten zurück, und Mose redete zu ihnen;',
        32: 'Und nachher traten alle Söhne Israels herzu und er gebot ihnen alles, was Jehovah mit ihm auf dem Berge Sinai geredet hatte.',
        33: 'Und Mose vollendete mit ihnen zu reden, und er tat eine Hülle über sein Angesicht.',
        34: 'Und wenn Mose hineinging vor Jehovah, mit Ihm zu reden, nahm er die Hülle ab, bis er herausging; und er ging heraus und redete zu den Söhnen Israels, was ihm geboten war.',
        35: 'Und die Söhne Israels sahen das Angesicht Moses, daß die Haut von Moses Ange- sicht strahlte, und Mose tat die Hülle zurück über sein Angesicht, bis er hineinging, mit Ihm zu reden.',
    },
    35: {
        1: 'Und Mose versammelte die ganze Gemeinde der Söhne Israels und sprach zu ihnen: Das sind die Worte, die Jehovah geboten hat, sie zu tun.',
        2: 'Sechs Tage soll die Arbeit getan werden, und am siebenten Tag sei euch ein heiliger Sabbath des Feierns für Jehovah; jeder, der an ihm Arbeit tut, soll sterben:',
        3: 'Ihr sollt kein Feuer in allen euren Wohnungen brennen lassen am Sabbathtag.',
        4: 'Und Mose sprach zur ganzen Gemeinde der Söhne Israels und sagte: Dies ist das Wort, das Jehovah geboten hat und gesagt:',
        5: 'Nehmet von euch eine Hebe für Jehovah, ein jeder, der freiwilligen Herzens ist, bringe als Hebe dem Jehovah: Gold und Silber und Erz;',
        6: 'Und blauen und roten Purpur, und Scharlach, doppelt gefärbt, und Byssus und Ziegenhaar;',
        7: 'Und rote Widderfelle und Dachsfelle und Schittimholz;',
        8: 'Und Öl für den Leuchter, und Gewürze zum Salböl und zum Räuchwerk der Spezereien.',
        9: 'Und Onychsteine und Füllungssteine für das Ephod und für das Brustschildlein.',
        10: 'Und jeder unter euch, der weisen Herzens ist, komme und mache alles, was Jehovah geboten hat:',
        11: 'Die Wohnung, ihr Zelt und ihre Decke; ihre Haken und ihre Bretter, ihre Riegel, ihre Säulen und ihre Untersätze;',
        12: 'Die Lade und ihre Stangen, den Gnadenstuhl und den Vorhang der Decke;',
        13: 'Den Tisch und seine Stangen und all seine Geräte und das Schaubrot;',
        14: 'Und den Leuchter der Beleuchtung und seine Geräte und seine Lampen und das Öl zur Beleuchtung.',
        15: 'Und den Räuchaltar und seine Stangen und das Salböl und das Räuchwerk der Spezereien; und die Decke am Eingang für den Eingang zur Wohnung;',
        16: 'Den Brandopferaltar und sein ehernes Gitter, seine Stangen und all seine Geräte; das Becken und sein Gestell;',
        17: 'Die Behänge des Vorhofs, seine Säulen und seine Untersätze, und die Decke zum Tor des Vorhofs;',
        18: 'Die Pflöcke der Wohnung und die Pflöcke des Vorhofs und ihre Seile;',
        19: 'Die Dienstkleider zum Dienst tun im Heiligtum; die heiligen Kleider für Aharon den Priester und die Kleider seiner Söhne, den Priesterdienst zu tun.',
        20: 'Und sie gingen hinaus, die ganze Gemeinde der Söhne Israels von Mose.',
        21: 'Und sie kamen, jeder Mann, den sein Herz erhob, und jeder, der seinen Geist freiwillig machte; sie brachten die Hebe Jehovahs zur Arbeit des Versammlungszeltes und für all seinen Dienst und für die heiligen Kleider.',
        22: 'Und es kamen die Männer samt den Weibern, alle mit freiwilligem Herzen, und brachten Haften und Ohrringe und Ringe und Gürtel, allerlei Gerät von Gold, und wie jeder Mann ein Webeopfer von Gold Jehovah bringen wollte.',
        23: 'Und jeder Mann, bei dem sich blauer und roter Purpur und doppelt gefärbter Scharlach und Byssus und Ziegenhaar fand, und rote Widderfelle und Dachsfelle, brachte sie.',
        24: 'Jeder, der eine Hebe an Silber und Erz hob, brachte es als Hebeopfer Jehovahs, und jeder, bei dem sich Schittimholz zu irgendwelchem Dienstwerk fand, brachte es.',
        25: 'Und alle Weiber, die weisen Herzens waren, spannen mit ihren Händen und brachten das Gesponnene, blauen und roten Purpur, doppelt gefärbten Scharlach und Byssus.',
        26: 'Und alle Weiber, die ihr Herz mit Weisheit erhob, spannen Ziegenhaar.',
        27: 'Und die Fürsten brachten Onychsteine und Füllungssteine für das Ephod und das Brustschildlein.',
        28: 'Und Gewürz und Öl für Beleuchtung und für das Öl zum Salben, und für das Räuchwerk der Spezereien;',
        29: 'Alles, Mann und Weib, die ihr Herz freiwillig machte, brachten für jegliches Werk, das Jehovah zu machen geboten hatte, durch Moses Hand; das brachten die Söhne Israels dem Jehovah als freiwillige Gabe.',
        30: 'Und Mose sprach zu den Söhnen Israels: Sehet, Jehovah hat mit Namen gerufen Bezaleel, den Sohn Uris, des Sohnes Churs, vom Stamme Judah;',
        31: 'Und ihn erfüllt mit dem Geiste Gottes, mit Weisheit, mit Einsicht und mit Kenntnis und in aller Arbeit.',
        32: 'Und Gedanken auszudenken, um es in Gold und in Silber und in Erz zu machen.',
        33: 'Und im Steinschneiden zum Einfüllen, und im Holzschneiden, um zu machen alle Arbeit, die er ausgedacht.',
        34: 'Und zu unterweisen gab Er ihm ins Herz, ihm und Oholiab, dem Sohne Achisamachs, vom Stamme Dan.',
        35: 'Er hat sie erfüllt mit Weisheit des Herzens, zu machen alle Arbeit des Werkmannes und des Ausdenkers und des Buntwirkers in Purpurblau und Purpurrot, in doppelt gefärbtem Scharlach und in Byssus, und des Webers, daß sie allerlei Arbeit tun und Gedanken ausdenken mögen.',
    },
    36: {
        1: 'Und es tat Bezaleel und Oholiab und alle Männer weisen Herzens, denen Jehovah Weisheit und Einsicht gegeben, um zu wissen, wie sie jegliche Arbeit zum Dienste des Heiligtums nach allem, was Jehovah geboten hatte, machen sollten.',
        2: 'Und Mose rief Bezaleel und Oholiab und jeglichen Mann weisen Herzens, denen Jehovah Weisheit ins Herz gegeben hatte, jeden, den sein Herz erhob, sich zu nahen zur Arbeit, um sie zu tun.',
        3: 'Und sie holten sich von Mose alle Hebe, welche die Söhne Israels brachten, zu machen die Arbeit zum Dienste des Heiligtums; und sie brachten ihm von Morgen zu Morgen noch freiwillige Gaben.',
        4: 'Und es kamen alle Weisen, die alle Arbeit des Heiligtums machten, Mann für Mann von seinem Werk, das er machte.',
        5: 'Und sprachen zu Mose und sagten: Das Volk bringt mehr denn genug zum Dienst der Arbeit, die Jehovah geboten hat zu machen.',
        6: 'Und Mose gebot, daß man eine Stimme im Lager hinziehen lasse und sage: Mann und Weib soll keine Arbeit weitermachen für die Hebe des Heiligtums. Und das Volk wurde abgehalten vom Bringen.',
        7: 'Denn der Arbeit war genug für jegliche Arbeit, die getan werden sollte, und war übrig.',
        8: 'Und alle, die weisen Herzens waren, machten mit denen, welche die Arbeit taten, die Wohnung aus zehn Teppichen von gezwirntem Byssus und blauem und rotem Purpur und Scharlach, doppelt gefärbt, mit Cheruben, ein Werk des Künstlers machte man sie.',
        9: 'Die Länge des einen Teppichs war achtundzwanzig Ellen und vier Ellen die Breite eines Teppichs; alle Teppiche hatten ein Maß.',
        10: 'Und er fügte fünf Teppiche zusammen, je einen an den andern, und fügte fünf Teppiche zusammen, eins an das andere.',
        11: 'Und machte Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende der Zusammenfügung. So tat er am Saume des äußersten Teppichs bei der zweiten Zusammenfügung.',
        12: 'Fünfzig Schleifen machte er an den einen Teppich und fünfzig Schleifen machte er an das Ende des Teppichs an der zweiten Zusammenfügung, so daß die Schleifen einander gegenüber waren;',
        13: 'Und er machte fünfzig goldene Haken, und durch die Haken fügte er die Teppiche zusammen, einen an den anderen, so daß die Wohnung eins wurde.',
        14: 'Und er machte Teppiche von Ziegenhaar für das Zelt über die Wohnung, elf Teppiche machte er sie.',
        15: 'Die Länge eines Teppichs war dreißig Ellen, und vier Ellen die Breite des einen Teppichs. Die elf Teppiche hatten ein Maß.',
        16: 'Und er fügte fünf Teppiche zusammen besonders, und sechs Teppiche besonders;',
        17: 'Und machte fünfzig Schleifen an den Saum des äußersten Teppichs an die Zusammenfügung, und fünfzig Schleifen machte er an den Saum des Teppichs an der zweiten Zusammenfügung.',
        18: 'Und er machte fünfzig Haken von Erz, um das Zelt zusammenzufügen, daß es eins wurde.',
        19: 'Und machte eine Decke für das Zelt von roten Widderfellen, und eine Decke von Dachsfellen darüber.',
        20: 'Und er machte Bretter von Schittimholz für die Wohnung; aufrecht zu stehen.',
        21: 'Zehn Ellen die Länge des Brettes, und eine Elle und eine halbe Elle die Breite eines Brettes.',
        22: 'Zwei Zapfen für ein Brett fügend das eine an das andere machte er an allen Brettern der Wohnung.',
        23: 'Und er machte die Bretter für die Wohnung, zwanzig Bretter für die Ecke gegen Mittag südwärts.',
        24: 'Und vierzig silberne Untersätze machte er unter die zwanzig Bretter, zwei Untersätze unter ein Brett für seine zwei Zapfen, und zwei Untersätze unter das andere Brett für seine zwei Zapfen.',
        25: 'Und für die zweite Seitenwand der Wohnung in die Ecke gegen Mitternacht machte er zwanzig Bretter.',
        26: 'Und ihre vierzig Untersätze von Silber, zwei Untersätze unter das eine Brett und zwei Untersätze unter das eine Brett.',
        27: 'Und für die Hinterseite der Wohnung gegen das Meer hin machte er sechs Bretter;',
        28: 'Und zwei Bretter machte er für die Eckstücke der Wohnung an der Hinterseite.',
        29: 'Und sie waren zweifach von unten an und zugleich ganz bis an die Spitze, an dem einen Ring. So tat er es mit beiden, an den beiden Eckstücken.',
        30: 'Und acht Bretter waren es, und ihre Untersätze von Silber, sechzehn Untersätze, zwei Untersätze und zwei Untersätze unter einem Brett.',
        31: 'Und er machte Riegel von Schittimholz, fünf für die Bretter einer Seitenwand der Wohnung;',
        32: 'Und fünf Riegel für die Bretter der zweiten Seitenwand der Wohnung, und fünf Riegel für die Bretter der Wohnung auf der Hinterseite gegen das Meer.',
        33: 'Und den mittleren Riegel machte er so, daß er von Ende zu Ende mitten hinlief an den Brettern.',
        34: 'Und die Bretter überzog er mit Gold und machte ihre Ringe von Gold, als Behälter für die Riegel, und die Riegel überzog er mit Gold.',
        35: 'Und den Vorhang machte er von blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus. Als Werk des Kunstwirkers machte er es mit Cheruben;',
        36: 'Und machte dafür vier Säulen von Schittimholz und überzog sie mit Gold; ihre Nägel waren von Gold, und vier silberne Untersätze goß er für sie.',
        37: 'Und für den Eingang zum Zelt machte er eine Decke von blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus, das Werk eines Buntwirkers;',
        38: 'Und ihre fünf Säulen und ihre Nägel; und überzog ihre Köpfe und Umgürtungen mit Gold, und ihre fünf Untersätze waren von Erz.',
    },
    37: {
        1: 'Und Bezaleel machte die Lade von Schittimholz, zwei Ellen und eine halbe ihre Länge, und eine Elle und eine halbe ihre Breite und eine Elle und eine halbe ihre Höhe;',
        2: 'Und überzog sie mit reinem Gold von innen und von außen, und machte ihr einen goldenen Kranz ringsumher;',
        3: 'Und goß ihr vier goldene Ringe auf ihre vier Ecken, und zwei Ringe auf ihre eine Seitenwand und zwei auf ihre zweite Seitenwand.',
        4: 'Und er machte Stangen von Schittimholz und überzog sie mit Gold.',
        5: 'Und er brachte die Stangen in die Ringe an der Seitenwand der Lade, um die Lade zu tragen.',
        6: 'Und machte den Gnadenstuhl von reinem Gold, zwei Ellen und eine halbe ihre Länge und eine Elle und eine halbe ihre Breite.',
        7: 'Und er machte zwei Cherube von Gold, in getriebener Arbeit aus den beiden Enden des Gnadenstuhls machte er sie;',
        8: 'Einen Cherub von dem einen Ende und einen Cherub von dem anderen Ende an dem Gnadenstuhl machte er die Cherube aus seinen zwei Enden.',
        9: 'Und die Cherube breiteten die zwei Flügel darüber aus und deckten den Gnadenstuhl mit ihren Flügeln, und ihre Angesichter waren gegeneinander; zu dem Gnadenstuhl waren die Angesichter der Cherube.',
        10: 'Und den Tisch machte er von Schittimholz, zwei Ellen seine Länge und eine Elle seine Breite und eine Elle und eine halbe seine Höhe.',
        11: 'Und er überzog ihn mit reinem Gold, und machte ihm einen goldenen Kranz ringsum.',
        12: 'Und er machte eine Randleiste an ihm ringsumher eine Hand breit, und einen goldenen Kranz machte er an seine Randleiste ringsumher;',
        13: 'Und goß für ihn vier goldene Ringe, und tat die Ringe an die vier Ecken, die bei seinen vier Füßen sind.',
        14: 'Zunächst der Randleiste waren die Ringe, als Behälter für die Stangen, den Tisch damit zu tragen.',
        15: 'Und die Stangen machte er aus Schittimholz und überzog sie mit Gold, um den Tisch zu tragen.',
        16: 'Und er machte die Gefäße auf den Tisch, seine Schüsseln und seine Platten, und seine Becher und die Trankopferschalen, womit er gedeckt wird, aus reinem Gold.',
        17: 'Und den Leuchter machte er von reinem Gold; in getriebener Arbeit machte er den Leuchter, sein Schaft und seine Röhre, seine Kelche, seine Knäufe und seine Blumen sollen aus ihm sein.',
        18: 'Und sechs Röhren gingen von seinen Seiten aus; drei Röhren des Leuchters von seiner einen Seite, und drei Röhren des Leuchters von seiner zweiten Seite;',
        19: 'Drei mandelblütförmige Kelche waren an der einen Röhre, Knauf und Blume, und drei mandelblütförmige Kelche an der anderen Röhre, Knauf und Blume; so bei den sechs Röhren, die von dem Leuchter ausgingen.',
        20: 'Und an dem Leuchter waren vier mandelblütförmige Kelche, seine Knäufe und seine Blumen;',
        21: 'Und ein Knauf war unter zwei Röhren aus ihm, und ein Knauf unter zwei Röhren aus ihm, und ein Knauf unter zwei Röhren aus ihm, für die sechs Röhren, die aus ihm ausgingen;',
        22: 'Ihre Knäufe und ihre Röhren waren aus ihm, sein Ganzes war ein Getriebenes aus reinem Gold.',
        23: 'Und er machte seine sieben Lampen, und seine Lichtputzen und seine Löschnäpfe von reinem Gold.',
        24: 'Aus einem Talent reinen Goldes machte er ihn und all seine Geräte.',
        25: 'Und er machte den Räuchaltar von Schittimholz, eine Elle seine Länge, und eine Elle seine Breite ins Gevierte, und zwei Ellen hoch. Aus ihm waren seine Hörner.',
        26: 'Und er überzog ihn mit reinem Gold, sein Dach und seine Wände ringsum und seine Hörner, und machte ihm einen Kranz von Gold ringsumher;',
        27: 'Und zwei Ringe von Gold machte er ihm unter seinen Kranz an seinen beiden Seitenwänden, an seinen Seiten, als Behälter für die Stangen, um ihn damit zu tragen.',
        28: 'Und die Stangen machte er von Schittimholz und überzog sie mit Gold.',
        29: 'Und machte das heilige Salböl und reines Räucherwerk der Spezereien, ein Werk des Salbenmischers.',
    },
    38: {
        1: 'Und er machte den Brandopferaltar aus Schittimholz, fünf Ellen seine Länge, und fünf Ellen seine Breite ins Gevierte, und drei Ellen seine Höhe;',
        2: 'Und machte seine Hörner auf seine vier Ecken; aus ihm selbst waren seine Hörner, und er überzog ihn mit Erz.',
        3: 'Und er machte alle Geräte des Altars: die Töpfe und die Schaufeln und Sprengbecken, die Fleischgabeln und die Kohlpfannen; alle seine Gerätschaften machte er von Erz;',
        4: 'Und machte am Altar ein Gitter, ein Netzwerk von Erz, unter seiner Einfassung, von unten auf bis an die Mitte desselben;',
        5: 'Und goß vier Ringe an die vier Enden des ehernen Gitters, als Behälter für die Stangen.',
        6: 'Und die Stangen machte er von Schittimholz und überzog sie mit Erz;',
        7: 'Und brachte die Stangen in die Ringe an den Seitenwänden des Altars, diesen damit zu tragen; hohl, von Brettern machte er ihn.',
        8: 'Und das Becken machte er von Erz, und sein Gestell von Erz in Sicht der Ausdrückenden, die da ausdrückten vor den Eingang des Versammlungszeltes;',
        9: 'Und machte den Vorhof zur Mittagsecke südwärts, die Umhänge des Vorhofs von gezwirntem Byssus hundert Ellen;',
        10: 'Ihre zwanzig Säulen und deren zwanzig Untersätze von Erz; die Nägel der Säulen und deren Umgürtungen von Silber.',
        11: 'Und auf der Mitternachtecke hundert Ellen: ihre zwanzig Säulen, und ihre zwanzig Untersätze von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber.',
        12: 'Und auf der Abendecke fünfzig Ellen Umhänge: ihre zehn Säulen und ihre zehn Untersätze, die Nägel der Säulen und ihre Umgürtungen von Silber.',
        13: 'Und auf der Vorderecke gegen Aufgang fünfzig Ellen,',
        14: 'Fünfzehn Ellen Umhänge auf dem einen Flügel: ihre drei Säulen und ihre drei Untersätze.',
        15: 'Und auf dem zweiten Flügel hier und dort am Tor des Vorhofs fünfzehn Ellen Umhänge, ihre drei Säulen und ihre drei Untersätze.',
        16: 'Alle Umhänge des Vorhofs ringsum von gezwirntem Byssus;',
        17: 'Und die Untersätze zu den Säulen von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber, und der Überzug ihrer Köpfe von Silber, und waren dieselben mit Silber umgürtet, alle Säulen des Vorhofs.',
        18: 'Und die Decke am Tor des Vorhofs war Buntwirkerarbeit von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus, und zwanzig Ellen lang und bei fünf Ellen hoch, in der Breite gemäß den Umhängen des Vorhofs.',
        19: 'Und ihre vier Säulen und ihre vier Untersätze waren von Erz; ihre Nägel von Silber, und deren Köpfe und Umgürtungen mit Silber überzogen.',
        20: 'Und alle Pflöcke für die Wohnung und für den Vorhof ringsum waren von Erz.',
        21: 'Das ist die Musterung für die Wohnung, die Wohnung des Zeugnisses, die gemustert wurden nach Moses Befehl, zum Dienste der Leviten, durch die Hand Ithamars, des Sohnes Aharons, des Priesters.',
        22: 'Und Bezaleel, der Sohn Uris, des Sohnes Churs, vom Stamme Judah, machte alles, das Jehovah dem Mose geboten hatte;',
        23: 'Und mit ihm Oholiab, der Sohn Achisamachs vom Stamme Dan, Werkmann und Ausdenker und Buntwirker in blauem und rotem Purpur, und in doppelt gefärbtem Scharlach und Byssus.',
        24: 'Alles Gold, aus dem gemacht wurde die Arbeit für die ganze Arbeit des Heiligtums - und es war das Gold der Webe - war neunundzwanzig Talente und siebenhundertdreißig Schekel nach dem Schekel des Heiligtums.',
        25: 'Und das Silber der Gemusterten der Gemeinde war hundert Talente, und tausend und siebenhundertfünfundsiebzig Schekel nach dem Schekel des Heiligtums;',
        26: 'Ein Beka auf den Kopf, ein halber Schekel nach dem Schekel des Heiligtums, von einem jeden, der zu den Gemusterten überging, der zwanzig Jahre und darüber alt war, von sechsmalhundertausend und dreitausend und fünfhundertfünfzig.',
        27: 'Und von hundert Talenten Silbers goß man die Untersätze des Heiligtums und die Untersätze des Vorhangs; für hundert Untersätze hundert Talente, ein Talent für einen Untersatz.',
        28: 'Und mit den tausend und siebenhundertfünfundsiebzig machte er die Nägel für die Säulen, und überzog ihre Köpfe und umgürtete sie.',
        29: 'Und das Erz der Webe war siebzig Talente und zweitausend und vierhundert Schekel.',
        30: 'Und damit machte er die Untersätze des Eingangs zum Versammlungszelt und den ehernen Altar und das eherne Gitter daran, und alle Geräte des Altars;',
        31: 'Und die Untersätze des Vorhofs ringsum, und die Untersätze des Tores an dem Vorhof, und alle Pflöcke der Wohnung und alle Pflökke des Vorhofs ringsum.',
    },
    39: {
        1: 'Und von dem blauen und dem roten Purpur und dem doppelt gefärbten Scharlach machten sie die Dienstkleider für das Diensttun im Heiligtum, und machten die heiligen Kleider für Aharon, wie Jehovah dem Mose geboten hatte.',
        2: 'Und er machte das Ephod von Gold, blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus.',
        3: 'Und die Goldplatten schlugen sie breit, und er schnitt sie ab in Fäden, um sie inmitten des blauen und inmitten des roten Purpurs und inmitten des doppelt gefärbten Scharlach und inmitten des Byssus zu tun, mit dem Werke des Denkers.',
        4: 'Schulterstücke machten sie daran, die sich zusammenfügten, an ihren beiden Enden fügte man sie zusammen.',
        5: 'Und der Gurt zum Anlegen, der daran war, war aus ihm und wie sein Werk, von Gold, blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus, wie Jehovah dem Mose geboten hatte.',
        6: 'Und sie machten die Onychsteine, ringsum in Gold gefaßt, und sie gruben darauf, wie im Siegelstich, nach den Namen der Söhne Israels ein.',
        7: 'Und er setzte sie auf die Schulterstücke des Ephod als Gedenksteine für die Söhne Israels, wie Jehovah dem Mose geboten hatte.',
        8: 'Und das Brustschildlein machte er mit dem Werke des Kunstwirkers, wie das Werk des Ephods gemacht war, aus Gold, blauem und rotem Purpur, und doppelt gefärbtem Scharlach und gezwirntem Byssus.',
        9: 'Geviert war es, gedoppelt machten sie das Brustschildlein, eine Spanne seine Länge und eine Spanne seine Breite, gedoppelt.',
        10: 'Und sie füllten es mit vier Reihen von Steinen; eine Reihe war Rubin, Topas und Karfunkel, die erste Reihe.',
        11: 'Und die zweite Reihe: Chrysopras, Saphir und Diamant.',
        12: 'Und die dritte Reihe: Lasurstein, Achat und Amethyst.',
        13: 'Und die vierte Reihe: Tharschisch, Onych und Jaspis, ringsum mit Goldeinfassungen in ihren Füllungen.',
        14: 'Und die Steine waren nach den Namen der Söhne Israels, zwölf nach ihren Namen; wie Siegel eingegraben mit eines jeden Namen für die zwölf Stämme.',
        15: 'Und an das Brustschildlein machten sie Kettchen am Rande, Flechtwerk von reinem Gold.',
        16: 'Und sie machten zwei Einfassungen von Gold und zwei Ringe von Gold und setzten die zwei Ringe an die zwei Enden des Brustschildleins.',
        17: 'Und die zwei Geflechte von Gold taten sie in die zwei Ringe an den Enden des Brustschildleins.',
        18: 'Und die zwei Enden der zwei Geflechte taten sie in die zwei Einfassungen, und setzten sie an die Schulterstücke des Ephod auf dessen Vorderseite;',
        19: 'Und machten zwei Ringe von Gold, und setzten sie an die zwei Enden des Brustschildleins an seinen Saum, welcher gegen das Ephod zu einwärts ist.',
        20: 'Und sie machten zwei goldene Ringe, und setzten sie an die zwei Schulterstücke des Ephod von unten an seiner Vorderseite nächst der Zusammenfügung über dem Gurt des Ephod.',
        21: 'Und sie schnürten das Brustschildlein mit seinen Ringen an die Ringe des Ephod mit einer purpurblauen Schnur, so daß es über dem Gurt des Ephod war und das Brustschildlein sich nicht vom Ephod verrückte, wie Jehovah dem Mose geboten hatte.',
        22: 'Und das Oberkleid des Ephods machte er mit dem Werke des Webers, gänzlich von Purpurblau.',
        23: 'Und in der Mitte des Oberkleides eine Öffnung, gleich der Öffnung am Panzer, und eine Borte rings um die Öffnung, auf daß es nicht reiße.',
        24: 'Und an die Säume des Oberkleides machten sie Granatäpfel von blauem und rotem Purpur, und von doppelt gefärbtem Scharlach hineingewirkt.',
        25: 'Und sie machten Glöcklein von reinem Gold, und setzten die Glöcklein inmitten der Granatäpfel an die Säume des Oberkleides, ringsum inmitten der Granatäpfel.',
        26: 'Ein Glöckchen und ein Granatapfel, ein Glöckchen und ein Granatapfel ringsum an den Säumen des Oberkleides für das Diensttun, wie es Jehovah dem Mose geboten hatte;',
        27: 'Und sie machten die Leibröcke von Byssus, mit dem Werke des Webers; für Aharon und seine Söhne;',
        28: 'Und die Tiara von Byssus und den Schmuck der Kopfbünde von Byssus, und die leinenen Beinkleider von gezwirntem Byssus;',
        29: 'Und den Gürtel von gezwirntem Byssus und von blauem und rotem Purpur und doppelt gefärbtem Scharlach in des Buntwirkers Werke, wie Jehovah dem Mose geboten hatte.',
        30: 'Und sie machten das Blatt des heiligen Diadems von reinem Gold, und schrieben darauf mit der Schrift des Siegelstichs: Heiligkeit dem Jehovah!',
        31: 'Und taten daran eine Schnur von blauem Purpur, um es oben an die Tiara zu setzen, wie Jehovah dem Mose geboten hatte.',
        32: 'Und es ward der ganze Dienst an der Wohnung des Versammlungszeltes vollendet; und die Söhne Israels taten nach allem, was Jehovah dem Mose geboten hatte; also taten sie.',
        33: 'Und sie brachten die Wohnung zu Mose: das Zelt und all seine Geräte, seine Haken, seine Bretter, seine Riegel, seine Säulen und seine Untersätze;',
        34: 'Und die Decke von roten Widderfellen, und die Decke von Dachsfellen, und den Vorhang der Decke;',
        35: 'Die Lade des Zeugnisses und ihre Stangen und den Gnadenstuhl;',
        36: 'Den Tisch, alle seine Gefäße und das Schaubrot,',
        37: 'Den reinen Leuchter, seine Lampen, die Lampen zum Anordnen, und alle seine Gefäße, und das Öl der Beleuchtung;',
        38: 'Und den goldenen Altar, und das Salböl, und das Räucherwerk der Spezereien und die Decke zum Eingang des Zeltes.',
        39: 'Den ehernen Altar und sein Gitter daran von Erz, seine Stangen, und all seine Geräte, das Becken und sein Gestell.',
        40: 'Die Umhänge des Vorhofs, seine Säulen und seine Untersätze, und die Decke für das Tor des Vorhofs, seine Seile und seine Pflökke, und alle Geräte zum Dienst in der Wohnung für das Versammlungszelt.',
        41: 'Dienstkleider für das Diensttun im Heiligtum, die heiligen Kleider für Aharon, den Priester, und die Kleider für seine Söhne zum Priesterdienst.',
        42: 'Nach allem, was Jehovah dem Mose geboten hatte, also taten die Söhne Israels allen Dienst.',
        43: 'Und Mose sah all das Werk, und siehe, sie hatten es gemacht, wie Jehovah geboten hatte, also hatten sie es gemacht, und Mose segnete sie.',
    },
    40: {
        1: 'Und Jehovah redete zu Mose und sprach:',
        2: 'Am Tage des ersten Monats, am ersten des Monats sollst du die Wohnung des Versammlungszeltes aufrichten,',
        3: 'Und darein die Lade des Zeugnisses setzen, und über die Lade den Vorhang dekken.',
        4: 'Und den Tisch hereinbringen, und anordnen seine Anordnung: und sollst den Leuchter hereinbringen und seine Lampen aufstecken;',
        5: 'Und den goldenen Räuchaltar vor die Lade des Zeugnisses stellen, und den Vorhang des Eingangs an die Wohnung setzen;',
        6: 'Und den Brandopferaltar vor den Eingang zur Wohnung des Versammlungszeltes setzen;',
        7: 'Und das Becken zwischen das Versammlungszelt und zwischen den Altar stellen und Wasser darein tun.',
        8: 'Und setze den Vorhof ringsum, und tue die Decke an das Tor des Vorhofs.',
        9: 'Und nimm das Salböl und salbe die Wohnung und alles, was in ihr ist, und heilige sie und all ihr Gerät, und sie sei ein Heiligtum.',
        10: 'Und du sollst den Brandopferaltar salben und alle seine Geräte, und den Altar heiligen, auf daß der Altar allerheiligst sei.',
        11: 'Und du sollst das Becken und sein Gestell salben und es heiligen.',
        12: 'Und laß Aharon und seine Söhne sich nahen dem Eingang des Versammlungszeltes, und wasche sie mit dem Wasser;',
        13: 'Und ziehe dem Aharon die heiligen Kleider an und salbe ihn und heilige ihn, auf daß er Mir Priesterdienst tue.',
        14: 'Und laß seine Söhne sich nahen, und ziehe ihnen die Leibröcke an;',
        15: 'Und salbe sie, wie du ihren Vater gesalbt hast, daß sie Mir Priesterdienst tun, und es soll ihnen ihre Salbung zu ewigem Priestertum werden in ihren Geschlechtern.',
        16: 'Und Mose tat nach allem, das ihm Jehovah geboten hatte; also tat er.',
        17: 'Und es geschah im ersten Monat im zweiten Jahr, am ersten des Monats, daß die Wohnung aufgerichtet wurde.',
        18: 'Und Mose richtete die Wohnung auf, und er setzte ihre Untersätze und stellte ihre Bretter, und tat ihre Riegel daran und richtete ihre Säulen auf.',
        19: 'Und er breitete das Zelt aus über die Wohnung, und legte die Decke des Zeltes oben darüber, wie Jehovah dem Mose geboten hatte.',
        20: 'Und er nahm das Zeugnis und tat es in die Lade, und legte die Stangen an die Lade und setzte den Gnadenstuhl oben auf die Lade;',
        21: 'Und brachte die Lade in die Wohnung, und tat den Vorhang der Decke davor und bedeckte die Lade des Zeugnisses, wie Jehovah Mose geboten hatte.',
        22: 'Und den Tisch stellte er in das Versammlungszelt an die Seite der Wohnung gegen Mitternacht außerhalb des Vorhangs;',
        23: 'Und ordnete darauf die Anordnung des Brotes vor Jehovah, wie Jehovah dem Mose geboten hatte.',
        24: 'Und den Leuchter stellte er in das Versammlungszelt gerade gegenüber dem Tisch zur Seite der Wohnung gegen Mittag;',
        25: 'Und steckte die Lampen auf vor Jehovah, wie dem Mose Jehovah geboten hatte.',
        26: 'Und den goldenen Altar setzte er in das Versammlungszelt vor den Vorhang;',
        27: 'Und räucherte darauf mit dem Räuchwerk der Spezereien, wie Jehovah dem Mose geboten hatte.',
        28: 'Und vor den Eingang zur Wohnung tat er die Decke.',
        29: 'Und den Brandopferaltar setzte er an den Eingang zur Wohnung des Versammlungszeltes, und ließ darauf das Brandopfer und das Speiseopfer aufgehen, wie Jehovah dem Mose geboten hatte.',
        30: 'Und das Becken setzte er zwischen das Versammlungszelt und zwischen den Altar und tat Wasser darein zum Waschen.',
        31: 'Und Mose und Aharon und seine Söhne wuschen sich ihre Hände und ihre Füße daraus.',
        32: 'Wenn sie in das Versammlungszelt eingingen und dem Altare nahten, wuschen sie sich, wie Jehovah dem Mose geboten hatte.',
        33: 'Und er richtete rings um die Wohnung und den Altar den Vorhof auf und in das Tor des Vorhofs tat er die Decke; und Mose vollendete das Werk.',
        34: 'Und die Wolke bedeckte das Versammlungszelt, und die Herrlichkeit Jehovahs füllte die Wohnung.',
        35: 'Und Mose vermochte nicht in das Versammlungszelt einzugehen; denn die Wolke lagerte darauf, und die Herrlichkeit Jehovahs füllte die Wohnung.',
        36: 'Und wenn die Wolke aufstieg von der Wohnung, brachen die Söhne Israels auf allen ihren Zügen auf.',
        37: 'Und wenn die Wolke nicht aufstieg, so brachen sie nicht auf, bis zu dem Tage, da sie aufstieg.',
        38: 'Denn bei Tag war die Wolke Jehovahs über der Wohnung, und bei Nacht war Feuer darin vor den Augen des ganzen Hauses Israel auf allen ihren Zügen.',
    },
}
